COLLDATA("tafsirnoor","ur",[[4537,"§ایمان داروں کے اوصاف حمیدہ کا بیان\nاے ایمان والو! جنھوں نے اللہ تعالیٰ اور اس کے پیغمبر علیہ السلام کو تسلیم کیا ہے تم خود کو اللہ تعالیٰ کی ذات کے سامنے جھکا دو اورا س کی عبادت کرو اور اچھے کام کرو جن کے کرنے کا تم کو اللہ تعالیٰ نے حکم دیا ہے صلہ رحمی اختیار کرو، اچھے اخلاق کواپناؤ تمھیں کامیابی حاصل ہوگی اور اللہ تعالیٰ کی راہ میں خالص اللہ تعالیٰ کی خوشنودی کے حصول کے لیے جہاد کرو کسی ملامت کرنے والے کی ملامت سے خوف نہ رکھو اللہ تعالیٰ نے تمام امتوں میں سے تمھیں منتخب کیا ہے اور بالخصوص تمھاری جانب خاتم النّبیین محمد صلی اللہ علیہ وسلم کو بھیجا جو تمام پیغمبروں علیہم السلام سے افضل اور کامل شریعت لائے ہیں اللہ تعالیٰ نے دین اسلام میں ہر گز تنگی کو روا نہیں رکھا ہے۔تَوَسُّع عطاکی ہے گناہ کے بعدتوبہ کرنے سے گناہ دھل جاتا ہے مزید دین اسلام میں تنگی نہیں ہے۔"],[4538,"§مومنوں کی صفات\n﴿قَدْ اَفْلَحَ الْمُؤْمِنُوْنَۙ۰۰۱ الَّذِيْنَ هُمْ فِيْ صَلَاتِهِمْ خٰشِعُوْنَۙ۰۰۲ وَ الَّذِيْنَ هُمْ عَنِ اللَّغْوِ مُعْرِضُوْنَۙ۰۰۳ وَ الَّذِيْنَ هُمْ لِلزَّكٰوةِ فٰعِلُوْنَۙ۰۰۴ وَ الَّذِيْنَ هُمْ لِفُرُوْجِهِمْ حٰفِظُوْنَۙ۰۰۵ اِلَّا عَلٰۤى اَزْوَاجِهِمْ اَوْ مَا مَلَكَتْ اَيْمَانُهُمْ فَاِنَّهُمْ غَيْرُ مَلُوْمِيْنَۚ۰۰۶ فَمَنِ ابْتَغٰى وَرَآءَ ذٰلِكَ فَاُولٰٓىِٕكَ هُمُ الْعٰدُوْنَۚ۰۰۷ وَ الَّذِيْنَ هُمْ لِاَمٰنٰتِهِمْ وَ عَهْدِهِمْ رٰعُوْنَۙ۰۰۸ وَ الَّذِيْنَ هُمْ عَلٰى صَلَوٰتِهِمْ يُحَافِظُوْنَۘ۰۰۹ اُولٰٓىِٕكَ هُمُ الْوٰرِثُوْنَۙ۰۰۱۰ الَّذِيْنَ يَرِثُوْنَ الْفِرْدَوْسَ١ؕ هُمْ فِيْهَا خٰلِدُوْنَ۰۰۱۱﴾\nاللہ کے نام سے (شروع) جو نہایت مہربان، بہت رحم کرنے والا ہے۔\nمومن یقیناً فلاح پا گئے1 وہ جو اپنی نماز میں عاجزی کرنے والے ہیں2 اور وہ جو لغو باتوں سے اعراض کرنے والے ہیں3 اور وہ جو زکاۃ ادا کرنے والے ہیں4 اور وہ جو اپنی شرم گاہ کی حفاظت کرنے والے ہیں5 سوائے اپنی بیویوں یا ان (کنیزوں) کے جن کے مالک ہوئے ان کے دائیں ہاتھ، تو بلاشبہ (ان کی بابت) ان پر کوئی ملامت نہیں6 پھر جو شخص ان کے علاوہ (رستہ) تلاش کرے تو ایسے لوگ ہی حد سے گزرنے والے ہیں7 اور وہ جو اپنی امانتوں اور اپنے عہد کی حفاظت کرنے والے ہیں8 اور وہ جو اپنی نمازوں کی حفاظت کرتے ہیں9 یہی لوگ وارث ہیں0 جو فردوس کے وارث ہوں گے، وہ اس\nمیں ہمیشہ رہیں گے!\nارشاد باری تعالیٰ ہے: ﴿قَدْ اَفْلَحَ الْمُؤْمِنُوْنَ﴾’’بے شک ایمان والے کامیاب ہوگئے۔‘‘ یعنی کامیاب و کامران ہوگئےا ور انہوں نے سعادت و فلاح کو حاصل کرلیا اور مومن وہ ہیں جو ان اوصاف کے ساتھ متصف ہیں۔"],[4539,"§عجز و نیاز کے پیکر\n﴿الَّذِيْنَ هُمْ فِيْ صَلَاتِهِمْ خٰشِعُوْنَ﴾ ’’جو اپنی نماز میں عجز و نیاز کرنے والے ہیں۔‘‘ علی بن ابوطلحہ رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ﴿خٰشِعُوْنَ﴾ کے معنی ہیں ڈرنے والے اور سکون اختیار کرنے والے۔ (تفسیر الطبری : 6/18) مجاہد، حسن قتادہ اور زہری رحمہ اللہ سے بھی اسی طرح مروی ہے۔ (الطبری : 4/18۔6) علی بن ابوطالب رضی اللہ عنہ سے روایت ہے کہ خشوع دل کے عجز و انکسار کا نام ہے۔ (تفسیر الطبری : 5/18) ابراہیم نخعی رحمہ اللہ کا بھی یہی قول ہے۔(تفسیر الطبری : 5/18) حسن بصری رحمہ اللہ فرماتے ہیں کہ خشوع ان کے دلوں میں تھا جس کی وجہ سے انہوں نے اپنی آنکھیں نیچی کر لیں اور پہلوئوں کو جھکا لیا۔ نماز میں خشوع اسے حاصل ہو سکتا ہے جس کا دل نماز کے لیے فارغ ہو چکا ہو، ماسوا سے منقطع ہو کر نماز ہی میں مشغول ہو گیا ہو اور نماز کو دوسرے کاموں پر ترجیح دیتا ہو تو اسی صورت میں نماز اس کے لیے راحت اور آنکھوں کی ٹھنڈک کا باعث ثابت ہوتی ہے جیسا کہ نبی صلی اللہ علیہ وسلم نے اس حدیث میں فرمایا ہے جسے امام احمد اور نسائی رحمہ اللہ نے سیّدنا انس رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((حُبِّبَ اِلَیَّ النِّسَائُ، وَالطِّیبُ، وَجُعِلَتْ قُرَّۃُ عَیْنِی فِی الصَّلَاۃِ)) ’’مجھے خوشبو اور عورتوں سے محبت ہے اور نماز میں میری آنکھوں کی ٹھنڈک بنا دی گئی ہے۔‘‘"],[4540,"§لغویات سے پرہیز\nاور فرمایا: ﴿وَ الَّذِيْنَ هُمْ عَنِ اللَّغْوِ مُعْرِضُوْنَۙ۰۰۳﴾ ’’اور وہ جو بے ہودہ باتوں سے اعراض کرنے والے ہیں۔‘‘ یعنی باطل سے اور یہ لفظ شرک، گناہوں اور ایسے تمام اقوال و افعال پر مشتمل ہے جو بے فائدہ ہوں جیسا کہ فرمایا: ﴿وَ اِذَا مَرُّوْا بِاللَّغْوِ مَرُّوْا كِرَامًا۰۰۷۲﴾ (الفرقان : 72) ’’اور جب ان کا بے ہودہ چیزوں سے گزر ہو تو وہ عزت و وقار سے گزرتے ہیں۔‘‘ قتادہ رحمہ اللہ کہتے ہیں کہ ان کے پاس اللہ تعالیٰ کا حکم آیا ہے، اس لیے اس نے انہیں لغو اور باطل امور سے بچا لیا ہے۔(تفسیر الطبری : 111/20)"],[4541,"§مال و جان کا تزکیہ کرنے والے\n﴿وَ الَّذِيْنَ هُمْ لِلزَّكٰوةِ فٰعِلُوْنَۙ۰۰۴﴾ ’’اور جو زکاۃ ادا کرنے والے ہیں۔‘‘ اکثر مفسرین کا خیال ہے کہ زکاۃ سے یہاں مالوں کی زکاۃ مراد ہے، حالانکہ یہ آیت مکی ہے جبکہ زکاۃ 2ھ میں مدینہ منورہ میں فرض ہوئی تھی لیکن بظاہر یوں معلوم ہوتا ہے کہ مدینہ میں زکاۃ مخصوص نصاب کے ساتھ فرض ہوئی تھی ورنہ اصل میں زکاۃ مکہ مکرمہ میں بھی واجب تھی جیسا کہ اللہ تعالیٰ نے سورۂ انعام میں فرمایا جو کہ مکی سورت ہے: ﴿وَ اٰتُوْا حَقَّهٗ يَوْمَ حَصَادِهٖ١ۖٞ﴾ (الانعام : 141) ’’اور جس دن (پھل توڑو اور کھیتی) کاٹو اللہ کا حق بھی اس میں سے ادا کرو۔‘‘ اس بات کا بھی احتمال ہے کہ زکاۃ سے یہاں نفس کو شرک کے میل کچیل سے پاک کرنا مراد ہو جیسا کہ فرمایا: ﴿قَدْ اَفْلَحَ مَنْ زَكّٰىهَا۪ۙ۰۰۹ وَ قَدْ خَابَ مَنْ دَسّٰىهَاؕ۰۰۱۰﴾ (الشمس : 10,9) ’’جس نے (اپنے) نفس (روح) کو پاک رکھا، یقیناً وہ مراد کو پہنچا اور جس نے اسے خاک میں ملا دیا، بلاشبہ وہ خسارے میں رہا۔‘‘ اور اس بات کا بھی احتمال ہے کہ یہاں دونوں باتیں مراد ہوں، نفوس کا تزکیہ بھی اور مالوں کی زکاۃ بھی کیونکہ اموال کی زکاۃ بھی نفوس کی زکاۃ میں شامل ہے اور مومن کامل وہ ہے جو ان میں سے ہر قسم کی زکاۃ ادا کرتا ہو۔ واللہ اعلم!"],[4542,"§فحاشی کے منکر\nاور فرمایا: ﴿وَ الَّذِيْنَ هُمْ لِفُرُوْجِهِمْ حٰفِظُوْنَۙ۰۰۵ ِلَّا عَلٰۤى اَزْوَاجِهِمْ اَوْ مَا مَلَكَتْ اَيْمَانُهُمْ فَاِنَّهُمْ غَيْرُ مَلُوْمِيْنَۚ۰۰۶ فَمَنِ ابْتَغٰى وَرَآءَ ذٰلِكَ فَاُولٰٓىِٕكَ هُمُ الْعٰدُوْنَۚ۰۰۷﴾ ’’اور وہ جو اپنی شرم گاہوں کی حفاظت کرنے والے ہیں مگر اپنی بیویوں سے یا جن (لونڈیوں) کے مالک ہوئے ان کے دائیں ہاتھ تو بلاشبہ (ان کی بابت) انہیں کوئی ملامت نہیں، پھر جو ان کے علاوہ (رستہ) تلاش کرے تو ایسے لوگ ہی (اللہ کی مقرر کی ہوئی) حد سے نکل جانے والے ہیں۔‘‘ یعنی مومن وہ ہیں جو حرام کاموں سے اپنی شرم گاہوں کی حفاظت کرتے ہیں اور اللہ تعالیٰ نے زنا اور لواطت کو حرام قرار دیا ہے، اس لیے وہ ان کا ارتکاب نہیں کرتے اور سوائے اپنی بیویوں اور کنیزوں کے جنہیں اللہ تعالیٰ نے ان کے لیے حلال قرار دیا ہے تو اس پر کوئی ملامت نہیں اور حلال سے استفادے میں کوئی حرج نہیں، اسی لیے فرمایا: انہیں ملامت نہیں اور جو بیویوں اور کنیزوں کے سوا اوروں کے طالب ہوں۔ ﴿فَاُولٰٓىِٕكَ هُمُ الْعٰدُوْنَۚ۰۰۷﴾ ’’تو وہ (اللہ کی مقرر کی ہوئی) حد سے نکل جانے والے ہیں۔‘‘"],[4543,"§وعدوں کے پاس دار اور امین لوگ\nاور اللہ تعالیٰ کا فرمان ہے: ﴿وَ الَّذِيْنَ هُمْ لِاَمٰنٰتِهِمْ وَ عَهْدِهِمْ رٰعُوْنَۙ۰۰۸﴾ ’’اور وہ جو اپنی امانتوں اور اقراروں کو ملحوظ رکھنے والے ہیں۔‘‘ یعنی جب ان کے پاس امانت رکھی جائے تو وہ اس میں خیانت نہیں کرتے بلکہ اسے اس کے مالک کو ادا کر دیتے ہیں اور جب وہ کوئی عہد و پیمان کریں تو اسے پورا کرتے ہیں، ان کی صفات منافقوں کی صفات کے برعکس ہیں کیونکہ منافقوں کے بارے میں تو رسول اللہ صلی اللہ علیہ وسلم نے یہ فرمایا ہے: ((آیَۃُ الْمُنَافِقِ ثَلَاثٌ: اِذَا حَدَّثَ کَذَبَ، وَاِذَا وَعَدَ أَخْلَفَ، وَاِذَا ائْتُمِنَ خَانَ)) ’’منافق کی تین نشانیاں ہیں: (1) جب بات کرے تو جھوٹ بولے، (2) اور جب وعدہ کرے تو اس کی خلاف ورزی کرے، (3) اور جب اس کے پاس امانت رکھی جائے تو اس میں خیانت کرے۔ (صحیح البخاری، حدیث : 33 و صحیح مسلم، حدیث: 59)"],[4544,"§بندگی کے محافظ\nاور فرمایا: ﴿وَ الَّذِيْنَ هُمْ عَلٰى صَلَوٰتِهِمْ يُحَافِظُوْنَۘ۰۰۹﴾ ’’اور وہ جو اپنی نمازوں کی حفاظت کرتے ہیں۔‘‘ یعنی انہیں ان کے اوقات مقررہ میں ادا کرتے ہیں جیسا کہ ابن مسعود رضی اللہ عنہ نے یہاں کہا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں عرض کی: یا رسول اللہ! کون سا عمل اللہ تعالیٰ کو سب سے زیادہ پسند ہے؟ آپ نے فرمایا: ((اَلصَّلَاۃُ عَلٰی وَقْتِھَا)) ’’نماز وقت پر ادا کرنا۔‘‘ میں نے عرض کی: پھر کون سا؟ فرمایا: ((ثُمَّ بِرُّ الْوَالِدَیْنِ)) ’’پھر والدین کے ساتھ حسن سلوک کرنا۔‘‘ پھر کون سا؟ فرمایا: ((اَلْجِھَادُ فِی سَبِیْلِ اللہِ)) ’’اللہ کے رستے میں جہاد کرنا۔‘‘ (صحیح البخاری، حدیث : 5970 وصحیح مسلم، حدیث : 85) قتادہ فرماتے ہیں کہ اس کے معنی یہ ہیں کہ وہ نماز کے اوقات کی بہت حفاظت کرتے ہیں اور نماز میں رکوع و سجود کا بھی پورا پورا خیال رکھتے ہیں۔\n(زاد المسیر لابن الجوزی : 21/1 و الدر المنثور : 9/5)\nاللہ تعالیٰ نے اس مقام پر مومنوں کی ان کی صفات حمیدہ کا آغاز بھی نماز سے کیا اور اس کا اختتام بھی نماز پر کیا، یہ نماز کی افضلیت کی دلیل ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((اِسْتَقِیْمُوا وَلَنْ تُحْصُوا، وَاعْلَمُوْا اَنَّ خَیْرَ اَعْمَالِکُمْ الصَّلَاۃُ، وَلَا یُحَافِظُ عَلَی الْوُضُوْئِ اِلَّا مُؤمِنٌ)) ’’سیدھے رستے پر رہو، تم ہرگز طاقت نہیں رکھ سکو گے اور خوب جان لو کہ تمہارے اعمال میں سب سے بہتر نماز ہے اور وضو کی حفاظت صرف مومن ہی کر سکتا ہے۔‘‘\n(سنن ابن ماجہ، الطہارۃ حدیث : 277 و مسند احمد)"],[4545,"§فردوس بریں کے وارث\nاللہ تعالیٰ نے جب مومنوں کے بارے میں یہ فرمایا کہ وہ ان صفات حمیدہ سے اتصاف پذیر ہیں اور ان نیک افعال کو بجا لاتے ہیں تو فرمایا: ﴿اُولٰٓىِٕكَ هُمُ الْوٰرِثُوْنَۙ۰۰۱۰ الَّذِيْنَ يَرِثُوْنَ الْفِرْدَوْسَ١ؕ هُمْ فِيْهَا خٰلِدُوْنَ۰۰۱۱﴾ ’’یہی لوگ وارث ہیں (یعنی) جو فردوس کے وارث ہوں گے (اور) اس میں ہمیشہ رہیں گے۔‘‘ صحیحین میں حدیث ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((فَاِذَا سَاَلْتُمُ اللہَ (فَاسْئَلُوْہُ) الْفِرْدَوْسَ، فَاِنَّہٗ اَوْسَطُ الْجَنَّۃِ وَأَعْلَی الْجَنَّۃِ، وَفَوْقَہٗ عَرْشُ الرَّحْمٰنِ وَمِنْہُ تَفَجَّرُ اَنْھَارُ الْجَنَّۃِ)) ’’جب تم اللہ تعالیٰ سے جنت کا سوال کرو تو اس سے فردوس کا سوال کرو کیونکہ وہ سب سے اعلیٰ اور افضل جنت ہے اوراسی کے اوپر رحمان کا عرش ہے، اسی سے جنت کی نہریں پھوٹتی ہے۔‘‘\n(صحیح البخاری، حدیث : 7423)\nابن ابو حاتم نے ابوہریرہ رضی اللہ عنہ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((مَا مِنْکُمْ مِّنْ أَحَدٍ اِلَّا لَہٗ مَنْزِلَانِ: مَنْزِلٌ فِی الْجَنَّۃِ، وَمَنْزِلٌ فِی النَّارِ، فَاِذَا مَاتَ، فَدَخَلَ النَّارَ، وَرِثَ اَھْلُ الْجَنَّۃِ مَنْزِلَہٗ، فَذٰلِکَ قَوْلُہٗ تَعَالٰی: ﴿اُولٰٓىِٕكَ هُمُ الْوٰرِثُوْنَۙ۰۰۱۰﴾ ’’یہی لوگ وارث ہوں گے۔‘‘ (سنن ابن ماجہ، حدیث : 4341)\n﴿اُولٰٓىِٕكَ هُمُ الْوٰرِثُوْنَۙ۰۰۱۰﴾ ’’یہی لوگ وارث ہوں گے۔‘‘ ابن جریج رحمہ اللہ نے لیث رحمہ اللہ سے اور انہوں نے مجاہد سے روایت کیا ہے کہ اس آیت کے معنی یہ ہیں کہ مومن کافروں کے گھروں کے وارث بن جائیں گے کیونکہ وہ اللہ وحدہ لا شریک کی عبادت کے لیے پیدا کیے گئے ہیں جب مومنوں نے فریضہ عبادت ادا کیا اور کافروں نے اپنے فرض کو ترک کر دیا تو مومنوں نے کافروں کے جنت میں اس حصے کو بھی حاصل کر لیا جو اطاعت بجا لانے کی صورت میں کافروں کو ملنا تھا۔ (تفسیر الطبری : 10/18) بلکہ اس سے بھی بڑھ کر وہ بات ہے جو صحیح مسلم میں ابو بردہ رضی اللہ عنہ سے اور ان کی اپنے والد سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ((یَجِیءُ یَوْمَ القَیَامَۃِ نَاسٌ مِّنَ الْمُسْلِمِیْنَ بِذُنُوْبٍ اَمْثَالِ الْجِبَالِ، فَیَغْفِرُھَا اللہُ لَہُمْ، وَیَضَعُھَا عَلَی الْیَہُودِ وَالنَّصَارٰی) ’’قیامت کے دن کچھ مسلمان پہاروں جیسے گناہ لے کر آئیں گے، اللہ تعالیٰ ان کے ان گناہوں کو معاف فرما دے گا اور انہیں یہود و نصاریٰ پر رکھ دے گا۔‘‘ (صحیح مسلم، حدیث : (51)۔2767) ایک اور روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((اِذَا کَانَ یَوْمُ الْقِیَامَۃِ، دَفَعَ اللہُ عَزَّوَجَلَّ اِلٰی کُلِّ مُسْلِمٍ یَّہُوْدِیًّا اَوْ نَصْرَانِیًّا، فَیَقُوْلُ: ہٰذَا فَکَاکُکَ مِنَ النَّارِ)) ’’جب قیامت کا دن ہوگا تو اللہ تعالیٰ ہر مسلمان کے سپرد ایک یہودی یا عیسائی کر دے گا اور فرمائے گا کہ یہ ہے جہنم سے تیری رہائی (کا بدلہ)۔‘‘ سیّدنا عمر بن عبدالعزیز رحمہ اللہ نے ابو بردہ رحمہ اللہ سے تین بار قسم لی کہ اس اللہ کی قسم کھائو جس کے سوا کوئی معبود نہیں کہ تمہارے باپ نے تمہیں اسے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا تھا۔ ابو بردہ رحمہ اللہ نے قسم کھائی۔ یہ آیت اس طرح ہے جیسے درج ذیل آیت کریمہ ہے: ﴿تِلْكَ الْجَنَّةُ الَّتِيْ نُوْرِثُ مِنْ عِبَادِنَا مَنْ كَانَ تَقِيًّا۰۰۶۳﴾ (مریم: 63) ’’یہی وہ جنت ہے جس کا ہم اپنے بندوں میں سے ایسے شخص کو مالک بنائیں گے جو پرہیزگار ہوگا۔‘‘ اور اس قول کی طرح: ﴿وَتِلْكَ الْجَنَّةُ الَّتِيْۤ اُوْرِثْتُمُوْهَا بِمَا كُنْتُمْ تَعْمَلُوْنَ﴾ (الزخرف: 72) ’’اور یہی وہ جنت ہے جس کے تم مالک بنا دیے گئے ہو ان اعمال کے بدلے میں جو تم کرتے رہے۔‘‘\nیہ اللہ تعالیٰ کی طرف سے اپنے مومن بندوں کی تعریف و تعظیم اور ان کی فلاح و سعادت کا ذکر ہے، نیز اس امر کا بیان ہے کہ وہ فلاح و سعادت کیسے حاصل کر سکتے ہیں اور اس ضمن میں اہل ایمان کو ترغیب دی گئی ہے کہ وہ اپنے آپ کو ان مذکورہ صفات سے متصف کریں۔ پس بندۂ مومن ان آیات کی میزان پر اپنے آپ کا وزن کرے، اور یہ معلوم کرے کہ اس کے پاس اور دوسروں کے پاس قلت و کثرت یا اضافے اور کمی کے اعتبار سے کتنا ایمان ہے۔ پس فرمایا: ﴿قَدْ اَفْلَحَ الْمُؤْمِنُوْنَ﴾ یعنی اہل ایمان کامیابی اور سعادت سے بہرہ مند ہوئے اور انہوں نے ہر وہ چیز حاصل کر لی جس کا حصول اہل ایمان کا مقصود و مطلوب ہے جو اللہ تعالیٰ پر ایمان لائے اور انہوں نے انبیاء و مرسلین کی تصدیق کی جن کی صفات کاملہ میں سے ایک صفت یہ ہے کہ بلاشبہ وہ ﴿فِیْ صَلَاتِھِمْ خٰشِعُوْنَ﴾ ’’اپنی نماز میں خشوع اختیار کرتے ہیں۔‘‘ نماز میں خشوع یہ ہے کہ بندے کا دل اللہ تعالیٰ کو قریب سمجھتے ہوئے اس کے حضور حاضر ہو… اس سے قلب کو سکون اور اطمینان حاصل ہوتا ہے، اس کی تمام حرکات ساکن اور غیر اللہ کی طرف اس کا التفات کم ہو جاتا ہے۔ وہ اپنے رب کے سامنے نہایت ادب کے ساتھ کھڑا ہوتا ہے، وہ اپنی نماز کے اندر، اول سے لے کر آخر تک جو کچھ کرتا ہے اور جو کچھ کہتا ہے پورے استحضار کے ساتھ کہتا ہے۔ اس طرح اس کے دل سے تمام وسوسے اور غلط افکار زائل ہو جاتے ہیں۔ یہی نماز کی روح اور یہی اس سے مقصود ہے اور یہی وہ مقصد ہے جو بندے کے لیے لکھ دیا گیا ہے۔ پس وہ نماز جو خشوع و خضوع اور حضور قلب سے خالی ہو اس پر اگرچہ ثواب ملتا ہے مگر صرف اتنا ملتا ہے جتنا قلب اس کو سمجھ کر ادا کرتا ہے۔"],[4546,"§افلح کا مفہوم\nافلح (مادہ… ف ل ح) میں تین باتیں بنیادی طور پر پائی جاتی ہیں: (1) پھاڑنا (2) کامیابی اور (3) بقا (مقائیس اللغۃ) اور فلّاح بمعنی کسان جو بیج بونے کے لیے زمین کو پھاڑتا، فصل پکنے پر کامیابی سے ہمکنار ہوتا اور اس سے فائدہ اٹھانے پر اپنی مراد پاتا ہے۔ گویا افلح کے معنی ایسا کامیاب ہونا ہے جو کسی کے اپنے عمل اور محنت کے نتیجہ میں ہو۔"],[4547,"§کامیابی کے لیے مومنوں کی چھ صفات\nیہ سورت بالاتفاق مکی ہے اور اس دور میں نازل ہوئی جب مسلمانوں کے کامیاب ہونے کا تصور بھی محال تھا اور ان پر عرصہ حیات بھی تنگ کر دیا گیا تھا اور اگر اسلام لانے سے پہلے کسی مسلمان کا کوئی کاروبار یا شغل تھا بھی تو اسلام لانے کےبعد وہ ختم ہو چکا تھا۔ دوسری طرف قریش مکہ تھے جن کے ہاں مال و دولت کی ریل پیل تھی۔ تجارت ان کے ہاتھ میں تھی اور صاحب اختیار و اقتدار تھے۔ کعبہ کے متولی ہونے کی بنا پر تمام قبائل عرب ان کی عزت بھی کرتے تھے اور ان سے ڈرتے بھی تھے۔ ان حالات میں ایمان داروں کی کامیابی کا اعلان جہاں مسلمانوں کے لیے ایک بشارت تھی وہاں اس سے یہ بھی معلوم ہو جاتا ہے کہ ایک دنیا دار انسان کے نزدیک کامیابی کا جو تصور اور معیار ہے وہ تصور ہی سرے سے غلط ہے۔ دنیوی اور اخروی کامیابی کے لیے جن صفات کا ہونا لازمی ہے۔ وہ وہی چھ صفات ہی ہیں جن کا آئندہ آیات میں ذکر ہو رہا ہے۔"],[4548,"§نماز میں خشوع کا مقام اور اثرات\nخَشَعَ کے معنی ایسی عاجزی ہے جو دل میں ڈر اور ہیبت طاری ہونے کی وجہ سے ہو۔ پھر اس ڈر اور عاجزی کے اثرات اعضاء و جوارح پر بھی ظاہر ہونے لگیں۔ آنکھیں مرعوب ہو کر جھک جائیں اور آواز پست ہو جائے چنانچہ ایسے مقامات پر بھی قرآن نے یہی لفظ استعمال فرمایا ہے، پھر اسی خشوع کا یہ تقاضا ہوتا ہے کہ انسان نماز میں با ادب کھڑا ہو۔ ادھر ادھر نہ دیکھے، نہ اپنے کپڑوں کو سنوارتا رہے نہ اپنی داڑھی وغیرہ سے کھیلتا رہے اور نہ دل میں نماز پر توجہ کے علاوہ دوسرے خیالات آنے دے اور خیالات آنے بھی لگیں تو فوراً ادھر سے توجہ ہٹا کر یہ سوچنے لگے کہ وہ نماز میں اپنے مالک کے سامنے دست بستہ کھڑا ہے اور اس بات پر توجہ دے کہ وہ زبان سے کیا کہہ رہا ہے۔ خشوع اگرچہ اجزائے صلوٰۃ کے لیے شرط نہیں تاہم حسنِ قبول کے لیے لازمی شرط ہے۔"],[4549,"§لغو کا مفہوم\nلغو سے مراد فضول اور بے کار مشغلے اور کھیل بھی ہو سکتے ہیں۔ یعنی وہ لوگ اگر تفریح طبع کے لیے یا جسمانی کسرت کے طور پر کوئی کھیل کھیلتے ہیں تو ایسے کھیل نہیں کھیلتے جن میں محض وقت کا ضیاع ہو بلکہ ایسے کھیل کھیلتے ہیں جن سے کوئی دینی فائدہ بھی حاصل ہوتا ہو۔ جیسے جہاد کی غرض سے تیراکی، نیز بازی، تیر اندازی اور نشانہ بازی وغیرہ اور لغو سے مراد بے ہودہ اور فضول باتیں بھی ہو سکتی ہیں۔ جیسے فضول گپیں، غیبت، بکواس، تمسخر، فحش گفتگو اور فحش قسم کے گانے وغیرہ۔ ان باتوں سے وہ صرف خود ہی پرہیز نہیں کرتے بلکہ جہاں ایسی سوسائٹی ہو وہاں سے وہ اٹھ کر چلے جاتے ہیں اور ان کے ساتھ رہنا قطعاً گوارا نہیں کرتے۔"],[4550,"§زکوٰۃ کا لغوی مفہوم\nزکوٰۃ (زکیّٰ، زکو) کے معنی بالیدگی، نشوونما پانا، بڑھنا اور عمدہ ہونا ہے اور زکیّٰ کے معنی کسی چیز کو عمدہ بنانا، اس کی اصلاح کرنا اور آگے بڑھانا ہے اور تزکیہ نفس کے معنی نفس کو روحانی آلائشوں، بیماریوں یا اخلاق رذیلہ سے پاک صاف کرکے اوصافِ حمید پیدا کرنا ہے جیسے ارشاد باری ہے: ﴿قَدْ اَفْلَحَ مَنْ زَكّٰىهَا۪ۙ۰۰۹﴾ (الشمس : 9) ’’یعنی جس نے اپنے نفس کو پاکیزہ بنا لیا وہ کامیاب ہو گیا۔‘‘ اور زکوٰۃ کے مفہوم میں یہ سب باتیں شامل ہیں اور زکوٰۃ سے جو دو فائدے زکوٰۃ ادا کرنے والے کو پہنچتے ہیں وہ ہیں تطہیر مال اور تزکیہ نفس (103:9) اور زکوٰۃ سے جو فائدہ معاشرہ کو پہنچتا ہے وہ یہ ہے کہ اس سے غریبوں اور محتاجوں کی امداد ہوتی ہے۔ طبقاتی تقسیم کم ہو جاتی ہے۔ کیونکہ زکوٰۃ کی ادائیگی سے دولت کا بہائو امیر سے غریب کی طرف ہو جاتا ہے۔ اور فَاعِلُوْنَ سے مراد یہ ہے کہ زکوٰۃ کی ادائیگی ان کی مستقل اور پختہ عادت بن چکی ہے۔ ایسا نہیں ہوتا کہ جب جی چاہے ادا کر دیں اور جب نہ چاہے تو نہ کریں۔"],[4551,"§زکوٰۃ اور اس کے فوائد\nیہاں یہ سوال بھی پیدا ہوتا ہے کہ زکوٰۃ تو مدینہ میں فرض ہوئی تھی۔ پھر اس مکی سورہ میں فَاعِلُوْنَ کا کیا معنی؟ تو اس کا جواب یہ ہے کہ زکوٰۃ کا نصاب محل زکوٰۃ اشیاء اور شرح زکوٰۃ کا تعین یہ سب کچھ فی الواقع مدینہ میں ہوا تھا مگر اس کی مشروعیت مکہ میں ہو چکی تھی۔ چنانچہ اکثر مکی سورتوں میں بھی زکوٰۃ و صدقات کا ذکر پایا جاتا ہے۔\nاس آیت کے بھی دو مطلب ہیں۔ ایک یہ کہ وہ اپنے مقامات ستر کو ڈھانپ کر رکھتے ہیں اور کسی کے سامنے کھولتے نہیں نہ عریاں لباس پہنتے ہیں کہ بدن کے اعضاء نظر آتے رہیں اور دوسرا یہ کہ وہ اپنی عفت و عصمت کی پوری پوری نگہداشت کرتے ہیں۔"],[4552,"§ترکِ نکاح اور رہبانیت کا رد\nمسلمانوں کے لیے اپنے شہوانی جذبات اور خواہشات کی تکمیل کی دو ہی صورتیں ہیں۔ ایک یہ کہ وہ اپنی خواہش اپنی بیویوں سے پوری کریں اور دوسری یہ کہ اپنی مملوک کنیزوں سے پوری کر سکتے ہیں۔ مملوک لونڈیوں کے لیے نکاح کی شرط نہیں اور اس سے تمتع کے جواز کی بنیاد نکاح نہیں بلکہ مِلک ہے۔\nاس آیت سے مزید دو امور کا پتہ چلتا ہے۔ ایک یہ کہ راہب سنیاسی یا بعض صوفی قسم کے لوگ شہوانی خواہش کی تکمیل کو برا سمجھتے ہیں۔ حتیٰ کہ نکاح کو ان کی خود ساختہ ولایت کے معیار کے خلاف سمجھا جاتا ہے۔ اس لیے کہ نکاح کے بعد انسان خانہ داری اور اولاد کے جھنجھٹوں میں پڑ جاتا ہے اور یہ چیز رہبانیت کی ریاضت کے حصول میں آڑتے آتی ہے۔ اس آیت میں ان لوگوں کے نظریہ کا پورا پورا رد موجود ہے۔\nنیز دورِ نبوی میں صحابہ کرام رضی اللہ عنہم میں بھی کچھ رہبانیت کا رجحان چل نکلا تھا۔ چنانچہ سیدنا انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ ’’تین آدمی رسول اللہ صلی اللہ علیہ وسلم کی بیویوں کے گھر آئے اور آپ صلی اللہ علیہ وسلم کی عبادت کے متعلق پوچھنے لگے۔ جب انہیں بتایا گیا تو اسے انہوں نے کم سمجھا اور کہنے لگے کہ کہاں ہم اور کہاں اللہ کے رسول صلی اللہ علیہ وسلم جن کے پہلے اور پچھلے سب گناہ معاف کیے جا چکے ہیں۔ پھر ان میں سے ایک نے کہا: میں ہمیشہ ساری رات نماز میں گزارا کروں گا‘‘ دوسرے کہا: ’’میں ہمیشہ روزہ رکھا کروں گا اور تیسرے نے کہا میں ہمیشہ عورتوں سے کنارہ کش رہوں گا اور کبھی نکاح نہ کروں گا‘‘ اتنے میں آپ صلی اللہ علیہ وسلم تشریف لے آئے اور ان لوگوں سے پوچھا: ’’کیا تم ہی وہ لوگ ہو جنہوں نے ایسی اور ایسی باتیں کی ہیں؟ اللہ کی قسم! میں تم سب سے زیادہ اللہ سے ڈرنے والا اور پرہیزگار ہوں۔ اس کے باوجود میں روزہ رکھتا بھی ہوں اور چھوڑتا بھی ہوں۔ رات کو نماز بھی پڑھتا ہوں اور سوتا بھی ہوں اور عورتوں سے نکاح بھی کرتا ہوں۔ تو جو کوئی میری سنت کو ناپسند کرے اس کا مجھ سے کوئی واسطہ نہیں۔‘‘\n(صحیح البخاری)"],[4553,"§عورت کا اپنے غلام سے تمتع کی ممانعت\nاور دوسری یہ بات کہ مرد کے لیے تو اس کی مملوکہ کنیز سے تمتع جائز ہے۔ لیکن عورت اپنے مملوک غلام سے تمتع نہیں کر سکتی۔ سیدنا عمر رضی اللہ عنہ کے زمانہ میں ایک عورت نے اپنے غلام سے تمتع کر لیا۔ پھر دلیل میں یہ آیت پیش کی۔ آپ رضی اللہ عنہ نے صحابہ رضی اللہ عنہم کی مجلس شوریٰ میں یہ معاملہ پیش کیا تو سب نے بالاتفاق کہا کہ: (تَاَوَّلَتْ کِتَابَ اللہِ تَعَالٰی غَیْرَ تَاوِیْلِہ) ’’یعنی اس عورت نے اللہ کی کتاب کا غلط مفہوم اخذ کیا ہے‘‘ اور عورت کے لیے اس چیز کو حرام کرنے کی حکمت یہ ہے کہ غلام اپنی مالکہ کی خواہش شہوانی تو پوری کر سکتا ہے۔ لیکن اس کا قوام نہیں بن سکتا۔ لہٰذا ایسی عورت کے لیے بہتر یہی ہے کہ اگر وہ چاہے تو اسے آزاد کر کے اس سے نکاح کر لے۔"],[4554,"§شہوانی خواہش کی تین ممکنہ صورتیں اور راہِ اعتدال\nشہوانی خواہشات کے سلسلہ میں تین ہی صورتیں ممکن تھیں۔ ایک یہ کہ انسان ایسی خواہشات کو کلیتاً ترک کر دے۔ دوسری یہ کہ ان خواہشات کی تکمیل میں انسان کلیتاً آزاد ہو اور تیسری یہ کہ کوئی معتدل روش اختیار کی جائے۔ اسلام نے ان میں سے معتدل روش کو اختیار کیا ہے۔"],[4555,"§جائز نکاح اور مِلک یمین کے علاوہ باقی سب صورتیں حرام ہیں\nیعنی ان خواہشات کی تکمیل کا راستہ کھول تو دیا۔ لیکن صرف جائز نکاح یا مِلک یمین کی صورت میں۔ باقی دونوں انتہاء پسندانہ صورتوں کو ناجائز اور حرام قرار دیا ہے۔ نہ رہبانیت کی ترک خواہش کو پسند فرمایا اور نہ اس سلسلہ میں شتر بے مہار قسم کی آزادی کو۔ اس آیت میں اسی بے لگام آزادی کو ممنوع قرار دیا گیا ہے اور اس میں زنا، لواطت یا لونڈے بازی، عورتوں کی ہم جنسی، جلق یا مشت زنی غرض یہ کہ شہوت رانی کی جتنی بھی صورتیں مندرجہ بالا دو صورتوں کے علاوہ ممکن ہیں سب ناجائز قرار پاتی ہیں۔\nواضح رہے کہ جائز نکاح سے مراد ایسا نکاح ہے جو عورت کو بسانے کے لیے کیا جائے۔ عورت کی رضا کو مقدم سمجھا جائے۔ عورت کا نکاح اس کا ولی کرے، نکاح کا اعلان ہو اور کم از کم دو گواہ موجود ہوں اور حق مہر مقرر کیا جائے۔ ان شرائط کو پورا نہ کرنے والا نکاح مثلاً نکاح متعہ، نکاح حلالہ یا نکاح شغار جائز نہیں۔ دور نبوی میں اور بھی کئی قسم کے نکاح رائج تھے۔ جو یہ شرائط پوری نہیں کرتے تھے۔ لہٰذا وہ از خود باطل قرار پا گئے۔ چنانچہ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ جاہلیت کے زمانہ میں لوگ چار طرح پر نکاح کیا کرتے تھے۔ ایک تو وہی معروف نکاح ہے۔ جیسے آج کل بھی لوگ کرتے ہیں یعنی کوئی شخص کسی دوسرے کو نکاح کے لیے کہتا اور وہ اپنی کسی رشتہ دار عورت (مثلاً بہن، بھتیجی، بھانجی وغیرہ) یا بیٹی کا مہر مقرر کرکے نکاح کر دیتا۔ (اسی قسم کے نکاح کو اسلام نے بحال رکھا ہے)۔\nدوسری صورت یہ تھی کہ جب کسی کی بیوی حیض سے پاک ہو جاتی تو شوہر اپنی بیوی سے کہتا کہ تو فلاں شخص کو اپنے پاس بلا لے اور اس سے لپٹ جا۔ (یعنی اس سے ہمبستری کر) جب عورت اس مرد سے صحبت کر چکتی تو اس کا خاوند اس سے اس وقت تک علیحدہ رہتا جب تک کہ اس غیر مرد کا حمل نمایاں نہ ہو جاتا اور جب حمل واضح ہو جاتا تو اس کے بعد اس کا خاوند اگر چاہتا تو اس سے صحبت کرتا اور شوہر اپنی بیوی سے یہ کام اس لیے کراتا تھا کہ بچہ شریف اور عمدہ پیدا ہو (تاکہ وہ شوہر کی ناموری کا باعث ہو) ایسے نکاح کو نکاح استبضاع کہا کرتے تھے۔\nنکاح کی تیسری صورت یہ تھی کہ ایک عورت کے شوہر کئی مرد ہوتے تھے لیکن یہ دس سے کم ہی ہوتے تھے اور وہ سب اس عورت سے صحبت کیا کرتے۔ پھر جب اسے حمل قرار پا جاتا تو وہ وضع حمل کے چند دن بعد ان سب شوہروں کو بلا بھیجتی اور اس کی دعوت پر ان سب کو آنا پڑتا تھا۔ جب وہ اس کے ہاں اکٹھے ہو جاتے تو وہ ان سے کہتی۔ جو کچھ تم کرتے رہے وہ تمہیں معلوم ہے۔ اب میرے ہاں جو بچہ پیدا ہوا ہے یہ تم میں سے فلاں کا بچہ ہے۔ اس معاملہ میں اس عورت کو پورا اختیار ہوتا کہ جس کا وہ چاہتی نام لے لیتی اور وہ بچہ اسی کا ہو جاتا اور کسی کو اس کے فیصلہ سے انکا کی مجال نہ ہوتی۔ (کیونکہ قومی رسم ہی یہی تھی)\nاور چوتھی صورت یہ تھی کہ کسی عورت کے پاس بہت سے آدمی آتے جاتے رہتے اور وہ ہر ایک سے صحبت کرا لیتی کسی سے بھی انکار نہ کرتی اور وہ کنجریاں تھیں جن کے دروازے پر پہچان کے لیے جھنڈا لگا دیتے۔ اب جس شخص کا جی چاہتا وہ اس سے صحبت کر سکتا تھا پھر جب اسے حمل ٹھہر جاتا اور بچہ جنتی تو اس کے ہاں جانے والے سب مرد اس عورت کے ہاں اکٹھے ہو جاتے اور کسی قیافہ شناس کو اپنے پاس بلاتے۔ قیافہ شناس علم قیافہ کی رو سے جس مرد کو اس بچہ کا باپ بتاتا وہ بچہ اسی کا بیٹا ہو جاتا وہ اس کا باپ کہلاتا اور قیافہ شناس کے فیصلہ سے کسی کو انکار کی مجال نہ ہوتی۔\nپھر جب اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کو پیغمبر بنا کر بھیجا تو آپ نے جاہلیت کے سب نکاح ختم کر دیے۔ بس ایک ہی قسم کا نکاح باقی رکھا جو آج کل لوگ کرتے ہیں۔ (صحیح البخاری)"],[4556,"§امانت کی قسمیں اور ان کی نگہداشت\nامانتوں سے مراد ہر وہ امانت ہے جو اللہ تعالیٰ کی طرف سے یا معاشرہ کی طرف سے یا کسی فرد کی طرف سے کسی شخص کے سپرد کی گئی ہو۔ خواہ یہ امانت منصب سے تعلق رکھتی ہو یا اقوال سے یا اموال سے۔ ان سب کی پوری پوری نگہداشت ضروری ہے۔ یہی صورت مال، عہد اور معاہدات کی ہے۔ خواہ کوئی عہد اللہ تعالیٰ سے کیا گیا ہو اور اللہ تعالیٰ نے بندوں سے لیا ہو۔ خواہ یہ آپس کا قول و قرار ہو اور خواہ یہ معاہدہ بیع یا نکاح سے متعلق ہو۔ ان کو وفا کرنا ضروری ہے۔ امانت میں خیانت اور وعدہ خلافی دونوں ایسے جرم ہیں جنہیں رسول اللہ صلی اللہ علیہ وسلم نے منافق کی علامتیں قرار دیا ہے جیسا کہ درج ذیل احادیث سے واضح ہے:\n(1)\nسیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’منافق کی تین نشانیاں ہیں۔ جب بات کرے تو جھوٹ بولے اور وعدہ کرے تو اس کا خلاف کرے اور جب اس کے پاس امانت رکھیں تو خیانت کرے۔‘‘ (صحیح البخاری)\n(2)\nسیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس میں چار خصلتیں ہوں وہ پکا منافق ہے اور جس میں ان چاروں میں سے کوئی ایک خصلت ہو گی اس میں نفاق کی ایک خصلت ہو گی جب تک اسے چھوڑ نہ دے جب اس کے پاس امانت رکھیں تو خیانت کرے اور جب بات کرے تو جھوٹ بولے اور جب عہد کرے تو بے وفائی کرے اور جب جھگڑا کرے تو بکواس کرے یا ناحق کی طرف چلے۔‘‘ (صحیح البخاری)\nاب دیکھیے پہلی حدیث میں صرف تین علامتیں مذکور ہیں جن میں دو یہی ہیں جو اس آیت میں مذکور ہیں اور دوسری میں جو چار علامتیں مذکور ہیں ان میں سے بھی دو یہی باتیں ہیں۔"],[4557,"§جنت کا سب سے اعلیٰ مقام جنت الفردوس\nفردوس بمعنی سرسبز وادی (منجد) اور بمعنی رود بار میں واقع باغ جس میں ہر قسم کے پھل اور پھول موجود ہوں (منتہی الارب) گویا جنت الفردوس سے مراد جنت کا وہ حصہ ہے جس میں گھنی اور ٹھنڈی چھائوں والے سرسبز درخت بکثرت ہوں۔ پھولوں کی خوشبو سے معطر ہو اور اس میں ہر قسم کے پھل با افراط ہوں اور جنت الفردوس جنت کا سب سے بلند طبقہ اور عین وسط میں ہوگا۔ جیسا کہ درج ذیل حدیث سے واضح ہے:\nسیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ربیع بنت نضر رضی اللہ عنہ کا بیٹا حارثہ بن سراقہ رضی اللہ عنہ بدر کے دن ایک غیبی تیر سے شہید ہو گیا۔ وہ آپ صلی اللہ علیہ وسلم کے پاس آکر کہنے لگیں: ’’مجھے حارثہ رضی اللہ عنہ کا حال بتائیے اگر وہ خیر کو پہنچا تو میں ثواب کی امید رکھوں اور صبر کروں اور اگر نہیں پہنچا تو میں اس کے لیے دعا کرتی رہوں۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ام حارثہ! جنت میں بہت سے باغ ہیں اور تیرا بیٹا تو فردوسِ بریں میں داخل ہوا ہے جو جنت کے وسط میں بلند زمین اور سب سے بلند مقام ہے۔‘‘ (صحیح ترمذی)\nاسی جنت کے لیے رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو یہ دعا سکھائی: ((اَللّٰہُمَّ اِنِّیْ اَسْئَلُکَ الْجَنَّۃَ الْفِرْدَوْسَ)) نیز آپ صلی اللہ علیہ وسلم نے فرمایا کہ جب اللہ سے سوال کرو تو جنت الفردوس کا سوال کیا کرو۔\nمندرجہ بالا آیات کے نزول کے وقت مسلمانوں کی جو حالت تھی اور ان آیات کے نزول پر آپ صلی اللہ علیہ وسلم نے مسلمانوں کے حق میں جو دعا فرمائی۔ مندرجہ ذیل حدیث سے اس حالت کا پورا نقشہ سامنے آ جاتا ہے۔\nسیدنا عمر رضی اللہ عنہ کہتے ہیں کہ جب آپ صلی اللہ علیہ وسلم پر وحی اترتی تو آپ صلی اللہ علیہ وسلم کے چہرے کے آس پاس شہد کی مکھی کی گنگناہٹ جیسی آواز آنے لگتی تھی۔ ایک دن آپ صلی اللہ علیہ وسلم پر وحی نازل ہوئی تو تھوڑی ہی دیر بعد آپ صلی اللہ علیہ وسلم نے قبلہ کی طرف منہ کرکے اور دونوں ہاتھ اٹھا کر دعا کی: اے اللہ! ہمیں زیادہ کر، تھوڑے نہ رہنے دے، ہمیں عزت عطا فرما، ذلیل نہ رہنے دے ہمیں عطا کر اور محروم نہ رکھ، ہمیں دوسروں پر مقدم کر، دوسروں کو ہم پر مقدم نہ رکھ، ہمیں خوش کر دے اور ہم سے خوش ہوجا! اس دعا کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا کہ: مجھ پر دس آیات نازل ہوئی ہیں جو ان پر عمل کرے گا، جنت میں داخل ہوگا۔ پھر آپ صلی اللہ علیہ وسلم نے ﴿قَدْ اَفْلَحَ الْمُؤْمِنُوْنَۙ۰۰۱…﴾ سے لے کر دس آیات پڑھیں۔ (صحیح ترمذی)\nفَلَاح کے لغوی معنی ہیں، چیرنا، کاٹنا، کاشت کار کو بھی فَلَّاح کہا جاتا ہے کہ وہ زمین کو چیر پھاڑ کر اس میں بیج بوتا ہے۔ مفلح (کامیاب) بھی وہ ہوتا ہے جو صعوبتوں کو قطع کرتے ہوئے مطلوب تک پہنچ جاتا ہے، یا کامیابی کی راہیں اس کے لیے کھل جاتی ہیں، اس پر بند نہیں ہوتیں۔ شریعت کی نظر میں کامیاب وہ ہے جو دنیا میں رہ کر اپنے رب کو راضی کر لے اور اس کے بدلے میں آخرت میں اللہ کی رحمت و مغفرت کا مستحق قرار پا جائے۔ اس کے ساتھ دنیا کی سعادت و کامرانی بھی میسر آ جائے تو سبحان اللہ۔ ورنہ اصل کامیابی تو آخرت ہی کی کامیابی ہے۔ گو دنیا والے اس کے برعکس دنیوی آسائشوں سے بہرہ ور کو ہی کامیاب سمجھتے ہیں۔ آیت میں ان مومنوں کو کامیابی کی نوید سنائی گئی ہے۔\nاس سے معلوم ہوا کہ متعہ کی اسلام میں قطعاً اجازت نہیں ہے اور جنسی خواہش کی تسکین کے لیے صرف دو ہی جائز طریقے ہیں۔ بیوی سے مبشارت کرکے یا لونڈی سے ہم بستری کرکے۔ بلکہ اب صرف بیوی ہی اس کام کے لیے رہ گئی ہے کیونکہ اصطلاحی لونڈی کا وجود فی الحال ختم ہے تاہم جب کبھی بھی حالات نے اسے دوبارہ وجود پذیر کیا تو بیوی ہی کی طرح اس سے مباشرت جائز ہو گی۔\nآخر میں پھر نمازوں کی حفاظت کو فلاح کے لیے ضروری قرار دیا، جس سے نماز کی اہمیت و فضیلت واضح ہے۔ لیکن آج مسلمان کے نزدیک دوسرے اعمال صالحہ کی طرح اس کی بھی کوئی اہمیت سرے سے باقی نہیں رہ گئی ہے۔ ﴿فَاِنَّا لِلّٰہِ وَاِنَّا اِلَیْہِ رَاجِعُوْنَ﴾ حالانکہ عہد رسالت و عہد صحابہ میں نماز ہی کافر اور مسلمان کے درمیان فرق کرنے والی چیز تھی۔\nان صفات مذکورہ کے حامل مومن ہی فلاح یاب ہوں گے جو جنت کے وارث یعنی حق دار ہوں گے۔ جنت بھی جنت الفردوس، جو جنت کا اعلیٰ حصہ ہے۔ جہاں سے جنت کی نہریں جاری ہوتی ہیں۔ (صحیح البخاری)\nاللہ تعالیٰ نے ان لوگوں کو کامیاب قرار دیا ہے جن میں سات خصلتیں پائی جائیں گی پہلی خصلت ایمان ہے وہ لوگ کامیاب ہیں جو اللہ کی ذات اس کے پیغمبروں اور آخرت کے دن پر ایمان رکھتے ہیں نمازوں کی ادائیگی میں خشوع اختیار کرتے ہیں اللہ کی بارگاہ میں اپنی ذلت اور مسکنت کا اظہار کرتے رہتے ہیں احکام الٰہیہ کی ادائیگی کے ساتھ جذبہ اطاعت اور وفا شعاری کا ثبوت بہم پہنچاتے ہیں عذاب الٰہی سے خوف زدہ رہتے ہیں نمازوں کی ادائیگی میں خشوع سے مقصود بالخصوص یہ بھی ہے کہ ان کی نگاہیں آسمان کی جانب نہیں اٹھتی ہیں بلکہ سجدہ کی جگہ سے آگے نہیں جاتی ہیں نیز خشوع سے یہ بھی مقصود ہے کہ قرآن پاک کی تلاوت کرتے ہوئے معانی کی جانب توجہ کی جائے تاکہ کائنات کے عجائب و اسرار سے آگاہی حاصل ہو اور وعید کی آیات کی تلاوت کے وقت اللہ کی ذات کا تصور سبھی اعضاء پر کار فرما ہو اور تواضع، خشیت الٰہی کا جذبہ کار فرما رہے۔\nحقیقت یہ ہے کہ نماز ادا کرنے والا شخص اپنے پروردگار سے سرگوشی کرتا ہے اس لیے قرآن پاک کے الفاظ اور دعائوں کے الفاظ کو غفلت کی حالت میں زبان سے ادا نہ کیا جائے اس حقیقت سے انکار ممکن نہیں کہ جس نماز کی ادائیگی میں خشوع خضوع کار فرما نہیں اس کی مثال اس جسم کی ہے جس میں روح نہیں، ایمان والوں کا یہ وصف بھی بیان ہوا کہ وہ جھوٹ، گالی گلوچ اور بے ہودہ مزاح سے بھی روگردانی کرتے ہیں ان کی توجہ تو خالق مطلق کی ذات کی جانب ہی رہتی ہے کسی اور کا تصور ان کے دل و دماغ میں راہ نہیں پاتا ہے ان کے اخلاق انبیاء علیہم الصلوٰۃ والسلام اور صالحین امت کا نمونہ ہوتے ہیں وہ اپنے نفس امارہ کو کچلنے کے لیے اور انہیں پاکیزہ بنانے کے لیے فقراء اور مساکین پر صدقہ خیرات کرتے رہتے ہیں مزید برآں وہ اپنی شرم گاہوں کو بیویوں اور لونڈیوں کے سوا سے تحفظ عطا کرتے ہیں ان کی زندگی عفت و عصمت کا اعلیٰ نمونہ ہوتی ہے ان اوصاف کے لوگ قابل ستائش ہیں ہرگز ان کی زندگی کو ملامت کا نشانہ نہ بنایا جائے۔\nجو شخص چار بیویوں اور لا محدود لونڈیوں کے سوا عورتوں اور مرد لڑکوں سے اپنی خواہشات نفسانیہ کو سکون عطا کرتے ہیں تو یہ وہ لوگ ہیں جو حدود الٰہیہ سے تجاوز کرکے سرکشی میں دیوانگی کی حد تک پہنچے ہوئے ہیں، البتہ اِسْتِمْنَائ بِالْیَد کو امام احمد بن حنبل رحمہ اللہ نے درست قرار دیا ہے کہ منی کا اخراج بھی پاخانہ پیشاب کے نکالنے کے برابر ہے اس لیے ضرورت کے پیش نظر اس کی اجازت دی گئی ہے اس کی بنیاد فصد اور سنگیاں لگوانے کے جواز پر ہے جبکہ اکثر علماء اس کو حرام قرار دیتے ہیں بہر حال دناءت اور خست نفس کا مظاہرہ ہے کمینے شخص کے لیے بھی باعث عار ہے تو عزت والے شخص کے لیے یقیناً یہ عمل باعث عار ہے۔\nوَالَّذِیْنَ ہُمْ لِاَمٰنٰتِھِمْ وَعَھْدِھِمْ رٰعُوْنَ: جب ان کے پاس امانتیں رکھی جاتیں ہیں تو وہ خیانت کے مرتکب نہیں ہوتے اور جب وعدہ کرتے ہیں تو پورا کرتے ہیں جبکہ منافق شخص کی تین علامتیں ہیں جب زبان سے کوئی کلمہ نکالتا ہے تو وہ جھوٹ ہوتا ہے اور عہد و پیمان کا خیال نہیں رکھتا اور امانت میں خیانت کا مرتکب ہوتا ہے۔\nوَالَّذِیْنَ ہُمْ عَلٰی صَلَوٰتِھِمْ یُحَافِظُوْنَ: اور وہ لوگ جو نمازوں کی ادائیگی ان کے اوقات میں کرتے ہیں نہایت خشوع و خضوع کے ساتھ نمازوں کی ادائیگی میں ہمیشگی اختیار کرتے ہیں، ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم سے دریافت کیا اللہ کو کون سا عمل زیادہ محبوب ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نماز کو اس کے وقت پر ادا کرنا، میں نے دریافت کیا پھر کون سا عمل افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: والدین کے ساتھ اچھا سلوک اختیار کرنا، میں نے دریافت کیا کہ پھر کون سا عمل افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کی رضا جوئی کے لیے اللہ کی راہ میں جہاد کرنا۔\n(صحیح بخاری، صحیح ترمذی، الصحیحۃ، ح : 1489)\nذہن نشین فرمائیں کہ اللہ پاک نے قابل تعریف اوصاف کے ذکر کرنے کے آغاز میں نماز کا ذکر کیا ہے جبکہ اختتام بھی نماز کی ادائیگی پر ہے اس کا سبب یہ ہے کہ ایک حدیث میں وارد ہے۔ لوگو! سمجھ لو تمام اعمال سے بہتر عمل نماز کی ادائیگی ہے اور یہ بھی حقیقت ہے کہ وضو کے عمل پر بھی محافظت ایمان دار شخص کرتا ہے۔ (ابن ماجہ، سنن دارمی، حاکم)\nاُوْلٰٓئِکَ ہُمُ الْوٰرِثُوْنَ: جن ایمان والوں کا ان کے اوصاف کے ساتھ ذکر کیا ہے وہ اس لائق ہیں کہ انہیں جنت میں اونچا مرتبہ عطا ہوگا اس میں ہمیشہ ہمیشہ رہیں گے نہ ان سے ان کو نکالا جائے گا اور نہ ان پر موت طاری ہو گی۔\n(المراغی : 269,267/6)\nوَ لَقَدْ خَلَقْنَا الْاِنْسَانَ مِنْ سُلٰلَةٍ مِّنْ طِيْنٍۚ۰۰۱۲ ثُمَّ جَعَلْنٰهُ نُطْفَةً فِيْ قَرَارٍ\nمَّكِيْنٍ۪۰۰۱۳ ثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً فَخَلَقْنَا الْمُضْغَةَ\nعِظٰمًا فَكَسَوْنَا الْعِظٰمَ لَحْمًا١ۗ ثُمَّ اَنْشَاْنٰهُ خَلْقًا اٰخَرَ١ؕ فَتَبٰرَكَ اللّٰهُ اَحْسَنُ\nالْخٰلِقِيْنَؕ۰۰۱۴ ثُمَّ اِنَّكُمْ بَعْدَ ذٰلِكَ لَمَيِّتُوْنَؕ۰۰۱۵ ثُمَّ اِنَّكُمْ يَوْمَ الْقِيٰمَةِ تُبْعَثُوْنَ۰۰۱۶\nوَ لَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآىِٕقَ١ۖۗ وَ مَا كُنَّا عَنِ الْخَلْقِ غٰفِلِيْنَ۰۰۱۷\nاور بلاشبہ ہم نے انسان کو مٹی کے جوہر سے پیدا کیا ہے @ پھر ہم نے اسے محفوظ قرار گاہ (رحم مادر)میں نطفہ بنا کر رکھا# پھر ہم نے نطفے کو خون کی پھُٹکی بنایا، پھر ہم نے پھُٹکی کو لوتھڑے میں ڈھالا، پھر ہم نے لوتھڑے سے ہڈیاں بنائیں، پھر ہم نے ہڈیوں پر گوشت چڑھا دیا، پھر ہم نے اسے ایک اور ہی صورت میں بنا دیا، چنانچہ بڑا با برکت ہے اللہ جو سب سے عمدہ بنانے والا\nہے$ پھر بے شک تم اس کے بعد ضرور مرنے والے ہو% پھر یقیناً تم یوم قیامت (دوبارہ) اٹھائے جائو گے^ اور بلاشبہ ہم\nنے تمھارے اوپر سات تہ بہ تہ آسمان پیدا کیے، اور ہم (اپنی) مخلوق سے غافل نہیں ہیں&"],[4558,"§انسان کی تخلیق کے تدریجی مراحل\nاللہ تعالیٰ نے بیان فرمایا ہے کہ انسان کی تخلیق کی ابتداء مٹی کے خلاصے سے ہوئی تھی۔ اللہ تعالیٰ نے سیّدنا آدم علیہ السلام کو بجنے والی مٹی سے پیدا کیا جو بدبودار سیاہ کیچڑ تھی۔ ابن جریر رحمہ اللہ کہتے ہیں کہ آدم کو طین کے نام سے بھی موسوم کیا گیا ہے، اس لیے کہ وہ مٹی سے پیدا ہوئے تھے۔ (تفسیر الطبری : 12/18) قتادہ رحمہ اللہ کہتے ہیں کہ آدم علیہ السلام کو مٹی کے خلاصے سے پیدا کیا گیا تھا۔ (تفسیر الطبری : 11/18) اور یہ بات معنی کے اعتبار سے نمایاں اور سیاق کلام سے زیادہ مناسبت رکھتی ہے۔ آدم علیہ السلام کو چپکتے گارے سے پیدا کیا گیا تھا جسے قرآن مجید میں کہیں ﴿طِيْنٍ لَّازِبٍ۰۰۱۱﴾ (الصّٰفّٰت : 11) ’’لیس دار (چپکتی) مٹی۔‘‘ اور کہیں ﴿صَلْصَالٍ مِّنْ حَمَاٍ مَّسْنُوْنٍۚ۰۰۲۶﴾ (الحجر : 26) ’’کھنکھناتی مٹی (سے اور) سڑے ہوئے گارے میں سے ہے۔‘‘ اور وہ مٹی سے پیدا کیے گئے ہیں جیسا کہ فرمایا: ﴿وَ مِنْ اٰيٰتِهٖۤ اَنْ خَلَقَكُمْ مِّنْ تُرَابٍ ثُمَّ اِذَاۤ اَنْتُمْ بَشَرٌ تَنْتَشِرُوْنَ۰۰۲۰﴾ (الروم: 20) ’’اور اسی کے نشانات میں سے ہے کہ اس نے تمہیں مٹی سے پیدا کیا، پھر اچانک تم انسان ہو جو جابجا پھیل رہے ہو۔‘‘\nامام احمد رحمہ اللہ نے ابو موسیٰ رضی اللہ عنہ سے روایت کیا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ((اِنَّ اللہَ عَزَّوَجَلَّ خَلَقَ آدَمَ مِنْ قَبْضَۃٍ قَبَضَھَا مِنْ جَمِیْعِ الْاَرْضِ، فَجَائَ بَنُو آدَمَ عَلٰی قَدْرِ الْاَرْضِ جَائَ مِنْہُمُ الْاَبْیَضُ، وَالْاَحْمَرُ، وَالْاَسْوَدُ، وَبَیْنَ ذٰلِکَ، وَالْخَبیثُ، وَالطَّیِّبُ، وَالسَّھْلُ، وَالْحَزْنُ، وَبَیْنَ ذٰلِکَ)) ’’بے شک اللہ تعالیٰ نے آدم علیہ السلام کو (مٹی کی) ایک مٹھی سے پیدا فرمایا جسے اس نے ساری زمین سے اکٹھا کیا تھا تو اسی زمین کے مطابق بنو آدم پیدا ہوئے کہ ان میں سے کچھ کا رنگ سرخ ہے کچھ کا سفید، کچھ کا سیاہ اور کچھ کا بین بین، ان میں سے کچھ برے، کچھ اچھے، کچھ نرم اور کچھ سخت جبکہ کچھ درمیانے ہیں۔‘‘ (مسند احمد) اس حدیث کو امام ابو داؤد اور ترمذی نے بھی روایت کیا ہے۔ (سنن ابی داؤد، حدیث : 4693 و جامع الترمذی، حدیث : 2955)"],[4559,"§انسان کی تخلیق کے مراحل\n﴿ثُمَّ جَعَلْنٰهُ نُطْفَةً﴾ ’’پھر ہم نے اس کو نطفہ بنا دیا۔‘‘ ﴿جَعَلْنٰهُ ﴾ میں ضمیر جنس انسان کی طرف لوٹتی ہے جیسا کہ دوسری آیت میں فرمایا: ﴿وَ بَدَاَ خَلْقَ الْاِنْسَانِ مِنْ طِيْنٍۚ۰۰۷ ثُمَّ جَعَلَ نَسْلَهٗ مِنْ سُلٰلَةٍ مِّنْ مَّآءٍ مَّهِيْنٍۚ۰۰۸﴾ (السجدۃ : 8,7) ’’اور اس نے انسان کی پیدائش کو مٹی سے شروع کیا، پھر اس کی نسل ایک حقیر پانی کے جوہر سے چلائی۔‘‘ یعنی کمزور (پانی) سے۔ جیسا کہ فرمایا: ﴿اَلَمْ نَخْلُقْكُّمْ مِّنْ مَّآءٍ مَّهِيْنٍۙ۰۰۲۰ فَجَعَلْنٰهُ فِيْ قَرَارٍ مَّكِيْنٍۙ۰۰۲۱﴾ (المرسلٰت : 21,20) ’’کیا ہم نے تم کو حقیر پانی سے پیدا نہیں کیا؟ پھر ہم نے اسے ایک محفوظ جگہ میں رکھا۔‘‘ یعنی اس کے لیے رحم کو تیار کیا اور بنایا گیا۔ ﴿اِلٰى قَدَرٍ مَّعْلُوْمٍۙ۰۰۲۲ فَقَدَرْنَا١ۖۗ فَنِعْمَ الْقٰدِرُوْنَ۰۰۲۳﴾ (المرسلٰت : 23,22) ’’ایک وقت معین تک، پھر ہم نے اندازہ لگایا بعد ازاں کیا ہی خوب اندازہ لگانے والے ہیں۔‘‘ یعنی ہم نے اسے ایک معلوم مدت اور معین وقت تک رحم میں رکھا حتیٰ کہ یہ مستحکم ہو گیا اور ایک حال سے دوسرے حال اور ایک صفت سے دوسری صفت میں بدلتا رہا، اس لیے یہاں فرمایا: ﴿ثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً﴾ ’’پھر ہم نے نطفے کو جما ہوا خون بنایا۔‘‘ پھر نطفے، یعنی اس اچھلنے والے پانی کو جو مرد کی پشت اور عورت کی سینے کی ہڈیوں میں سے نکلتا ہے اسے سرخ رنگ کی مستطیل شکل کا لوتھڑا بنا دیا۔ عکرمہ رحمہ اللہ کہتے ہیں کہ یہ خون ہوتا ہے۔ ﴿فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً﴾ ’’پھر ہم نے جمے ہوئے خون کو لوتھڑے میں ڈھالا۔‘‘ یہ گوشت کی بوٹی جیسا ایک ٹکڑا ہوتا ہے جس کی نہ کوئی شکل ہوتی ہے اور نہ کوئی صورت۔ ﴿فَخَلَقْنَا الْمُضْغَةَ عِظٰمًا﴾ ’’پھر ہم نے لوتھڑے سے ہڈیاں بنائیں۔‘‘ اور اسے شکل و صورت دے کر اس میں ایک سر، دو ہاتھ، دو پائوں اور ان کی ہڈیاں، اعصاب اور رگیں پیدا فرما دیں۔\nعوفی رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے ﴿ثُمَّ اَنْشَاْنٰهُ خَلْقًا اٰخَرَ١ؕ﴾ کے بارے میں روایت کیا ہے کہ ہم اسے ایک حال سے دوسرے حال میں منتقل کرتے رہتے ہیں حتیٰ کہ وہ بچہ بن کر نکل آتا ہے، پھر وہ بچے کی حیثیت سے پروان چڑھتا ہے حتیٰ کہ بالغ ہو جاتا ہے، پھر جوان ہو جاتا ہے، ادھیڑ عمر کو پہنچ جاتا ہےا ور پھر بوڑھا اور بہت بوڑھا ہو جاتا ہے۔ (تفسیر القرطبی: 202/2 و تفسیر الطبری : 15/18 و الدار المنثور : 12/5) امام احمد رحمہ اللہ نے مسند میں عبداللہ بن مسعود رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے بیان فرمایا اور آپ صلی اللہ علیہ وسلم صادق و مصدوق ہیں: ((إِنَّ أَحَدَکُمْ یُجْمَعُ خَلْقُہُ فِی بَطْنِ أُمِّہٖ، فِی أَرْبَعِینَ یَوْمًا، ثُمَّ یَکُونُ عَلَقَۃً مِّثْلَ ذَلِکَ، ثُمَّ یَکُونُ مُضْغَۃً مِّثْلَ ذَلِکَ، ثُمَّ یُرْسَلُ اِلَیْہِ الْمَلَکُ فَیَنْفُخُ فِیہِ الرُّوحَ، وَیُؤْمَرُ بِأَرْبَعِ کَلِمَاتٍ: رِّزْقِہٖ، وَأَجَلِہٖ، وَعَمَلِہٖ، وَشَقِیٌّ أَمْ سَعِیدٌ، فَوَالَّذِیْ لَا اِلٰہَ غَیْرُہٗ! اِنَّ اَحَدَکُمْ لَیَعْمَلُ بِعَمَلِ اَھْلِ الْجَنَّۃِ، حَتّٰی مَا یَکُونُ بَیْنَہُ وَبَیْنَھَا اِلَّا ذِرَاعٌ، فَیَسْبِقُ عَلَیْہِ الْکِتَابُ، فَیُخْتَمُ لَہٗ بِعَمَلِ اَھْلِ النَّارِ، فَیَدْخُلُھَا، وَاِنَّ الرَّجُلَ لَیَعْمَلُ بِعَمَلِ اَھْلِ النَّارِ، حَتّٰی مَا یَکُوْنُ بَیْنَہٗ وَبَیْنَھَا اِلَّا ذِرَاعٌ، فَیَسْبِقُ عَلَیْہِ الْکِتَابُ، فَیُخْتَمُ لَہٗ بِعَمَلِ اَھْلِ الْجَنَّۃِ فَیَدْخُلُھَا)) ’’بے شک تم میں سے ایک کی پیدائش کو اس کی ماں کے پیٹ میں چالیس دن تک نطفے کے طور پر جمع رکھا جاتا ہے، پھر اسی طرح اسے لوتھڑا رکھا جاتا ہے، پھر اسی طرح اسے بوٹی رکھا جاتا ہے، پھر اس کی طرف فرشتے کو بھیجا جاتا ہے جو اس میں روح پھونکتا ہے اور فرشتے کو چار باتوں (کے لکھنے) کا حکم دیا جاتا ہے: اس کے رزق، اس کی موت، اس کے عمل اور اس بات کا کہ وہ بدبخت ہے یا سعادت مند۔ پس اس ذات کی قسم جس کے سوا کوئی معبود نہیںْ تم میں سے ایک شخص اہل جنت کے سے عمل کرتا رہتا ہے حتیٰ کہ اس کے اور جنت کے درمیان صرف ایک ہاتھ کا فاصلہ رہ جاتا ہے مگر کتاب سبقت لے جاتی ہے اور اس کا خاتمہ جہنمیوں کے کسی عمل پر ہو جاتا ہے جس کی وجہ سے وہ جہنم میں داخل ہو جاتا ہے اور ایک شخص اہل دوزخ کے عمل کرتا رہتا ہے حتیٰ کہ اس کے اور دوزخ کے درمیان ایک ہاتھ کا فاصلہ رہ جاتا ہے مگر کتاب اس سے سبقت لے جاتی ہے اور اس کا خاتمہ جنتیوں کے کسی عمل پر ہو جاتا ہے اور وہ جنت میں داخل ہو جاتا ہے۔‘‘ (مسند احمد) اس کو امام بخاری اور امام مسلم نے بھی روایت کیا ہے۔ (صحیح البخاری، حدیث : 6594 وصحیح مسلم، حدیث : 2642)"],[4560,"§آسمانوں کی پیدائش بھی نشانی ہے\nاللہ تعالیٰ نے انسان کی پیدائش کا ذکر فرمانے کے بعد ساتوں آسمانوں کی پیدائش کا ذکر شروع فرمایا ہے، اسی طرح اللہ تعالیٰ نے قرآن مجید میں اور بھی بہت سے مقامات پر آسمانوں اور زمین کی تخلیق کا تخلیقِ انسان کے ساتھ ذکر فرمایا ہے جیسا کہ فرمایا:﴿لَخَلْقُ السَّمٰوٰتِ وَ الْاَرْضِ اَكْبَرُ مِنْ خَلْقِ النَّاسِ﴾ (المومن: 57) ’’آسمانوں اور زمین کا پیدا کرنا لوگوں کو پیدا کرنے کی نسبت زیادہ بڑا (کام) ہے۔‘‘ اسی طرح سورۂ سجدہ کے آغاز میں بھی جسے رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن نماز فجر کی پہلی رکعت میں پڑھا کرتے تھے، آسمانوں اور زمین کی تخلیق کا ذکر فرمایا، پھر اس بات کا کہ اس نے انسان کو حقیر پانی کے جوہر سے پیدا فرمایا ہے، اس سورۂ مبارکہ میں آخرت اور جزا و سزا کا بھی بیان ہے۔ (دیکھیے: السجدۃ، آیات : 9,4 کے تحت) اور ان تمام امور کا تعلق مقاصد سے ہے۔\n﴿سَبْعَ طَرَآىِٕقَ١ۖۗ﴾ ’’سات آسمان تہ در تہ۔‘‘ مجاہد رحمہ اللہ فرماتے ہیں کہ سبع طرائق سے مراد سات آسمان ہیں۔ (الدر المنثور : 13/5 و تفسیر الطبری : 17/18 عن ابن زید و تفسیر القرطبی : 111/12 عن ابی عبیدۃ) جیسا کہ فرمایا: ﴿تُسَبِّحُ لَهُ السَّمٰوٰتُ السَّبْعُ وَ الْاَرْضُ وَ مَنْ فِيْهِنَّ١ؕ﴾ (بنی اسرائیل : 44) ’’ساتوں آسمان اور زمین اور جو (مخلوق) ان میں ہیں، سب اسی کی تسبیح کرتے ہیں۔‘‘ اور فرمایا: ﴿اَلَمْ تَرَوْا كَيْفَ خَلَقَ اللّٰهُ سَبْعَ سَمٰوٰتٍ طِبَاقًاۙ۰۰۱۵﴾ (نوح : 15) ’’کیا آپ نے نہیں دیکھا کہ اللہ نے سات آسمان اوپر کیسے سے بنائے ہیں۔‘‘ اور فرمایا: ﴿اَللّٰهُ الَّذِيْ خَلَقَ سَبْعَ سَمٰوٰتٍ وَّ مِنَ الْاَرْضِ مِثْلَهُنَّ١ؕ يَتَنَزَّلُ الْاَمْرُ بَيْنَهُنَّ لِتَعْلَمُوْۤا اَنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ١ۙ۬ وَّ اَنَّ اللّٰهَ قَدْ اَحَاطَ بِكُلِّ شَيْءٍ عِلْمًاؒ۰۰۱۲﴾ (الطلاق : 12) ’’اللہ ہی وہ ذات ہے جس نے سات آسمان پیدا کیے اور اتنی ہی زمینیں بھی، ان کے درمیان (اللہ کا) حکما ترتا رہے تاکہ تم لوگ جان لو کہ اللہ ہر چیز پر قادر ہے اور بلاشبہ (اپنے) علم سے ہر چیز پر احاطہ کیے ہوئے ہے۔‘‘ اسی طرح یہاں فرمایا: ﴿وَ لَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآىِٕقَ١ۖۗ وَ مَا كُنَّا عَنِ الْخَلْقِ غٰفِلِيْنَ۰۰۱۷﴾ ’’اور البتہ تحقیق ہم نے تمہارے اوپر سات آسمان تہ بہ تہ پیدا کیے اور ہم (اپنی) خلقت سے غافل نہیں ہیں۔‘‘ یعنی وہ جانتا ہے جو زمین میں داخل یا اس سے خارج ہوتا ہے اور جو آسمان سے نازل ہوتا یا اس پر چڑھتا ہے اور وہ تمہارے ساتھ ہے، خواہ تم کہیں بھی ہو اور وہ تمہارے تمام اعمال کو دیکھ رہا ہے۔ اللہ سبحانہ و تعالیٰ سے نہ کوئی آسمان کسی دوسرے آسمان کو اور نہ کوئی زمین کسی دوسری زمین کو چھپا سکتی ہے، وہ ہر پہاڑ کے بارے میں جانتا ہے کہ اس کی تہ میں کیا چھپا ہوا ہے، وہ ہر دریا اور سمندر کے بارے میں جانتا ہے کہ اس کے پیندے میں کیا ہے، وہ تمام پہاڑوں، ٹیلوں، ریت کے ذروں، دریائوں اور سمندروں، جنگلوں اور درختوں کی تعداد کو جانتا ہے، ﴿وَ مَا تَسْقُطُ مِنْ وَّرَقَةٍ اِلَّا يَعْلَمُهَا وَ لَا حَبَّةٍ فِيْ ظُلُمٰتِ الْاَرْضِ وَ لَا رَطْبٍ وَّ لَا يَابِسٍ اِلَّا فِيْ كِتٰبٍ مُّبِيْنٍ۰۰۵۹﴾ (الانعام: 59) ’’اور کوئی پتا نہیں جھڑتا مگر وہ اسے جانتا ہے اور زمین کے اندھیروں میں کوئی دانہ ایسا نہیں جسے وہ جانتا نہ ہو اور کوئی ہری یا سوکھی چیز نہیں ہے مگر واضح کتاب میں (لکھی ہوئی) ہے۔‘‘\nاللہ تعالیٰ نے انسان کی تخلیق کا ذکر کرنے کے بعد، اس کے مسکن اور اس پر ہر لحاظ سے اپنی بے پایاں نعمتوں کا ذکر کرتے ہوئے فرمایا: ﴿وَلَقَدْ خَلَقْنَا فَوْقَکُمْ﴾ ’’اور بنائے ہم نے تمہارے اوپر‘‘ یعنی شہروں کی چھت کے طور پر اور بندوں کے فائدے کی خاطر ﴿سَبْعَ طَرَآئِقَ﴾ ہم نے سات آسمان طبق پر طبق بنائے کہ ہر طبقے کے اوپر دوسرا طبقہ ہے اور ان کو سورج، چاند اور ستاروں کے ذریعے سے سجایا اور ان میں مخلوق کے تمام فوائد ودیعت کیے گئے۔\n﴿وَمَا کُنَّا عَنِ الْخَلْقِ غٰفِلِیْنَ﴾ ’’اور ہم مخلوق سے غافل نہیں ہیں۔‘‘ پس جیسے ہماری تخلیق ہر مخلوق کے لیے عام ہے۔ اسی طرح ہمارا علم بھی تمام مخلوق پر محیط ہے، ہم اپنی کسی مخلوق سے غافل ہیں نہ اسے بھولتے ہیں اور نہ کسی مخلوق کو پیدا کرنے کے بعد اسے ضائع کرتے ہیں، نہ آسمان سے غافل ہوتے ہیں کہ وہ زمین پر گر پڑے اور نہ سمندروں کی موجوں میں تیرتے ہوئے اور صحرائوں میں پڑے ہوئے ایک ذرے کو بھی فراموش کرتے ہیں۔ کوئی ایسا جان دار نہیں جس کو ہم رزق نہ پہنچاتے ہوں۔ ﴿وَ مَا مِنْ دَآبَّةٍ فِي الْاَرْضِ اِلَّا عَلَى اللّٰهِ رِزْقُهَا وَ يَعْلَمُ مُسْتَقَرَّهَا وَ مُسْتَوْدَعَهَا١ؕ ﴾ (ہود: 6) ’’زمین میں چلنے والا کوئی ایسا جاندار نہیں جس کا رزق اللہ کے ذمہ نہ ہو اور اللہ تعالیٰ جانتا ہے کہ کہاں اس کا ٹھکانہ ہے اور کہاں اسے سونپا جاتا ہے۔‘‘ اللہ تعالیٰ نے بہت کثرت سے اپنی تخلیق اور اپنے علم کو اکٹھا بیان کیا ہے، مثلاً فرمایا: ﴿اَلَا يَعْلَمُ مَنْ خَلَقَ١ؕ وَ هُوَ اللَّطِيْفُ الْخَبِيْرُؒ۰۰۱۴﴾ (الملک: 14) ’’کیا وہ نہیں جانتا جس نے پیدا کیا، حالانکہ وہ پوشیدہ باتوں کو جاننے والا اور ہر چیز سے آگاہ ہے۔‘‘ نیز فرمایا: ﴿بَلٰى ١ۗ وَ هُوَ الْخَلّٰقُ الْعَلِيْمُ۰۰۸۱﴾ (یٰسٓ: 81) ’’کیوں نہیں! جبکہ وہ پیدا کرنے والا اور علم رکھنے والا ہے۔‘‘ کیونکہ مخلوقات کی تخلیق، ان کے خالق کے علم اور حکمت پر سب سے بڑی عقلی دلیل ہے۔"],[4561,"§انسان کی پیدائش اور مٹی کے جوہر کا مفہوم\nسَلَالَۃٌ بمعنی خلاصہ، نچوڑ، ست، جوہر، کسی بھی چیز سے نکالا ہوا کار آمد حصہ (مفردات القرآن) اور انسان کو مٹی کے خلاصہ سے پیدا کرنے کے دو مطلب ہو سکتے ہیں ایک یہ کہ سیدنا آدم علیہ السلام کا پتلا مٹی سے بنایا گیا۔ پہلے یہ خشک مٹی تھی۔ پھر اس میں پانی ملایا گیا تو یہ گارا بن گیا۔ پھر اس کا خمیر اٹھایا گیا جس میں بدبو پیدا ہو گئی۔ پھر اسے گوندھ کر اس کا چپک دار اور لیس دار حصہ لیا گیا اور اسے خشک کر لیا گیا۔ پھر اسے حرارت پہنچائی گئی حتیٰ کہ وہ ٹن کی طرح بجنے لگا۔ جیسا کہ مٹی کے برتن اور ان کی مختلف شکلیں بنائی اور آگ میں پکائی جاتی ہیں اور ان میں مٹی کا صرف چپک دار اور کار آمد حصہ ہی استعمال ہوتا ہے۔ اسی مٹی سے آدم علیہ السلام کا پتلا تیار ہوا جس میں اللہ نے اپنی روح سے پھونکا تو جیتا جاگتا انسان وجود میں آ گیا۔ پھر آئندہ آدم کی نسل توالد و تناسل اور نطفہ سے چلی اور دوسرا مطلب یہ ہے نطفہ بذات خود انسان کے جسم میں انہیں غذائوں سے بنتا ہے جو زمین سے ہی حاصل ہوتی ہے۔ اس لحاظ سے نطفہ بھی بالآخر زمین ہی کا جوہر ہے۔"],[4562,"§انسان کی اندرونی کائنات\nیعنی نطفہ اور بے جان گوشت کے لوتھڑے سے ایک جیتا جاگتا عقل و شعور رکھنے والا انسان بنا کر پیدا کر دیا۔ جس کا ایک ایک عضو اور رگ و ریشہ کئی مقاصد کی تکمیل کر رہا ہے اور اس کا کوئی بھی حصہ بے کار پیدا نہیں کیا گیا۔ اب انسان کی اندرونی ساخت پر غور کریں تو معلوم ہوتا ہے کہ انسان کئی قسم کی آٹو میٹک کلوں اور مشینوں کا مجموعہ ہے کہیں چکی لگی ہے، کہیں چھلنی ہے، کہیں پیسنے کی کل، کہیں کوٹنے کی، کہیں توڑنے کی کہیں جذب کرنے والی کہیں فضلات کو باہر پھینکنے والی، کہیں اچھالنے والی اور کہیں اتارنے والی اور یہ خود کار مشینیں اس قدر مضبوط، مربوط اور منظم طریقے سے کام کر رہی ہیں جن کا مطالعہ کرکے انسان اللہ تعالیٰ کی قدرتوں اور حکمتوں پر عش عش بھی کر اٹھتا ہے اور ورطۂ حیرت میں گم بھی ہو جاتا ہے۔ معدہ خالی ہو جائے تو از خود انسان کو بھوک اور پیاس لگتی ہے اور وہ کھانے پینے پر مجبور ہوتا ہے اور جب غذا معدہ میں پہنچ جاتی ہے تو یہ سب خود کار مشینیں اپنا اپنا کام شروع کر دیتی ہیں۔ اگر ان میں سے کسی کل میں خرابی واقع ہو جائے تو انسان بیمار پڑ جاتا ہے اور اگر خرابی درست نہ ہو بلکہ بڑھ جائے تو انسان مر جاتا ہے۔\nیہ تو تھا جسم کی اندرونی ساخت کا قصہ، اب اس کے قویٰ پر نظر دوڑائیے۔ جب بچہ پیدا ہوتا ہے تو اس میں زندگی کی ابتدائی خصوصیات کے سوا کچھ بھی نہیں ہوتا نہ سماعت، نہ بصارت، نہ گویائی، نہ چلنے یا بیٹھنے کی طاقت، نہ عقل و خرد، نہ کوئی اور خوبی۔ مگر وہ رحم مادر سے باہر آ کر کوئی اور ہی چیز بننا شروع ہو جاتا ہے۔ جس کو پیٹ والے جنین سے کوئی مناسبت نہیں ہوتی۔ تھوڑی ہی مدت میں وہ ایک سمیع و بصیر اور ناطق بچہ بن جاتا ہے۔"],[4563,"§انسان کا اور ہی چیز بن جانے کا مطلب\nاب وہ کچھ علم ماحول سے حاصل کرتا ہے اور کچھ اپنے ذاتی تجربہ اور مشاہدہ سے۔ ذرا اس میں عقل آتی ہے تو اس میں دوسروں سے مسابقت یا آگے نکل جانے کا جذبہ پیدا ہوتا ہے۔ اس کی یہ بیداری اور خودی اسے ہر اس چیز پر اپنا تحکم جتانے اور اپنا زور منوانے کی کوشش کرتی ہے۔ جس پر اس کا بس چل سکتا ہو اور اس کی یہی بیداری اور خودی اس میں ’’کوئی اور ہی چیز‘‘ ہونے کی کیفیت کو نمایاں تر اور افزوں تر کرتی چلی جاتی ہے۔ پھر وہ جوان اور پختہ عمر کا ہوتا ہے تو اس کی تمام قوتیں، طاقت اور قابلیتیں بھی بڑھتی جاتی ہیں اور ایک وقت آتا ہے جب اس میں ’’ہمچوما دیگرے نیست‘‘ کا تصور پیدا ہونا شروع ہو جاتا ہے۔ بسا اوقات بعض انسان ایسے محیر العقول کارنامے بھی سر انجام دیتے ہیں جو عام انسانوں کی بساط سے باہر ہوتے ہیں۔"],[4564,"§موت سے اخروی زندگی کا آغاز کیسے؟\n؟: یعنی جس طرح نطفہ سے انسان بننے میں تمہارا اپنا کچھ بھی اختیار نہ تھا اور اللہ نے اپنی قدرت کاملہ اور حکمت بالغہ سے مختلف مراحل طے کرا کر تمہیں پیدا بھی کیا اور ایک محیر العقول تخلیق بھی بنا دیا۔ اسی طرح موت کے بعد اسی جسم کے خلاصہ سے مختلف مراحل طے کراکر تمہیں دوبارہ اسی طرح زندہ پیدا کر دے گا۔ جس طرح پہلی بار کیا تھا۔ چنانچہ سورۃ انشقاق میں اللہ تعالیٰ نے کئی قسمیں کھانے کے بعد فرمایا: ﴿لَتَرْکَبُنَّ طَبَقًا عَنْ طَبَقٍ﴾ یعنی یہ مراحل تمہیں بہرحال طے کرنا ہوں گے۔ اللہ تعالیٰ نے پہلی تخلیق کے مراحل کا تو ذکر کئی مقامات پر فرما دیا اس لیے وہ انسان کے مشاہدہ میں آتے رہتے ہیں اور دوسری زندگی کے مراحل کا ذکر اس لیے نہیں فرمایا کہ نہ تو وہ انسان کے مشاہدہ میں آ سکتے ہیں اور نہ ہی انسان کی عقل ان مراحل کو سمجھ سکتی ہے۔"],[4565,"§کائنات کی تخلیق اور اس کی نگہداشت\nسبع طرائق سے بعض علماء نے سات آسمان یا سات طبقات مراد لیے ہیں۔ جیسے ارشاد باری ہے: ﴿اَلَمْ تَرَ کَیْفَ خَلَقَ اللّٰہُ سَبْعَ سَمٰوٰتٍ طِبَاقًا…﴾ اور بعض نے ان سے مراد سات راستے ہی لیے ہیں۔ جو فرشتوں کی آسمانوں میں آمد و رفت کے راستے ہیں اور آسمان چونکہ سات ہیں۔ اس لیے یہ راستے بھی سات ہیں اور بعض علماء نے ان سے سات سیاروں کے راستے یا مدار مراد لیے ہیں۔ چونکہ نزول قرآن کے زمانہ میں بطلیموسی نظریہ ہیئت بھی درست سمجھا جاتا تھا اور اس نظریہ کے مطابق سات سیارے ہی محوِ گردش ہیں اور وہ چاند، زہرہ، عطارد، سورج، مشتری، مریخ اور زحل۔ لہٰذا قرآن نے لوگوں کے علم اور سمجھ کے مطابق سات ہی راستوں کا ذکر فرمایا۔ اگرچہ اس سے زیادہ بھی ہو سکتے ہیں۔\nاور فَوْقَکُمْ یعنی تمہارے اوپر کے ایک معنی تو وہی ہیں جو عام فہم ہیں اور دوسرا مطلب یہ ہے کہ آسمانوں کی یا سیاروں اور ان کے مداروں کی تخلیق تمہاری تخلیق سے بہت بلند تر اور بڑی چیز ہے اور اس مطلب کی تائید بھی قرآن کریم کی اس آیت سے ہو جاتی ہے۔ ﴿لَخَلْقُ السَّمٰوٰتِ وَ الْاَرْضِ اَكْبَرُ مِنْ خَلْقِ النَّاسِ﴾ (المومن : 57)\nاس کی کچھ تفصیل سورۂ حج کے شروع میں گزر چکی ہے۔ یہاں اسے پھر بیان کیا گیا ہے۔ تاہم وہاں ﴿مُخَلَّقَۃ﴾ کا جو ذکر تھا، یہاں اس کی وضاحت ﴿مُضْغَۃٌ﴾ کو ہڈیوں میں تبدیل کرنے اور ہڈیوں کو گوشت پہنانے، سے کر دی ہے۔ ﴿مُضْغَۃٌ﴾ گوشت کو ہڈیوں میں تبدیل کرنے سے مقصد، انسانی ڈھانچے کو مضبوط بنیادوں پر کھڑا کرنا ہے۔ کیونکہ محض گوشت میں تو کوئی صلابت اور سختی نہیں ہوتی، پھر اگر اسے نرا ہڈیوں کا ڈھانچہ ہی رکھا جاتا، تو انسان میں وہ حسن و رعنائی نہ آتی، جو ہر انسان کے اندر موجود ہے۔ اس لیے ان ہڈیوں پر ایک خاص تناسب اور مقدار سے گوشت چڑھا دیا گیا کہیں کم کہیں زیادہ۔ تاکہ اس کے قد و قامت میں غیر موزونیت اور بھدا پن پیدا نہ ہو۔ بلکہ وہ حسن و جمال کا ایک پیکر اور قدرت کی تخلیق کا ایک شہ کار ہو۔ اسی چیز کو قرآن نے ایک دوسرے مقام پر اس طرح بیان فرمایا: ﴿لَقَدْ خَلَقْنَا الْاِنْسَانَ فِيْۤ اَحْسَنِ تَقْوِيْمٍٞ۰۰۴﴾ (التین : 4) ’’ہم نے انسان کو احسن تقویم یعنی بہت اچھی ترکیب یا بہت اچھے ڈھانچے میں بنایا۔‘‘\nاللہ کریم نے اس آیت کریمہ میں انسان کی تخلیق اور اس کے مدارج کا ذکر فرمایا ہے مقصود اللہ کی کمال قدرت سے لوگوں کو روشناس کرانا ہے تاکہ لوگ ایک اللہ کی عبادت کریں اللہ کی قدرت کے عجائبات (Miracles) سے ہے کہ انسان کو نطفہ مادہ منویہ (Seminal Fluid) سے پیدا فرمایا ارشاد نبوی ہے: ’’کہ والدہ کے رحم میں نطفہ چالیس دن کے بعد منجمد خون کی شکل اختیار کر لیتا ہے مزید چالیس دن گزرنے پر گوشت کا لوتھڑا (Flesh) بنتا ہے اس پر چالیس دن گزرنے کے بعد اس میں روح پھونکی جاتی ہے اس وقت حمل کا پانچواں مہینہ شروع ہو جاتا ہے اس پر اللہ تعالیٰ ایک فرشتہ بھیجتے ہیں اسے حکم دیا جاتا ہے کہ وہ اس پیدا ہونے والے بچے کے بارے میں اس کی خوراک اس کی موت اس کا بدبخت ہونا اس کا خوش نصیب ہونا تحریر کیا جائے حکم کے مطابق اس کو تحریر کر دیا جاتا ہے۔‘‘\n(بخاری، حدیث : 3208، مسلم، حدیث : 2643، جامع العلوم والحکم، حدیث: 4)\nمفسرین کا نقطۂ نظر یہ ہے کہ جس نطفہ سے انسان کی تخلیق ہوتی ہے وہ دراصل خون سے بنتا ہےا ور خون غذائی اشیاء سے بنتا ہے خواہ غذائی اشیاء کا تعلق نباتات سے ہے اگر حیوانات سے بھی ہے تو حیوانات کا وجود بھی تو نباتات سے تیار ہوتا ہے اور نباتات زمین کی مٹی اور پانی سے نکلتے ہیں اس لحاظ سے انسان کی تخلیق مٹی کے خلاصہ سے ہے بعد ازاں نطفہ منویہ باپ کی پشت سے ماں کے رحم میں پہنچتا ہے وہاں بچے کی ولادت سے پہلے نطفہ منجمد خون کی شکل اختیار کر لیتا ہے پھر منجمد خون (Frozen Blood) گوشت کا ٹکڑا بن جاتا ہے پھر ہم گوشت کے ٹکڑے میں جو اجزاء اس لائق ہوتے ہیں کہ انہیں ہڈیوں (Stone Bones) میں منتقل کیا جائے انہیں ادھر لے جایا جاتا ہے اور جو اجزاء گوشت بننے کی صلاحیت رکھتے ہیں انہیں گوشت کی شکل میں رہنے دیا جاتا ہے اور ہڈیوں کو گوشت کا لباس عطا کیا جاتا ہے چنانچہ گوشت ہڈیوں کو ڈھانپ لیتا ہے بعد ازاں ہم اس کو نشاۃ ثانیہ میں منتقل کرتے ہیں کہ اس میں روح کو ڈالا جاتا ہے اب اس میں زندگی کے آثار نمودار ہوتے ہیں اس میں گویائی، شنوائی اور بصارت کی قوت نمودار ہوتی ہے، مزید عجائب و غرائب سے اس کو مزین کر دیا جاتا ہے۔\nاللہ کی ذات عظیم قدرت کے ساتھ موصوف ہے ہر قسم کے نقص اور عیب سے پاک ہے مخلوق کی تصویر کشی میں اس کا کردار خبر دیتا ہے کہ ایک انسان دوسرے انسان سے تخلیق کی صنعت کے لحاظ سے نمایاں الگ نظر آتا ہے ہرگز اشتباہ راہ نہیں پاتا ہے اس حقیقت میں ہرگز کچھ اشتباہ نہیں ہے کہ اللہ تعالیٰ کی ذات کی برکات نمایاں ہیں اس نے کائنات کی جو تخلیق فرمائی ہے اس میں غور و فکر کے بعد زبان پر بے ساختہ یہ کلمہ گردش کرنے لگتا ہے کہ اللہ پاک کی ذات کی برکات کا اندازہ لگانے سے زبان پر یہ جملہ گردش کرنے لگتا ہے کہ اللہ کی ذات کی برکتوں کا نتیجہ ہے کہ اللہ کی مخلوق میں ہر لحاظ سے نہ صرف یہ کہ تنوع ہے بلکہ حسن، جاذبیت، کشش کا جلوہ کار فرما ہے۔\nسیّدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے پروردگار عالم کے ساتھ چار باتوں میں موافقت کو پایا ہے میں نے عرض کیا: اے اللہ کے پیغمبر صلی اللہ علیہ وسلم! کاش ہم مقام ابراہیم کے پیچھے نوافل ادا کیا کریں تو اللہ تعالیٰ نے ﴿وَ اتَّخِذُوْا مِنْ مَّقَامِ اِبْرٰهٖمَ مُصَلًّى١ؕ﴾ (البقرۃ: 125) ’’تم مقام ابراہیم کے سامنے دو رکعت ادا کرو۔‘‘ آیت کو نازل فرمایا، اور میں نے عرض کیا: اے اللہ کے پیغمبر صلی اللہ علیہ وسلم! آپ اپنی بیویوں کو پردہ کرنے کا حکم دیں اس لیے کہ آپ صلی اللہ علیہ وسلم کے پاس اچھے اور غلط کار دونوں طرح کے افراد آتے رہتے ہیں تو اللہ تعالیٰ نے سورہ احزاب کی آیت کو نازل کیا ﴿وَ اِذَا سَاَلْتُمُوْهُنَّ مَتَاعًا فَسْـَٔلُوْهُنَّ۠ مِنْ وَّرَآءِ حِجَابٍ١ؕ﴾ (الاحزاب : 53) ’’اور جب تم ان سے افادیت کا سوال کرو تو پردہ کے پیچھے سے سوال کرو۔‘‘ اور میں نے آپ صلی اللہ علیہ وسلم کی بیویوں کو مخاطب کرکے کہا تم مسلسل مطالبات کرنے سے باز آجائو یا اللہ پاک آپ کو تم سے بہتر بیویاں عطا کرے گا تو سورہ تحریم کی آیت نازل ہوئی: ﴿عَسٰى رَبُّهٗۤ اِنْ طَلَّقَكُنَّ﴾ (التحریم : 5) ’’قریب ہے اس کا پروردگار کہ اس کو تمہیں طلاق دینے کا حکم دے۔‘‘ اور جب یہ آیت کریمہ نازل ہوئی: ﴿وَلَقَدْ خَلَقْنَا الْاِنْسَانَ مِنْ سُلٰلَۃٍ﴾ ’’کہ ہم نے انسان کو نطفہ سے پیدا کیا۔‘‘ تو میں نے کہا: ﴿فَتَبٰرَکَ اللّٰہُ اَحْسَنُ الْخٰلِقِیْنَ﴾ ’’اللہ کی ذات برکت والی ہے جو بہت اچھا خالق ہے۔‘‘ اس پر نبی صلی اللہ علیہ وسلم نے فرمایا: اے عمر! آپ کے قول کے موافق یہ آیت نازل ہوئی ہے۔\n(صحیح بخاری، مسند احمد، المراغی : 272/6)\nثُمَّ اِنَّکُمْ بَعْدَ ذٰلِکَ لَمَیِّتُوْنَ: تم عدم سے نشاۃ اولیٰ میں داخل ہونے کے بعد اپنے وقت مقرر کے بعد موت سے ہمکنار ہو گے بعد ازاں قیامت کے دن جو حساب اور مجازات کا دن ہے تمہیں قبروں سے اٹھایا جائے گا ہر شخص کو اس کے عمل کا پورا پورا بدلہ ملے گا اگر زندگی میں اچھے کام کیے تھے تو بدلہ اچھا ملے گا اور برے اعمال کا بدلہ تو برا ہی ملے گا۔\nوَ اَنْزَلْنَا مِنَ السَّمَآءِ مَآءًۢ بِقَدَرٍ فَاَسْكَنّٰهُ فِي الْاَرْضِ١ۖۗ وَ اِنَّا عَلٰى ذَهَابٍۭ بِهٖ\nلَقٰدِرُوْنَۚ۰۰۱۸ فَاَنْشَاْنَا لَكُمْ بِهٖ جَنّٰتٍ مِّنْ نَّخِيْلٍ وَّ اَعْنَابٍ١ۘ لَكُمْ فِيْهَا فَوَاكِهُ\nكَثِيْرَةٌ وَّ مِنْهَا تَاْكُلُوْنَۙ۰۰۱۹ وَ شَجَرَةً تَخْرُجُ مِنْ طُوْرِ سَيْنَآءَ تَنْۢبُتُ بِالدُّهْنِ\nوَصِبْغٍ لِّلْاٰكِلِيْنَ۰۰۲۰ وَ اِنَّ لَكُمْ فِي الْاَنْعَامِ لَعِبْرَةً١ؕ نُسْقِيْكُمْ مِّمَّا فِيْ بُطُوْنِهَا\nوَلَكُمْ فِيْهَا مَنَافِعُ كَثِيْرَةٌ وَّ مِنْهَا تَاْكُلُوْنَۙ۰۰۲۱ وَ عَلَيْهَا وَ عَلَى الْفُلْكِ\nتُحْمَلُوْنَؒ۰۰۲۲\nاور ہم نے آسمان سے ایک (خاص) انداز سے پانی نازل کیا، پھر ہم نے اسے زمین میں ٹھہرایا، اور بلاشبہ ہم اسے لے جانے پر بھی یقیناً قادر ہیں* پھر ہم نے اس (پانی) کے ذریعے سے تمھارے لیے کھجوروں اور انگوروں کے باغات اُگائے، ان میں تمھارے لیے بہت سے (لذیذ) پھل ہیں اور ان میں سے بعض کو تم کھاتے ہو(اور وہ درخت (زیتون) جو طور سیناء میں پیدا ہوتا ہے، وہ کھانے والوں کے لیے تیل اور سالن لیے اگتا ہے) اور بلاشبہ تمھارے لیے چوپایوں میں ضرور (سامان) عبرت ہے، ہم تمھیں اس میں سے پلاتے ہیں جو ان کے پیٹوں میں (دودھ) ہے، اور تمھارے لیے ان میں کثیر منافع ہیں، اور ان میں\nسے بعض کو تم کھاتے ہو` اور ان (چوپایوں) پر اور کشتیوں پر تم سوار بھی کیے جاتے ہو~"],[4566,"§بارش، نباتات، درخت اور چوپائے اس کی قدرت کی نشانیاں ہیں\nاللہ تعالیٰ اپنے بندوں پر اپنی ان گنت اور بے شمار نعمتوں کے ضمن میں فرما رہا ہے کہ اس نے ایک اندازے کے مطابق آسمان سے بارش کا پانی نازل فرمایا، یعنی بقدر ضرورت، نہ اس قدر زیادہ کہ اس سے زمین اور آبادیاں تباہ ہو جائیں اور نہ اس قدر کم کہ اس سے فصلوں اور پھلوں کی ضرورت ہی پوری نہ ہو بلکہ اس نے اس قدر نازل فرمایا کہ اس سے فصلوں کو سیراب کرنے، خود پینے اور جانوروں کو پلانے کے علاوہ دیگر مقاصد پورے ہو سکیں حتیٰ کہ وہ زمینیں جن میں زراعت کے لیے زیادہ پانی کی ضرورت ہوتی ہے مگر وہ موسلا دھار بارش کو برداشت نہیں کر سکتیں، ان کے لیے بھی اللہ تعالیٰ دوسرے علاقوں سے پانی بہا کر لے آتا ہے جیسا کہ مصر کی زمین ہے، اسے بنجر زمین کہا جاتا ہے، اللہ تعالیٰ اس کے لیے نیل کے پانی کو لے آتا ہے جو اپنے ساتھ سرخ مٹی لے کر آتا ہے، اس مٹی کو بارش کے زمانے میں وہ حبشہ کی زمین سے بہا کر لے آتا ہے اور نیل کا پانی جب مصر میں پہنچتا ہے تو وہ یہاں سرخ مٹی کی تہ بھی بچھا دیتا ہے اور مصر کی زمین کو سیراب بھی کر دیتا ہے تاکہ یہاں کے لوگ اپنی زمینوں کو کاشت کر سکیں ورنہ یہاں کی زمین بنجر اور اس میں ریت کا عنصر غالب تھا، پاک ہے وہ ذات جو لطیف و خبیر اور رحیم و غفور ہے۔"],[4567,"§پانی کو قابل استعمال بنانا\nاور فرمایا: ﴿فَاَسْكَنّٰهُ فِي الْاَرْضِ١ۖۗ﴾ ’’پھر ہم نے اسے زمین میں ٹھہرا دیا۔‘‘ یعنی آسمان سے جب پانی برستا ہے تو زمین میں جمع ہو جاتا ہے اور زمین میں ہم نے یہ صلاحیت پیدا کی ہے کہ دانے اور کھجور کی گٹھلیاں اس سے پانی پی سکیں اور اپنی غذا حاصل کر سکیں۔ ﴿وَ اِنَّا عَلٰى ذَهَابٍۭ بِهٖ لَقٰدِرُوْنَۚ۰۰۱۸﴾ ’’اور بلاشبہ ہم اسے نابود کر دینے پر بھی قادر ہیں۔‘‘ یعنی اگر ہم چاہیں کہ بارش نہ برسے تو ہم ایسا کر سکتے ہیں اور اگر چاہیں کہ بارش تمہارے بجائے پہاڑوں، جنگلوں اور صحرائوں میں برسے تو ہم ایسا کر سکتے ہیں اور اگر ہم چاہیں کہ پانی اس قدر کڑوا ہو جائے کہ وہ پینے اور آب پاشی کے قابل نہ رہے تو ہم ایسا کر سکتے ہیں۔ اگر ہم چاہیں کہ پانی زمین کے اندر داخل نہ ہو بلکہ اس کی سطح ہی پر بہتا رہے تو ہم ایسا کر سکتے ہیں اور اگر ہم چاہیں کہ زمین میں داخل ہونے والا پانی اس قدر گہرائی میں چلا جائے کہ تمہاری وہاں تک دسترس نہ ہو اور تم اس پانی سے فائدہ نہ اٹھا سکو تو ہم ایسا کر سکتے ہیں مگر یہ اللہ تعالیٰ کا لطف و کرم اور اس کی رحمت ہے کہ وہ بادلوں سے شیریں و فرحت بخش اور ٹھنڈا اور صاف شفاف پانی نازل فرماتا ہے، پھر اسے زمین میں ٹھہراتا اور چشمے بنا کر چلا دیتا ہے، پھر وہ چشموں اور نہروں کو رواں دواں کر دیتا ہے اور ان سے فصلوں اور پھل دار درختوں کو سیراب کیا جاتا ہے اور تم اس پانی کو پیتے ہو، اپنے جانوروں اور مویشیوں کو پلاتے ہو اور اس سے غسل کرکے نظافت اور طہارت حاصل کرتے ہو۔ فَلَہُ الْحَمْدُ وَالْمِنَّۃ!\n﴿وَ شَجَرَةً تَخْرُجُ مِنْ طُوْرِ سَيْنَآءَ﴾ ’’اور وہ درخت (زیتون) جو طور سیناء میں پیدا ہوتا ہے۔‘‘ یعنی زیتون کا درخت اور طور کے معنی پہاڑ کے ہیں اور بعض نے کہا ہے کہ طور اس پہاڑ کو کہتے ہیں جس پر درخت ہوں اور اگر درخت نہ ہوں تو پھر اسے طور نہیں بلکہ جبل کہا جاتا ہے۔ واللہ اعلم! اور طور سیناء سے مراد طور سینین ہے اور یہ وہ پہاڑ ہے جس پر اللہ تعالیٰ نے موسیٰ علیہ السلام کو ہم کلامی کا شرف عطا فرمایا تھا اور اس پہاڑ اور اس کے گردونواح کے پہاڑوں پر زیتون کے درخت اگتے ہیں۔ اور فرمایا: ﴿تَنْۢبُتُ بِالدُّهْنِ وَ صِبْغٍ لِّلْاٰكِلِيْنَ۰۰۲۰﴾ ’’وہ کھانے والوں کے لیے روغن اور سالن لیے اگتا ہے۔‘‘ بعض نے کہا ہے کہ حرف ’’با‘‘ زائد ہے اور اصل میں تَنْبُتُ الدُّھْنَ تھا جیسا کہ عرب کہتے ہیں: اَلْقٰی فُلَانٌ بِیَدِہٖ، یعنی یَدَہٗ اور جنہوں نے حرف ’’با‘‘ کو زائد قرار نہیں دیا ان کے قول کے مطابق اس کے معنی تَخْرُجُ بِالدُّھْنِ یا تَاْتِی بِالدُّھْنِ ہیں، یعنی ان سے تیل نکلتا ہے۔ (تفسیر الطبری : 20/18 و تفسیر القرطبی : 116,115/2) اور ﴿وَ صِبْغٍ﴾ ’’کے معنی سالن کے ہیں، یہ امام قتادہ رحمہ اللہ کا قول ہے۔ (الدر المنثور : 14/5) ﴿لِّلْاٰكِلِيْنَ﴾ ’’کھانے والوں کے لیے۔‘‘ یعنی اس میں روغن اور رنگ ہے جس سے فائدہ اٹھایا جاتا ہے۔\nعبد بن حمید رحمہ اللہ نے اپنی مسند اور تفسیر میں سیّدنا عمر رضی اللہ عنہ کی روایت بیان کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((اِئْتَدِمُوا بِالزَّیْتِ وَادَّھِنُوا بِہٖ، فَاِنَّہٗ یَخْرُجُ مِنْ شَجَرَۃٍ مُّبَارَکَۃٍ)) ’’زیتون کو سالن بنائو اور بطور تیل استعمال کرو کیونکہ یہ مبارک درخت سے نکلتا ہے۔‘‘ (مسند عبد بن حمید، حدیث : 13) اسے امام ترمذی رحمہ اللہ اور ابن ماجہ رحمہ اللہ نے بھی روایت کیا ہے۔ (جامع الترمذی، حدیث : 1851 و سنن ابن ماجہ، حدیث : 3319)"],[4568,"§چوپائے قدرت کی نشانی ہیں\nفرمان باری تعالیٰ ہے: ﴿وَ اِنَّ لَكُمْ فِي الْاَنْعَامِ لَعِبْرَةً١ؕ نُسْقِيْكُمْ مِّمَّا فِيْ بُطُوْنِهَا وَ لَكُمْ فِيْهَا مَنَافِعُ كَثِيْرَةٌ وَّ مِنْهَا تَاْكُلُوْنَۙ۰۰۲۱ وَ عَلَيْهَا وَ عَلَى الْفُلْكِ تُحْمَلُوْنَؒ۰۰۲۲﴾ ’’اور بلاشبہ تمہارے لیے چوپایوں میں ضرور عبرت ہے کہ جو ان کے پیٹوں میں ہے اس سے ہم تمہیں (دودھ) پلاتے ہیں اور تمہارے لیے ان میں (اور بھی) بہت سے فائدے ہیں اور ان میں سے بعض کو تم کھاتے بھی ہو۔ اور ان پر اور کشتیوں پر تم سوار بھی کیے جاتے ہو۔‘‘ اللہ تعالیٰ نے ان فوائد کا ذکر فرمایا ہے جو اس نے چوپایوں میں رکھے ہیں اور وہ یہ کہ گوبر اور خون کے درمیان سے کشید ہو کر نکلنے والے دودھ کو لوگ پیتے ہیں، ان کے گوشت کھاتے ہیں، ان کی اونوں اور بالوں سے لباس تیار کرتے ہیں، ان کی پشتوں پر سوار ہوتے ہیں اور ان پر سازو سامان لاد کر دور دراز علاقوں میں لے جاتے ہیں جیسا کہ فرمایا: ﴿وَتَحْمِلُ اَثْقَالَكُمْ اِلٰى بَلَدٍ لَّمْ تَكُوْنُوْا بٰلِغِيْهِ اِلَّا بِشِقِّ الْاَنْفُسِ١ؕ اِنَّ رَبَّكُمْ لَرَءُوْفٌ رَّحِيْمٌۙ۰۰۷﴾ (النحل: 7) ’’اور وہ تمہارے بوجھ اٹھا کر ان شہروں تک لے جاتے ہیں جہاں تم زحمت شاقہ کے بغیر پہنچ نہیں سکتے، کچھ نہیں کہ تمہارا پروردگار نہایت شفقت والا، بڑا مہربان ہے۔‘‘ اور فرمایا: ﴿اَوَ لَمْ يَرَوْا اَنَّا خَلَقْنَا لَهُمْ مِّمَّا عَمِلَتْ اَيْدِيْنَاۤ اَنْعَامًا فَهُمْ لَهَا مٰلِكُوْنَ۰۰۷۱ وَ ذَلَّلْنٰهَا لَهُمْ فَمِنْهَا رَكُوْبُهُمْ وَ مِنْهَا يَاْكُلُوْنَ۰۰۷۲ وَ لَهُمْ فِيْهَا مَنَافِعُ وَ مَشَارِبُ١ؕ اَفَلَا يَشْكُرُوْنَ۰۰۷۳﴾ (یٰسٓ: 73,71) ’’کیا انہوں نے نہیں دیکھا کہ جو چیزیں ہم نے اپنے ہاتھوں سے بنائیں ان میں ہم نے ان کے لیے چوپائے بھی پیدا کر دیے، پھر وہ ان کے مالک (بن گئے) ہیں؟ اور ہم نے انہیں ان کے تابع کر دیا، چنانچہ کوئی ان میں سے ان کی سواریاں ہیں اور ان میں سے کچھ کو وہ کھاتے ہیں اور ان کے لیے ان میں (طرح طرح کے) فوائد اور مشروبات ہیں، کیا پھر وہ شکر نہیں کرتے؟‘‘"],[4569,"§پانی کی کل مقدار جو اللہ نے آسمان سے اتاری\nسوال یہ ہے کہ یہ ایک خاص مقدار میں پانی اللہ تعالیٰ نے کب اتارا تھا؟ اس کا ایک جواب یہ ہے کہ جب اللہ تعالیٰ نے زمین پیدا کی تو اس وقت ہی ایک خاص اور کثیر مقدار میں پانی اتار دیا تھا۔ اتنا کثیر مقدار میں جو قیامت تک زمین پر پیدا ہونے والی مخلوق، خواہ وہ کسی نوع سے تعلق رکھتی ہو، کی ضروریات کے لیے کافی ہو۔ اس کثیر مقدار کے ایک کثیر حصہ نے زمین کی تین چوتھائی سطح کو سمندروں کی شکل میں تبدیل کر رکھا ہے۔ پھر اس کثیر مقدار کا کثیر حصہ زمین کی سطح کے نیچے چلا گیا جیسے زمین کے نیچے بھی پانی کے دریا بہہ رہے ہیں اور سطح زمین کا کثیر حصہ ایسا ہے کہ جہاں سے کھودیں نیچے سے پانی نکل آتا ہے۔ جسے انسان نکال کر اپنے استعمال میں لاتا ہے اور کبھی زمین سے از خود چشمے ابل پڑتے ہیں۔ پھر اپنی مخلوق کی ضروریات کی تکمیل کے لیے اللہ تعالیٰ نے یہ سلسلہ قائم فرمایا کہ سورج کی گرمی سے سمندر سے آبی بخارات اوپر اٹھتے ہیں جو کسی سرد طبقہ میں پہنچ کر بادلوں کی شکل اختیار کر لیتے ہیں اور مزید سردی سے زمین پر برسنے لگتے ہیں۔ اس بارش کے پانی سے زمین کی تمام نباتات سیراب ہوتی ہے۔ جاندار بھی اپنی ضرورتیں پوری کرتے ہیں۔ پھر اس بارش کا کچھ حصہ زمین میں جذب ہو جاتا ہے اور باقی حصہ ندی نالوں اور دریائوں کی شکل میں پھر سمندروں میں جا گرتا ہے اور جو پانی مخلوق استعمال کرتی ہے وہ بھی بالآخر یا تو پانی کی شکل میں زمین میں چلا جاتا ہے یا بخارات بن کر ہوا میں مل جاتا ہے۔ ان تصریحات سے نتیجہ یہ نکلتا ہے کہ اللہ تعالیٰ نے پانی کی جتنی مقدار زمین پر نازل فرمائی تھی۔ اس مقدار میں نہ کچھ اضافہ ہوا ہے اور نہ ہی کمی واقع ہوئی ہے۔ البتہ اس طریقہ سے اللہ تعالیٰ نے اپنی مخلوق کی ضروریات کی تکمیل کا ایک مستقل اور دائمی انتظام مہیا فرما دیا ہے۔"],[4570,"§نیچریت اور دہریت کا رد\nاس سلسلہ میں حیران کن امر یہ ہے کہ پانی بذات خود ایک مرکب چیز ہے جو دو حصے ہائیڈروجن گیس اور ایک حصہ آکسیجن سے مل کر بنتا ہے (H2O)۔ ہائیڈروجن گیس ایک آتش گیر اور فوراً بھڑک اٹھنے والی گیس ہے اور آکیسجن وہ گیس ہے جو جلانے میں مدد دیتی ہے۔ گویا ان آتشیں خاصیت والے مادوں سے اللہ تعالیٰ نے وہ چیز پیدا کی جو آگ کو بجھا دیتی ہے اور پھر اسی کو کیمیاوی عمل کے ذریعہ پھاڑ کر انہیں گیسوں میں تبدیل کیا جا سکتا ہے اور دوسری حیران کن بات یہ ہے کہ ہائیڈروجن گیس اور آکسیجن گیس آج بھی وافر مقدار میں فضا میں موجود ہے اگر وہ از خود زمین کی پیدائش کے وقت مل کر پانی بن گئیں تھیں تو آج بھی مل کر پانی کی مقدار میں اضافہ کیوں نہیں کر دیتیں؟ نیچری اور دہریہ حضرات کے لیے یہ ایک بہت اہم لمحہ فکریہ ہے۔ ہمارے پاس تو اس کا واضح جواب موجود ہے کہ جتنا پانی بنانا اللہ کو منظور اور اس کے اندازہ کے موافق تھا اتنا بن گیا۔ ان گیسوں میں از خود یہ قدرت نہیں ہے کہ مل کر پانی بن جائیں۔\nاور اس جملہ کا دوسرا مطلب یہ ہے کہ اپنی مخلوق کی ضروریات کے مطابق آسمان سے بوقت ضرورت پانی برساتے ہیں۔ نہ اتنا زیادہ کہ مخلوق ڈوب کر مر جائے اور نہ اتنا کم کہ مخلوق قحط میں مبتلا ہو کر مر جائے۔ الا یہ کہ وہ عذابِ الٰہی ہی کی شکل ہو۔"],[4571,"§زیتون کا درخت اور اس کے فوائد\nاس درخت سے مراد زیتون کا درخت ہے۔ شام و فلسطین اس درخت کا اصلی وطن ہے اور طور سینا کا ذکر اس لیے کیا گیا کہ یہ اس علاقہ کا مشہور مقام ہے۔ اس درخت کی عمر، اس کا قد و قامت اور پھیلائو بہت زیادہ ہوتا ہے۔ جیسے ہمارے ہاں برگد کا درخت ہوتا ہے۔ جس کے زیادہ پھیلائو کی وجہ سے اس کی کئی شاخیں واپس زمین تک آکر اس کا سہارا بنتی ہیں۔ زیتون کے درخت سے تیل وافر مقدار میں حاصل ہوتا ہے۔ یہیں سے یہ تیل دنیا کے اکثر مقامات پر جاتا ہے۔ طبی لحاظ سے یہ تیل بہت مفید چیز ہے اور بہت سے لوگ اس کے پھل کا اچار ڈالتے ہیں۔ اس کے تیل کو سالن کے طور پر بھی استعمال کرتے ہیں اور سالن میں گھی کی جگہ بھی استعمال کرتے ہیں اس کی عام افادیت کے پیش نظر ہی اللہ تعالیٰ نے سورہ ’’التین‘‘ میں زیتون کی قسم بھی کھائی ہے۔"],[4572,"§دودھ کیسے اور کب بنتا ہے؟\n؟: چوپایوں میں عبرت یا حیران کن بات یہ ہے کہ گھاس پھوس کھانے والے اور چرنے والے مویشی (مادائوں) کے جسم میں جب غذا جاتی ہے تو اس سے خون اور فضلہ یا گوبر کے علاوہ ایک تیسری چیز بھی بنتی ہے جو اوصاف میں ان دونوں چیزوں سے یکسر مختلف ہوتی ہے۔ خون اور گوبر دونوں نجس اور حرام چیزیں ہیں۔ جبکہ دودھ نہایت پاکیزہ، حلال، طیب، انتہائی سفید رنگ، مزہ میں شیریں اور پینے میں خوشگوار ہوتا ہے اور مکمل غذا کا کام دیتا ہے۔ اس سے بھوک بھی دور ہو جاتی ہے اور پیاس بھی۔ اس میں اللہ تعالیٰ کا محیر العقول کارنامہ یہ ہے کہ اللہ تعالیٰ نے مدائوں کے جسم میں ایسی مشینری فٹ کر دی ہے جو گھاس پھونس سی چیز کو ایک نہایت اعلیٰ اور قیمتی چیز میں تبدیل کر دیتی ہے اور اس سے بھی زیادہ حیران کن بات یہ ہے کہ یہ مشینری صرف اس وقت حرکت میں آتی ہے جب حمل قرار پا جائے اور اس کا نتیجہ فوری طور پر نہیں نکلتا بلکہ بچہ کے وضع ہونے کے وقت تک یہ مشینری خون کو دودھ میں تبدیل کر دینے کے قابل بن جاتی ہے ادھر بچہ پیدا ہوتا ہے تو ادھر ماں کے پستان دودھ سے بھر جاتے ہیں اور بچہ پیدا ہوتے ہی جب ماں کے پستانوں کی طرف لپکتا ہے تو اسےفوراً یہ قدرتی غذا مہیا ہو جاتی ہے جبکہ وہ کوئی اور غذا کھانے کے قابل ہی نہیں ہوتا اور اگر ماں کو حمل قرار نہ پائے تو اس بات کے باوجود کہ دودھ بنانے والی یہی گوشت پوست اور رگ ریشہ پر مشتمل یہ مشینری اس کے اندر موجود ہے۔ کبھی اپنا کام نہ کرے گی اور نہ دودھ بنے گا نہ پستانوں میں اترے گا۔"],[4573,"§مویشیوں کے فوائد\nمویشیوں کی ایک ایک چیز انسان کے کام کی چیز ہے۔ ان کی کھال، ان کے بال، ان کی ہڈیاں، غرض یہ کہ ہر چیز سے انسان فائدہ اٹھاتا ہے۔ زندہ ہوں تو ان پر سواری بھی کرتا ہے اور یہ کھیتی باڑی اور بار برداری کے کام بھی آتے ہیں۔ پھر ان کا گوشت انسان بطور خوراک بھی استعمال کرتا ہے اور دودھ جو ان سے ھاصل ہوتا ہے وہ ان سب فوائد سے بڑھ کر ہے۔\nیعنی یہ انتظام بھی کیا کہ سارا پانی برس کر فوراً بہہ نہ جائے اور ختم نہ ہو جائے بلکہ ہم نے چشموں، نہروں، دریائوں اور تالابوں اور کنوئوں کی شکل میں اسے محفوظ بھی کیا ہے، (کیونکہ ان سب کی اصل بھی آسمانی بارش ہی ہے) تاکہ ان ایام میں جب بارشیں نہ ہوں، یا ایسے علاقے میں جہاں بارش کم ہوتی ہے اور پانی کی ضرورت زیادہ ہے، ان سے پانی حاصل کر لیا جائے۔\nوَاَنْزَلْنَا مِنَ السَّمَآءِ مَآءً: اور ہم نے اپنی عظمت کے ساتھ آسمان کی جانب سے اس قدر بارش اتارتے ہیں جس سے کھیت، درخت سیراب ہوں اور چٹیل میدانوں میں روئیدگی ظہور پذیر ہو اور ضرورت کے مطابق بارش کا پانی نہروں کی وساطت سے دریائوں اور سمندر میں داخل ہو اگر سمندروں میں پانی اوپر کی سطح سے ہی نازل ہوتا تو سمندروں کے پانی سے زمین پانی میں ڈوب جاتی اور اگر بارش کا نزول نہ ہوتا تو زمین پر نباتات اور درخت سوکھ جاتے، حقیقت یہ ہے کہ ہم نے اپنی عظمت کے ساتھ زمین کو آباد رکھا ہوا ہے جبکہ ہم اس کے ختم کرنے پر بھی قادر ہیں اور پانی کے نہ ہونے کے ساتھ ہم اپنی برکت کو چھین لیتے ہیں پس تمہارے لیے ضروری ہے کہ تم ان کاموں سے دور رہو جن سے ہمیں ناراضگی حاصل ہو ہم تو اپنے لطف و کرم اور رحمت کے ساتھ تم پر میٹھا پانی اتارتے ہیں اور اسے زمین میں داخل کر دیتے ہیں بعض اوقات چشموں (Fountains) کی شکل میں پانی کو چلاتے ہیں تاکہ تم اپنے کھیتوں اور پھلوں کو سیراب کرو اور نہ صرف تم بلکہ تمہارے چار پائے بھی پانی سے سیراب ہوں ہم بارش کو اتار کر تمہارے کھجوروں اور انگوروں کے باغات کو سیراب کرتے ہیں باغات میں کھجوریں اور انگور نشوونما پاتے ہیں جو تمہاری خوراک بنتے ہیں اور ہم نے تمہارے لیے طور سیناء کی وادی میں زیتون کے درخت کو پیدا کیا جس سے زیتون (Olive) کا پھل تمہارے استعمال میں آتا ہے تم اس سے تیل (Oil) نکالتے ہو جس کو تم اپنے جسم پر لگاتے ہو بلکہ اسے بطور سالن (Curry) کے استعمال کرتے ہو۔\nوَاِنَّ لَکُمْ فِی الْاَنْعَامِ لَعِبْرَۃً: اور بلاشبہ چارپایوں کے پیدا کرنے میں تمہارے لیے عبرت کا سامان موجود ہے جبکہ وہ تمہارے لیے عظیم نعمت بھی ہیں عبرت کی وضاحت یوں ہے کہ جانوروں کے جسم کا خون غذا سے ظہور پذیر ہوتا ہے وہ خون جانور میں پستانوں کی غدود سے لذیذ عمدہ مشروب دودھ نکلتا ہے یہ خالق کائنات کی قدرت پر واضح دلیل ہے کہ تم دودھ سے فوائد حاصل کرتے ہو تم دودھ کو دہی، گھی، پنیر (Cheese) شکل میں بنا کر خوراک میں اپنے کام و دہن کو لذتوں سے ہم کنار کرتے ہو اس کے علاوہ بھی تم جانوروں کی اون ان کے بالوں سے اپنا لباس تیار کرتے ہو جسے موسم سرما میں پہنتے ہو اور جنگلات (Forests) میں رہائش اختیار کرتے وقت ان سے خیمے بناتے ہو اور حلال جانوروں کو ذبح کرکے ان کا گوشت تناول کرتے ہو جس سے تم نہ صرف یہ کہ لذت سے ہم کنار ہوتے ہو بلکہ تمہاری بھوک بھی دور ہوتی ہے اور کچھ ایسے جانور بھی ہیں جن کی پشت پر تم سواری کرتے ہو بلکہ بھاری بھاری بوجھ ان کی کمر پر رکھتے ہو اور وہ جانور تمہارے بوجھ کو ایسے شہروں کی جانب پہنچاتے ہیں کہ جہاں تم انہیں نہایت مشقت اتھا کر پہنچا سکتے گویا کہ وہ کشتیاں ہیں سمندر کے سفر میں جن پر تم اپنا سامان رکھتے ہو اور منزل مقصود تک لے جاتے ہو۔ (نظم الدرر : 121/11، المراغی : 277/6)\nوَ لَقَدْ اَرْسَلْنَا نُوْحًا اِلٰى قَوْمِهٖ فَقَالَ يٰقَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِّنْ اِلٰهٍ غَيْرُهٗ١ؕ\nاَفَلَا تَتَّقُوْنَ۰۰۲۳ فَقَالَ الْمَلَؤُا الَّذِيْنَ كَفَرُوْا مِنْ قَوْمِهٖ مَا هٰذَاۤ اِلَّا بَشَرٌ مِّثْلُكُمْ١ۙ\nيُرِيْدُ اَنْ يَّتَفَضَّلَ عَلَيْكُمْ١ؕ وَ لَوْ شَآءَ اللّٰهُ لَاَنْزَلَ مَلٰٓىِٕكَةً١ۖۚ مَّا سَمِعْنَا بِهٰذَا فِيْۤ\nاٰبَآىِٕنَا الْاَوَّلِيْنَۚ۰۰۲۴ اِنْ هُوَ اِلَّا رَجُلٌۢ بِهٖ جِنَّةٌ فَتَرَبَّصُوْا بِهٖ حَتّٰى حِيْنٍ۰۰۲۵\nاور بلاشبہ ہم نے نوح کو اس کی قوم کی طرف بھیجا تو اس نے کہا: اے میری قوم! اللہ کی عبادت کرو، اس کے سوا تمھارے لیے کوئی معبود نہیں، تو کیا تم ڈرتے نہیں؟ - چنانچہ اس کی قوم کے سردار، جنھوں نے کفرکیا، کہنے لگے: یہ تو تم جیسا ہی بشر ہے، وہ چاہتا ہے کہ تم پر فضیلت پائے اور اگر اللہ چاہتا تو (آسمان سے) فرشتے ضرور نازل کرتا، ہم نے پہلے باپ دادا میں یہ (توحید) نہیں\nسنی_ یہ ایک آدمی ہی تو ہے جسے جنون لاحق ہے، لہٰذا تم ایک وقت تک اس کی بابت انتظار کرو="],[4574,"§سیّدنا نوح علیہ السلام اور آپ کی قوم کا قصہ\nاللہ تعالیٰ نے بیان فرمایا ہے کہ اس نے جب نوح علیہ السلام کو ان کی قوم کی طرف بھیجا تاکہ وہ اللہ تعالیٰ کے ساتھ شرک کرنے والوں، اس کے حکم کی مخالفت کرنے والوں اور اس کے رسولوں کی تکذیب کرنے والوں کو اللہ تعالیٰ کے انتقام، اس کی سخت گرفت اور اس کے شدید عذاب سے ڈرائیں۔ ﴿فَقَالَ يٰقَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِّنْ اِلٰهٍ غَيْرُهٗ١ؕ اَفَلَا تَتَّقُوْنَ۰۰۲۳﴾ ’’تو اس نے کہا: اے میری قوم! اللہ ہی کی عبادت کرو اس کے سوا تمہارا کوئی معبود نہیں، پس کیا تم ڈرتے نہیں؟‘‘ کیا تم اللہ تعالیٰ کے ساتھ شرک کرنے سے ڈرتے نہیں ہو؟ قوم کے اکابر اور سرداروں نے جواب دیا: ﴿مَا هٰذَاۤ اِلَّا بَشَرٌ مِّثْلُكُمْ١ۙ يُرِيْدُ اَنْ يَّتَفَضَّلَ عَلَيْكُمْ١ؕ﴾ ’’یہ تو تم جیسا ہی آدمی ہے، وہ چاہتا ہے کہ تم پر فضیلت پائے۔‘‘ چاہتا ہے کہ اسے تم پر فوقیت حاصل ہو اور اپنے آپ کو تم سے بڑا ثاتب کرنے کے لیے اس نے نبوت کا دعویٰ کر دیا ہے، حالانکہ یہ تم جیسا آدمی ہی ہے تو یہ کیسے ہو سکتا ہے کہ اللہ تعالیٰ نے تمہیں چھوڑ کر اسے نبی بنا دیا؟ ﴿وَ لَوْ شَآءَ اللّٰهُ لَاَنْزَلَ مَلٰٓىِٕكَةً١ۖۚ﴾ ’’اور اگر اللہ چاہتا تو (آسمان سے) فرشتے ضرور اتار دیتا۔‘‘ یعنی اللہ تعالیٰ اگر کسی کو نبی بنا کر بھیجنا چاہتا تو وہ کسی فرشتے کو یہ کام سپرد کر دیتا۔ انسان کو اس نے نبی بنایا ہو، یہ ہم نے آج تک نہیں سنا، یعنی ان کے کہنے کا مقصد یہ تھا کہ گزشتہ زمانوں میں ہمارے آباء و اجداد کے دور میں بھی ایسا کبھی نہیں ہوا تھا کہ اللہ نے کسی انسان کو نبی بنا کر بھیجا ہو۔ ﴿اِنْ هُوَ اِلَّا رَجُلٌۢ بِهٖ جِنَّةٌ﴾ ’’یہ ایک آدمی ہی تو ہے جسے دیوانگی کا عارضہ ہے۔‘‘ یعنی یہ جنون ہے جو یہ دعویٰ کرتا ہے کہ اللہ تعالیٰ نے نبوت و رسالت کے لیے اسے منتخب کیا اور تمہاری طرف رسول بنا کر بھیجا ہے۔ ﴿فَتَرَبَّصُوْا بِهٖ حَتّٰى حِيْنٍ۰۰۲۵﴾ ’’لہٰذا تم ایک وقت تک اس کی بابت انتظار کرو۔‘‘ اس کے بارے میں حوادث زمانہ کا انتظار کرو اور کچھ مدت تک صبر کر لو حتیٰ کہ اس سے آرام پا جائو۔"],[4575,"§رسول کا بشر ہونا کیوں ضروری ہے\nتمام انبیاء اور رسل ہمیشہ بشر ہی ہوتے تھے اور انسانوں کے لیے رسول بھی کوئی بشر ہی ہونا چاہیے جو انہی میں سے ہو تاکہ جب وہ انہیں اپنی زبان میں اللہ کا پیغام پہنچائیں تو وہ اسے سمجھ سکیں۔ نیز رسول کا کام صرف اللہ کا پیغام پہنچانا ہی نہیں ہوتا۔ ان احکام پر سب سے پہلے خود عمل پیرا ہو کر عملی نمونہ دکھانا بھی ہوتا ہے۔ اب اگر رسول انسان کے بجائے فرشتہ ہو یا نوری مخلوق ہو یا کسی اور اعلیٰ جنس سے ہو۔ تو اس پر ایمان لانے والے یہ کہہ سکتے ہیں کہ ہم لوگ انسان ہو کر ایک فرشتہ یا کسی بالاتر جنس والی ہستی کی اقتدا کیسے کر سکتے ہیں۔ یہی وہ مصلحتیں ہیں جن کی بنا پر رسول کا بشر ہونا۔"],[4576,"§نور و بشر کی بحث\nلیکن گمراہ لوگوں کی گمراہیوں میں سے ایک یہ گمراہی بھی بطور قدر مشترک رہی ہے۔ بشریت اور رسالت دونوں صفات اکٹھی نہیں ہو سکتیں انبیاء کی تکذیب کرنے والوں نے سب سے پہلے بطور طعنہ انبیاء سے یہی بات کہی کہ تم تو ہم جیسے بشر ہو تم رسول بن کیسے سکتے ہو؟ یہ ایک طرح کی گمراہی تھی اور دوسری طرح کی گمراہی انبیاء کے عقیدت مندوں میں پیدا ہوتی ہے۔ جو غلو کی راہ اختیار کرکے دوسری انتہاء کو پہنچتے ہیں۔ ان کا نظریہ بھی یہی ہوتا ہے کہ نبوت یا رسالت اور بشریت ایک ہی شخص میں جمع نہیں ہو سکتیں۔ فرق یہ پڑ جاتا ہے کہ وہ رسالت کا تو اقرار کرتے ہیں مگر بشریت سے انکار کر دیتے ہیں۔ دور کیوں جائیے ہم مسلمانوں میں ایک ایسا طبقہ موجود ہے جو رسول اللہ صلی اللہ علیہ وسلم کو بشر کہنے والوں کو ’’گستاخانِ رسول‘‘ کا طعنہ دیتا ہے۔ چنانچہ ان کا یہ زبان زد نعرہ ’’بشر عرش توں پار جا کوئی نہیں سکدا‘‘ ان کے اسی نظریہ کی ترجمانی کرتا ہے یہ لوگ آپ صلی اللہ علیہ وسلم کو بشر کے بجائے نور ثابت کرتے ہیں اور بشریت سے انکار کرتے ہیں۔"],[4577,"§انبیاء اور دوسرے لوگوں کے حصولِ اقتدار میں فرق\nپھر یہ بات بھی واضح ہے کہ انبیاء کو بھی بالآخر اللہ کی مدد سے اقتدار حاصل ہو جاتا ہے۔ مگر ان دونوں کے اقتدار کے حصول میں زمین و آسمان کا فرق ہوتا ہے۔ ایک دنیا دار کا مقصود ہی اقتدار کا حصول ہوتا ہے۔ جبکہ ایک نبی کا اصل مقصود احکامِ الٰہیہ کا نفاذ ہوتا ہے اور اس کے لیے وہ اقتدار کو محض ایک ذریعہ بناتا ہے۔ اس فرق کی یہ مثال یوں سمجھیے کہ ایک آدمی قتل ناحق کرتا ہے تو یہ سراسر فساد ہے اور ایک جج اس قاتل کو قصاص میں قتل کی سزا دیتا ہے تو یہ سراسر عدل اور رحمت اور فساد کی روک تھام ہے۔ جبکہ نفس قتل کے لحاظ دونوں واقعات ایک جیسے ہی ہوتے ہیں۔\nیہ حقیقت ہے کہ ہم نے نوح علیہ السلام کو اس کی قوم کی جانب مبعوث کیا تاکہ انہیں عذاب الٰہی کے نازل ہونے سے خوف زدہ کرے جبکہ وہ اللہ کے ساتھ اس کی مخلوق کو شریک بنا رہے ہیں اور ان کی جانب جو پیغمبر اللہ کا پیغام لایا کہ تم ایک اللہ کی عبادت کرو اس کے ساتھ کسی کو شریک نہ بنائو اس کے سوا تمہارا کوئی پروردگار نہیں نہ کوئی معبود ہے تمہیں اللہ کے عذاب سے بچائو اختیار کرنا چاہیے کہ تم اللہ کے سوا کسی کو اپنا معبود نہ سمجھو۔\nلیکن قوم نوح کے رؤساء جو کفر میں مستغرق تھے اور ان کی اطاعت کی جاتی تھی انہوں نے برملا نوح علیہ السلام کی مخالفت کی اور استکبار کے انداز میں کہا کہ نوح کو ہم پر تفوق حاصل نہیں ہے کہ ہم اس کی نبوت کو تسلیم کریں، دراصل وہ سیادت کا خواہش مند ہے اور تم پر حکمرانی کرنا چاہتا ہے، مزید برآں انہوں نے کہا کہ اگر اللہ چاہتا کہ ہم اللہ کے علاوہ کسی کی عبادت نہ کریں تو وہ فرشتوں کو ہماری جانب بھیج دیا اس کے علاوہ نوح پیغمبر جس بات کی جانب دعوت دے رہا ہے کہ معبود حقیقی ایک اللہ کی ذات ہے اس کے سوا کوئی پروردگار اور معبود نہیں ہے یہ اس کی انوکھی بات ہے ہم نے اپنے آبائو اجداد سے ایسی بات نہیں سنی ہے، معلوم ہوا ان کی اپنی کوئی رائے نہ تھی وہ تو اپنے آبائو اجداد کی قلید پر مصر تھے اس لیے انہوں نے نوح علیہ السلام کی نبوت کا انکار کیا۔\nقَالَ رَبِّ انْصُرْنِيْ بِمَا كَذَّبُوْنِ۰۰۲۶ فَاَوْحَيْنَاۤ اِلَيْهِ اَنِ اصْنَعِ الْفُلْكَ بِاَعْيُنِنَا\nوَوَحْيِنَا فَاِذَا جَآءَ اَمْرُنَا وَ فَارَ التَّنُّوْرُ١ۙ فَاسْلُكْ فِيْهَا مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ\nوَاَهْلَكَ اِلَّا مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ مِنْهُمْ١ۚ وَ لَا تُخَاطِبْنِيْ فِي الَّذِيْنَ ظَلَمُوْا١ۚ\nاِنَّهُمْ مُّغْرَقُوْنَ۰۰۲۷ فَاِذَا اسْتَوَيْتَ اَنْتَ وَ مَنْ مَّعَكَ عَلَى الْفُلْكِ فَقُلِ الْحَمْدُ\nلِلّٰهِ الَّذِيْ نَجّٰىنَا مِنَ الْقَوْمِ الظّٰلِمِيْنَ۰۰۲۸ وَ قُلْ رَّبِّ اَنْزِلْنِيْ مُنْزَلًا مُّبٰرَكًا وَّ اَنْتَ\nخَيْرُ الْمُنْزِلِيْنَ۰۰۲۹ اِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ وَّ اِنْ كُنَّا لَمُبْتَلِيْنَ۰۰۳۰\nنوح نے کہا: اے میرے رب! میری مدد کر کہ انھوں نے مجھے جھٹلایا+ چنانچہ ہم نے اس کی طرف وحی کہ ہماری آنکھوں کے سامنے اور ہماری وحی کے مطابق کشتی بنا، پھر جب ہمارا حکم آ جائے اور تنور ابل پڑے تو اس میں ہر قسم کے جوڑے سے دو (نر اور مادہ) اور اپنے اہل و عیال داخل (سوار) کر لے، سوائے اس کے جس کے متعلق ان میں سے (ہمارا) قول پہلے ہی آ چکا، اور تو مجھ سے ظالموں کے بارے میں بات نہ کرتا، بلاشبہ وہ غرق کیے جائیں گے پھر جب تو اور تیرے ساتھی اطمینان سے کشتی پر سوار ہو چکیں تو کہہ: تمام حمد اللہ ہی کے لیے ہے جس نے ہمیں ظالم قوم سے نجات دی رضی اللہ عنہما اور کہہ: اے میرے رب! تو مجھے با برکت اتارنا، اور تو سب سے بہتر اتارنے والا ہے صلی اللہ علیہ وسلم بے شک اس (واقعے) میں بھی نشانیاں ہیں، اور بلاشبہ ہم ہی\nآزمانے والے ہیں رضی اللہ عنہا"],[4578,"§نزولِ عذاب اور مومنوں کے لیے نجات\nاللہ تعالیٰ نے نوح علیہ السلام کے بارے میں بیان فرمایا ہے کہ آپ نے اپنے رب تعالیٰ سے دعا کی کہ وہ اس کی قوم کے خلاف اس کی مدد فرمائے جیسا کہ اللہ تعالیٰ نے دوسری آیت میں فرمایا ہے: ﴿فَدَعَا رَبَّهٗۤ اَنِّيْ مَغْلُوْبٌ فَانْتَصِرْ۰۰۱۰﴾ (القمر : 10) ’’تب اس نے اپنے پروردگار سے دعا کی کہ (ان کے مقابلے میں) میں کمزور ہوں تو ان سے بدلہ لے۔‘‘ اور یہاں فرمایا: ﴿رَبِّ انْصُرْنِيْ بِمَا كَذَّبُوْنِ۰۰۲۶﴾ ’’میرے پروردگار! انہوں نے مجھے جھٹلایا ہے تو میری مدد کر۔‘‘ تو اللہ تعالیٰ نے انہیں حکم دیا کہ آپ ایک مضبوط و مستحکم کشتی بنائیں اور اس میں تمام حیوانات، نباتات اور پھلوں وغیرہ میں سے نر اور مادہ کا ایک ایک جوڑا بٹھائیں اور اپنے گھر والوں کو بھی اس میں سوار کریں۔ ﴿اِلَّا مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ مِنْهُمْ١ۚ﴾ ’’سوائے ان کے جن کی نسبت ان میں سے ہمارا حکم پہلے ہی آ چکا ہے۔‘‘ یعنی جن کے بارے میں اللہ تعالیٰ نے یہ فیصلہ فرما دیا ہے کہ وہ ہلاک ہو کر رہیں گے۔ ان سے مراد وہ لوگ ہیں جو ان کے گھر والوں میں سے ایمان نہیں لائے تھے، مثلاً: ان کا بیٹا اور ان کی بیوی۔ واللہ اعلم!\n﴿وَ قُلْ رَّبِّ اَنْزِلْنِيْ مُنْزَلًا مُّبٰرَكًا وَّ اَنْتَ خَيْرُ الْمُنْزِلِيْنَ۰۰۲۹﴾ یعنی تمہیں ایک نعمت ابھی عطا ہونا باقی ہے، اس کے بارے میں اللہ تعالیٰ سے دعا مانگو کہ وہ تمہیں بابرکت منزل میسر کرے، چنانچہ اللہ تعالیٰ نے سیّدنا نوح علیہ السلام کی دعا سن لی اور فرمایا: ﴿وَ قُضِيَ الْاَمْرُ وَ اسْتَوَتْ عَلَى الْجُوْدِيِّ وَ قِيْلَ بُعْدًا لِّلْقَوْمِ الظّٰلِمِيْنَ۰۰۴۴﴾ (ہود:44) ’’اور فیصلہ چکا دیا گیا اور کشتی جودی پہاڑ پر جا ٹھہری اور کہہ دیا گیا لعنت ہے ظالموں پر۔‘‘ اور فرمایا: ﴿قِيْلَ يٰنُوْحُ اهْبِطْ بِسَلٰمٍ مِّنَّا وَ بَرَكٰتٍ عَلَيْكَ وَ عَلٰۤى اُمَمٍ مِّمَّنْ مَّعَكَ١ؕ﴾ (ہود: 48) ’’کہا گیا اے نوح! اتر جا، سلامتی کے ساتھ ہماری طرف سے اور برکتیں ہوں تجھ پر اور ان گروہوں پر جو تیرے ساتھ ہیں۔‘‘ ﴿اِنَّ فِیْ ذٰلِکَ﴾ بلاشبہ اس قصہ میں ﴿لَاٰیٰتٍ﴾ ’’نشانیاں ہیں۔‘‘ جو دلالت کرتی ہیں کہ اللہ تعالیٰ ہی اکیلا معبود ہے اور اس کے رسول نوح علیہ السلام سچے ہیں اور ان کی قوم جھوٹی ہے، نیز دلالت کرتی ہیں کہ اللہ تعالیٰ کی رحمت اس کے بندوں پر سایہ کناں ہے کہ اس نے انہیں ان کے باپ سیّدنا نوح علیہ السلام کی صلب میں، کشتی پر سوار کرکے محفوظ کیا جبکہ روئے زمین پر بسنے والے تمام لوگ ڈوب گئے اور کشتی بھی اللہ تعالیٰ کی نشانیوں میں سے ایک نشانی ہے۔ اللہ تعالیٰ نے فرمایا: ﴿وَ لَقَدْ تَّرَكْنٰهَاۤ اٰيَةً فَهَلْ مِنْ مُّدَّكِرٍ۰۰۱۵﴾ (القمر : 15) ’’ہم نے اس کشتی کو نشانی کے طور پر چھوڑ دیا۔ تو ہے کوئی نصیحت پکڑنے والا؟‘‘ اسی لیے اس کو یہاں جمع کیا ہے کیونکہ یہ متعدد آیات و مطالب پر دلالت کرتی ہے۔ ﴿وَّاِنْ کُنَّا لَمُبْتَلِیْنَ﴾ ’’اور ہم آزمائش کرکے ہی رہتے ہیں۔‘‘\nسیدنا نوح علیہ السلام کا زمانہ تبلیغ غالباً تمام انبیاء سے زیادہ ہے جو قرآن کی صراحت کے مطابق ساڑھے نو سو سال ہے۔ اس طویل عرصہ میں آپ اپنی قوم سے ناروا باتیں اور طعنے وغیرہ سنتے اور برداشت کرتے رہے۔ اتنی طویل مدت میں بہت ہی کم لوگ ایمان لائے۔ دوسروں کا کیا ذکر آپ کی بیوی اور ایک بیٹا بھی آپ کے مقابلہ میں کافروں کا ساتھ دے رہے تھے۔ سیدنا نوح علیہ السلام کو یہ یقین ہو گیا کہ اب جو کافر موجود ہیں وہ اس قدر ضدی اور ہٹ دھرم واقع ہوئے ہیں اور ان میں سے کوئی بھی دعوت حق کو قبول کرنے کو تیار نہیں ہوگا۔ بس یہ لوگ صرف سیدنا نوح علیہ السلام کی اذیت اور ذہنی کوفت کا باعث بن رہے تھے۔ جب ان کافروں نے آپ کو اذیت دینے میں انتہاء کر دی تو اس وقت آپ نے دعا کی کہ یا اللہ! یہ قوم مجھ پر غالب آ گئی ہے اب توہی میری مدد فرما اور ان سے اس ظلم کا بدلہ لے جو انہوں نے اتنی طویل مدت مجھ پر ڈھایا ہے۔\nسیدنا نوح علیہ السلام کے قصہ میں کئی ایسی باتیں ہیں جن سے ایک غور کرنے والا انسان سبق حاصل کر سکتا ہے اور جب ہم کوئی نبی بھیجتے ہیں تو اس وقت قوم کا امتحان شروع ہو جاتا ہے۔ نبی اور اس کے پیروکاروں کا بھی کہ وہ کس حد تک صبر و ثبات سے کام لیتے ہیں اور جھٹلانے والوں کا بھی کہ وہ کس حد تک سرکشی اختیار کرتے ہیں۔ پھر جو اس امتحان میں کامیاب ہوں انہیں انعامات سے نوازتے بھی ہیں اور ان کی مدد بھی کرتے ہیں اور معاندین کو قرار واقعی سزا بھی دیتے ہیں۔ پھر یہ بھی دیکھتے ہیں کہ بعد میں آنے والی قوم میں سے کون ان نشانیوں کو دیکھ کر عبرت و نصیحت حاصل کرتا ہے اور کون نہیں کرتا؟‘‘\nساڑھے نو سو سال کی تبلیغ و دعوت کے بعد، بالآخر رب سے دعا کی، ﴿فَدَعَا رَبَّهٗۤ اَنِّيْ مَغْلُوْبٌ فَانْتَصِرْ۰۰۱۰﴾ (القمر : 10) ’’نوح نے رب سے دعا کی، میں مغلوب اور کمزور ہوں میری مدد کر۔‘‘ اللہ تعالیٰ نے دعا قبول فرمائی اور حکم دیا کہ میری نگرانی اور ہدایت کے مطابق کشتی تیار کرو۔ کشتی میں بیٹھ کر اللہ کا شکر ادا کرنا کہ اس نے ظالموں کو بالآخر غرق کرکے، ان سے نجات عطا فرمائی اور کشتی کے خیر و عافیت کے ساتھ کنارے پر لگنے کی دعا کرنا: ((رَبِّ اَنْزِلْنِیْ مُنْزَلًا مُّبَارَکًا وَّاَنْتَ خَیْرُ الْمُنْزِلِیْنَ))اس کے ساتھ وہ دعا بھی پڑھ لی جائے جو نبی صلی اللہ علیہ وسلم، سواری پر بیٹھتے وقت پڑھا کرتے تھے: ((اَللہُ اَکْبَرُ، اَللہُ اَکْبَرُ، اَللہُ اَکْبَرُ)) ﴿سُبْحٰنَ الَّذِيْ سَخَّرَ لَنَا هٰذَا وَ مَا كُنَّا لَهٗ مُقْرِنِيْنَۙ۰۰۱۳ وَ اِنَّاۤ اِلٰى رَبِّنَا لَمُنْقَلِبُوْنَ۠۰۰۱۴﴾ (الزخرف: 14,13) یعنی اس سرگزشت نوح میں کہ اہل ایمان کو نجات دی گئی اور کافروں کو ہلاک کر دیا گیا، نشانیاں ہیں اس امر پر کہ انبیاء جو کچھ اللہ کی طرف سے لے کرآتے ہیں، ان میں وہ سچے ہیں۔ نیز یہ کہ اللہ تعالیٰ ہر چیز پر قادر اور کشمکش حق و باطل میں ہر بات سے آگاہ ہے اور وقت آنے پر اس کا نوٹس لیتا ہے اور اہل باطل کی پھر اس طرح گرفت کرتا ہے کہ اس کے شکنجے سے کوئی نکل نہیں سکتا۔\nمزید انہوں نے کہا کہ نوح جو خود کو پیغمبر کہتا ہے یہ پیغمبر نہیں ہے اس کی دماغی کیفیت درست نہیں اس کی باتوں کی جانب توجہ کرنا حماقت ہے اور اپنے قیمتی وقت کو ضائع کرنا ہے، بعد ازاں انہوں نے ان کی باتوں کا جواب یہ دیا کہ تم سب انتظار کرو شاید وہ اس راہ کو چھوڑ کر پہلی کیفیت پر واپس آجائے اور تمہارے دین کو قبول کر لے جبکہ ان کی یہ باتیں حقائق سے دور تھیں اس لیے کہ وہ در حقیقت نوح کی شخصیت کو عقل و فکر کے لحاظ سے فوقیت عطا کرتے تھے بالآخر انہوں نے تقلید پر قناعت کرتے ہوئے کہا کہ ہم تو اپنے آبائو اجداد کے مقلد ہیں ان سے ہم نے جو کچھ سنا ہے اس پر عمل پیرا ہیں ان کی مخالف جہت کی جانب ہم ہرگز قدم زن نہ ہوں گے لیکن ان کا یہ کہنا کہ نوح پیغمبر دیوانہ شخص ہے بالکل صریح جھوٹ ہے انہیں اچھی طرح علم تھا کہ نوح جواب خود کو پیغمبر کہتا ہے وہ نہایت سمجھ دار اور فطین شخص ہے اس کی رائے کے صحیح ہونے کے بارے میں انہیں انکار نہ تھا۔\nجب نوح علیہ السلام نے محسوس کیا کہ قوم تو گمراہی پر مصر ہے ان سے توقع نہیں ہے کہ وہ ایمان لائیں گے بلکہ اللہ پاک کی جانب سے بھی ان پر وحی نازل ہوئی کہ آپ کی قوم میں سے جو ایمان لا چکے ہیں ان کے سوا کوئی ایمان نہیں لائے گا تو پھر نوح علیہ السلام نے بارگاہ الٰہی میں دعا کی اے میرے پروردگار! میری مدد فرمائیں اور مجھ سے جو وعدہ کیا گیا ہے اس کو پورا کریں یعنی ان پر عذاب نازل فرمائیں، بلکہ سورۂ نوح میں صراحت ہے: ﴿رَّبِّ لَا تَذَرْ عَلَى الْاَرْضِ مِنَ الْكٰفِرِيْنَ دَيَّارًا۰۰۲۶﴾ (نوح: 26) ’’اے میرے پروردگار! روئے زمین پر کفار کا کوئی گھر باقی نہ رہنے پائے۔‘‘\nچنانچہ اللہ تعالیٰ نے ان کی دعا کو قبولیت عطا کرتے ہوئے حکم دیا آپ ہماری نگرانی اور ہماری تعلیم کی راہنمائی میں کشتی تیار کریں جب آپ کی قوم کے بارے میں ان کی تباہی کا فیصلہ عملی شکل میں ظہور پذیر ہوگا تو اس وقت زمین سے پانی باہر نکلنے لگے گا اس دوران آپ نے ہر قسم کے حیوان سے نر مادہ کے جوڑے کو کشتی پر سوار کرانا ہوگا، نیز اپنی اولاد اور ان کی بیویوں کو بھی کشتی میں سوار کرائیں البتہ جس شخص کے بارے میں ہمارا فیصلہ صادر ہو چکا ہے کہ وہ بھی تباہ و برباد ہونے والوں کے ساتھ ہلاک ہو جائے گا اس کو کشتی میں سوار نہیں کرانا ہے اس سے مقصود نوح علیہ السلام کا بیٹا کنعان تھا جو اس طوفان میں اپنے دیگر رفقاء کے ساتھ ڈوب کر مر گیا، شیخ سعدی رحمہ اللہ کا ایک شعر ملاحظہ فرمائیں :\nپسر نوح بابداں بنشست خاندان نبوتش گم شد\n’’نوح علیہ السلام کا بیٹا بد کردار لوگوں کی مجلس میں شریک ہونے کے باعث اس کا خاندان نبوت سے ہونے اس کو کچھ فائدہ نہ دیا۔‘‘\nمزید اللہ تعالیٰ نے حکم دیا ظالموں کے بارے میں مجھ سے مطالبہ نہ کرنا کہ میں انہیں ڈوبنے سے تحفظ عطا کروں اس لیے کہ اس کے سمیت سبھی پر میرا عذاب واقع ہوگا البتہ جب آپ اپنے رفقاء کے ساتھ کشتی میں سوار ہوں تو آپ کی زبان پر یہ جملہ ہو کہ ہر قسم کی حمدوثنا اس اللہ کے لیے لائق ہے جس نے ہمیں ان ظالم مشرک لوگوں سے نجات عطا کی اور کشتی سے باہر آتے وقت آپ کی زبان پر یہ کلمات ہوں اے میرے پروردگار! مجھے برکت والی زمین پر اتارنا اور تیری ذات اتارنے والوں سے بہتر اتارنے والی ہے اس میں کچھ شک نہیں کہ قوم نوح کی تباہی میں مشرکین قریش کے لیے عبرت کا سامان ہے شاید وہ کفر سے باز آجائیں سورۂ ہود میں تفصیل کے ساتھ یہ واقعہ بیان ہوا ہے۔\nثُمَّ اَنْشَاْنَا مِنْۢ بَعْدِهِمْ قَرْنًا اٰخَرِيْنَۚ۰۰۳۱ فَاَرْسَلْنَا فِيْهِمْ رَسُوْلًا مِّنْهُمْ اَنِ\nاعْبُدُوا اللّٰهَ مَا لَكُمْ مِّنْ اِلٰهٍ غَيْرُهٗ١ؕ اَفَلَا تَتَّقُوْنَؒ۰۰۳۲ وَ قَالَ الْمَلَاُ مِنْ قَوْمِهِ\nالَّذِيْنَ كَفَرُوْا وَ كَذَّبُوْا بِلِقَآءِ الْاٰخِرَةِ وَ اَتْرَفْنٰهُمْ فِي الْحَيٰوةِ الدُّنْيَا١ۙ مَا هٰذَاۤ اِلَّا\nبَشَرٌ مِّثْلُكُمْ١ۙ يَاْكُلُ مِمَّا تَاْكُلُوْنَ مِنْهُ وَ يَشْرَبُ مِمَّا تَشْرَبُوْنَ۪ۙ۰۰۳۳ وَ لَىِٕنْ اَطَعْتُمْ\nبَشَرًا مِّثْلَكُمْ اِنَّكُمْ اِذًا لَّخٰسِرُوْنَۙ۰۰۳۴ اَيَعِدُكُمْ اَنَّكُمْ اِذَا مِتُّمْ وَ كُنْتُمْ تُرَابًا\nوَّ عِظَامًا اَنَّكُمْ مُّخْرَجُوْنَ۪ۙ۰۰۳۵ هَيْهَاتَ هَيْهَاتَ لِمَا تُوْعَدُوْنَ۪ۙ۰۰۳۶ اِنْ هِيَ اِلَّا\nحَيَاتُنَا الدُّنْيَا نَمُوْتُ وَ نَحْيَا وَ مَا نَحْنُ بِمَبْعُوْثِيْنَ۪۠ۙ۰۰۳۷ اِنْ هُوَ اِلَّا رَجُلُ ا۟فْتَرٰى عَلَى\nاللّٰهِ كَذِبًا وَّ مَا نَحْنُ لَهٗ بِمُؤْمِنِيْنَ۰۰۳۸ قَالَ رَبِّ انْصُرْنِيْ بِمَا كَذَّبُوْنِ۰۰۳۹ قَالَ عَمَّا\nقَلِيْلٍ لَّيُصْبِحُنَّ نٰدِمِيْنَۚ۰۰۴۰ فَاَخَذَتْهُمُ الصَّيْحَةُ بِالْحَقِّ فَجَعَلْنٰهُمْ غُثَآءً١ۚ\nفَبُعْدًاا لِّلْقَوْمِ الظّٰلِمِيْنَ۰۰۴۱\nپھر ہم نے ان کے بعد ایک دوسری امت پیدا کی رضی اللہ عنہ چنانچہ ہم نے ان میں انھی میں سے ایک رسول بھیجا کہ تم اللہ کی عبادت کرو، اس کے سوا تمھارے لیے کوئی معبود نہیں، پھر کیا تم ڈرتے نہیں؟ رضی اللہ عنہم اور اس کی قوم کے سرداروں نے کہا، جنھوں نے کفر کیا اور (ہماری) آخرت کی ملاقات جھٹلائی، اور ہم نے انھیں دنیاوی زندگی میں خوشحالی دی تھی، کہ یہ تم جیسا ایک بشر ہی تو ہے، وہ اس میں سے کھاتا ہے جس میں سے تم کھاتے ہو، اور وہ اس میں سے پیتا ہے جو تم پیتے ہو علیہ السلام اور اگر تم نے اپنے ہی جیسے بشر کی اطاعت کی تو بلاشبہ تم اس وقت خسارہ پانے والے ہو گے علیہما السلام کیا وہ تمھیں وعدہ دیتا ہے کہ بے شک جب تم مر گئے اور مٹی اور ہڈیاں ہو گئے تو بلاشبہ تم (زندہ) نکالے جائو گے علیہم السلام دور ہے، دور ہے وہ جو تم وعدہ کیے جاتے ہو!p یہ ہماری دنیاوی زندگی ہی تو (سب کچھ) ہے (جس میں) ہم مرتے اور زندہ رہتے ہیں، اور ہم (دوبارہ) اٹھائے جانے والے نہیں[ وہ ایک شخص ہی تو ہے جس نے اللہ پر جھوٹ گھڑا ہے، اور ہم اس پر ایمان لانے والے نہیں] اس (رسول) نے کہا: اے میرے رب! تو میری مدد فرما اس لیے کہ انھوں نے میری تکذیب کی اللہ نے فرمایا: بلاشبہ تھوڑے دنوں میں وہ (اپنے کیے پر) ضرور نادم ہوں گے\nپھر انھیں واقعی چنگھاڑنے آ پکڑا، پھر ہم نے انھیں خس و خاشاک کر دیا، چنانچہ دوری ظالم لوگوں کے لیے ہے"],[4579,"§عاد یا ثمود کا قصہ\nاللہ تعالیٰ نے بیان فرمایا ہے کہ اس نے قوم نوح کے بعد ایک اور جماعت پیدا فرما دی۔ ایک قول کے مطابق اس جماعت سے مراد قوم عاد ہے کیونکہ قوم نوح کے بعد یہی لوگ تھے اور دوسرے قول کے مطابق اس سے مراد قوم ثمود ہے کیونکہ ان کے بارے میں ارشاد باری تعالیٰ ہے: ﴿فَاَخَذَتْہُمُ الصَّیْحَۃُ بِالْحَقِّ﴾ ’’پھر انہیں حق کے ساتھ چنگھاڑ نے آ پکڑا۔‘‘ اللہ تعالیٰ نے ان کی طرف انہی میں سے ایک رسول بھیجا جس نے انہیں اللہ وحدہ لا شریک کی عبادت کی دعوت دی مگر انہوں نے ان کی تکذیب و مخالفت کی اور ان کی اتباع سے انکار کر دیا اور کہا کہ ہم ان کی اتباع کیوں کریں، وہ تو ہمارے جیسے بشر ہیں اور اس طرح انہوں نے ایک بشری رسول کی اتباع سے انکار کر دیا، قیامت کے دن اللہ تعالیٰ کی ملاقات کا بھی انکار کر دیا، نیز انہوں نے جسموں کے دوبارہ اٹھائے جانے کا بھی انکار کر دیا، اور کہا: ﴿اَيَعِدُكُمْ اَنَّكُمْ اِذَا مِتُّمْ وَ كُنْتُمْ تُرَابًا وَّ عِظَامًا اَنَّكُمْ مُّخْرَجُوْنَ۪ۙ۰۰۳۵ هَيْهَاتَ هَيْهَاتَ لِمَا تُوْعَدُوْنَ۪ۙ۰۰۳۶﴾ ’’کیا وہ تمہیں وعدہ دیتا ہے کہ بے شک جب تم مر جائو گے اور مٹی اور ہڈیاں ہو جائو گے تو تم (زندہ) نکالے جائو گے، جس بات کا تم سے وعدہ کیا جاتا ہے (بہت) بعید، بہت بعید ہے۔‘‘ یعنی بہت زیادہ بعید ہے۔ ﴿اِنْ هُوَ اِلَّا رَجُلُ ا۟فْتَرٰى عَلَى اللّٰهِ كَذِبًا﴾ ’’وہ ایک ایسا آدمی ہے جس نے اللہ پر جھوٹ گھڑا ہے۔‘‘ یعنی یہ جو تمہارے پاس پیغام، ڈر اور آخرت کی خبریں لے کر آیا ہے تو ان سب باتوں میں یہ جھوٹا ہے۔ ﴿وَّ مَا نَحْنُ لَهٗ بِمُؤْمِنِيْنَ۰۰۳۸ قَالَ رَبِّ انْصُرْنِيْ بِمَا كَذَّبُوْنِ۰۰۳۹﴾ ’’اور ہم اس کو ماننے والے نہیں۔ اس (پیغمبر) نے کہا کہ اے میرے پروردگار! انہوں نے میری تکذیب کی، اس لیے تو میری مدد کر۔‘‘ یعنی رسول نے اپنی قوم کے خلاف اللہ تعالیٰ سے فتح و نصرت طلب کی تو اللہ تعالیٰ نے ان کی دعا کو قبول فرما لیا اور ﴿قَالَ عَمَّا قَلِيْلٍ لَّيُصْبِحُنَّ نٰدِمِيْنَۚ۰۰۴۰﴾ ’’فرمایا: بلاشبہ تھوڑے ہی عرصے میں وہ ضرور پشیمان ہو کر رہ جائیں گے۔‘‘ یعنی آپ کی مخالفت اور آپ جو دین لے کر آئے ہیں اس سے دشمنی کرنے کی وجہ سے عنقریب انہیں ندامت و پشیمانی حاصل ہو گی۔"],[4580,"§دوسرے کی آنکھ کا تنکا بھی نظر آ جاتا ہے اور اپنی آنکھ کا شہتیر نظر نہیں آتا\nحالانکہ وہ خود بھی ایک عام انسان ہی تھے اور عام لوگوں کی طرح کھاتے پیتے تھے۔ اس کے باوجود وہ عوام کے مطاع بنے ہوئے تھے اور چاہتے تھے کہ عوام ان کی اطاعت کریں۔ ان کا یہ پروپیگنڈا اس لیے نہ تھا کہ انسان مطاع نہیں بن سکتا۔ بلکہ صرف اس لیے تھا کہ کہیں لوگ نبی کی دعوت قبول کرکے ہماری اطاعت کو ترک کرکے اس کی اطاعت نہ کرنے لگ جائیں۔ گویا اصل خطرہ انہیں اپنی سرداریوں کا تھا اور ان کے لیے تو یہ واقعی خسارہ کی بات تھی۔ لیکن لوگوں کو یہ باور کرانا چاہتے تھے کہ نبی کی اطاعت کرکے تم خسارہ میں رہو گے۔ گویا بشر ہونے کے باوجود ان کی اپنی اطاعت میں خسارے کی بات ان کے نزدیک خارج از بحث تھی۔"],[4581,"§آخرت کا انکار جہالت اور ہٹ دھرمی پر مبنی ہے\nآخرت سے انکار کرنے والوں کے پاس سب سے بڑی دلیل یہ ہوتی ہے کہ چونکہ کوئی بھی مرا ہوا انسان آج تک دوبارہ زندہ ہو کر واپس نہیں آیا۔ لہٰذا ہم کیسے مان لیں کہ مرنے اور مر کر مٹی میں مل جانے کے بعد دوبارہ اٹھائے جائیں گے؟ گویا ان کے انکار کی اصل بنیاد ان کا اپنا تجربہ مشاہدہ ہوتا ہے۔ قوم عام مشرکین مکہ کی طرح اللہ کی ہستی کے قائل تھے حالانکہ اللہ کی ہستی بھی کسی تجربہ اور مشاہدہ میں نہیں آتی اور اللہ کی ہستی کے قائل ہونے کی وجہ بھی یہ نہیں ہوتی کہ وہ کسی پیغمبر کی تعلیم سے متاثر ہو کر اللہ پر ایمان بالغیب لاتے ہیں۔ بلکہ اس لیے فلاسفروں اور حکماء نے اللہ کی ہستی کو علت العلل (First Cause) کے طور پر تسلیم کیا ہے یعنی جس طرح ہم یہ تسلیم کرتے ہیں کہ ہر چیز کے لیے صانع یا اس کے بنانے والے کا ہونا ضروری ہے اسی طرح اس کارخانہ کائنات کا بنانے والا ہونا بھی ضروری ہے۔ بالفاظ دیگر اللہ کی ہستی کو عقلی دلیل کی بنا پر تسلیم کیا جاتا ہے۔ جس سے معلوم ہوا کہ عقلی دلیل کی بنا پر بھی ایسی اشیاء کو تسلیم کرنا ضروری ہے جو مشاہدہ اور تجربہ میں نہ آئی ہوں یا نہ آ سکتی ہوں اور دوبارہ زندگی کے قیام پر چونکہ بہت سے عقلی دلائل موجود ہیں جن کا ذکر قرآن کریم میں بے شمار مقامات پر ہوا ہے۔ لہٰذا جو لوگ آخرت اور دوبارہ زندگی کا انکار محض اس بنا پر کرتے ہیں کہ کوئی آدمی مرکر واپس نہیں آیا یا انسان کا جسم مٹی میں مل کر مٹی ہو جاتا ہے تو پھر کیسے زندہ ہو سکتا ہے، تو یہ عقلی دلائل کا انکار اور محض جہالت ہے۔\nاکثر مفسرین کے نزدیک قوم نوح کے بعد، جس قوم کو اللہ نے پیدا فرمایا اور ان میں رسول بھیجا، وہ قوم عاد ہے کیونکہ اکثر مقامات پر قوم نوح کے جانشین کے طور پر عاد ہی کا ذکر کیا گیا ہے۔ بعض کے نزدیک یہ قوم ثمود ہے کیونکہ آگے چل کر ان کی ہلاکت کے ذکر میں کہا گیا ہے کہ صَیْحَۃ (زبردست چیخ) نے ان کو پکڑ لیا، اور یہ عذاب قوم ثمود پر آیا تھا۔ بعض کے نزدیک یہ سیّدنا شعیب علیہ السلام کی قوم اہل مدین ہیں کہ ان کی ہلاکت بھی چیخ کے ذریعے سے ہوئی تھی۔\nوہ خسارہ یہی ہے کہ اپنے ہی جیسے انسان کو رسول مان کر تم اس کی فضیلت و برتری کو تسلیم کر لو گے، جبکہ ایک بشر، دوسرے بشر سے افضل کیوں کر ہو سکتا ہے؟ یہی وہ مغالطہ ہے جو منکرین بشریت رسول کے دماغوں میں رہا ہے۔ حالانکہ اللہ تعالیٰ جس بشر کو رسالت کے لیے چن لیتا ہے، تو وہ اس وحی رسالت کی وجہ سے دوسرے تمام غیر نبی انسانوں سے شرف و فضل میں بہت بالا اور نہایت ارفع ہو جاتا ہے۔\n﴿عَمَّا﴾ میں ما زائد ہے جو جار مجرود کے درمیان، قلت زمان کی تاکید کے لیے آیا ہے۔ جیسے ﴿فَبِمَا رَحْمَةٍ مِّنَ اللّٰهِ﴾ (آل عمران: 159) ’’میں ما زائد ہے۔ یعنی بہت جلد عذاب آنے والا ہے، جس پر یہ پچھتائیں گے۔ لیکن اس وقت یہ پچھتانا ان کے کچھ کام نہ آئے گا۔\nقوم نوح کی تباہی و بربادی کے بعد ہم نے قوم عاد کو پیدا فرمایا ان میں سے ہی ہود علیہ السلام کو مبعوث کیا انہوں نے انہیں اللہ کی توحید کی جانب دعوت دی اور واضح کیا کہ تم صرف ایک اللہ کی عبادت اور اسی کی اطاعت کرو بت پرستی کے گڑھے سے خود کو نکال کر توحید کے جادۂ مستقیم پر رواں دواں ہو جائو اگر تم اللہ کی عبادت سے روگردانی کرتے ہوئے بت پرستی کرتے رہو گے تو اللہ کے عذاب سے تحفظ حاصل نہ کر سکو گے، لیکن قوم عاد کے بدمست اور متکبر قسم کے لوگوں نے ان کی دعوت کا انکار اور آخرت کی تکذیب کرتے ہوئے رفاہیت اور کبر و نخوت کے عالم میں کہا کہ یہ شخص جو ہمیں ایک اللہ کی عبادت کی جانب دعوت دے رہا ہے اس کو تم پر ہرگز برتری حاصل نہیں ہے یہ تو بس تمہارے جیسا انسان ہے اس میں کوئی امتیازی وصف نہیں ہے تمہاری طرح اس کا رہن سہن اس کا کھانا پینا ہے اس لیے ہم اس کی اطاعت نہیں کر سکتے اور نہ آخرت کے دن کو تسلیم کرتے ہیں موت کے بعد ہمیں ہرگز اٹھایا نہیں جائے گا اگر تم اس کی اطاعت کرو گے جبکہ یہ تمہارے جیسا انسان ہے اس میں کچھ برتری اور تفوق کی کوئی بات نظر نہیں آتی ہے تو تمہیں جو مقام حاصل ہے تم اس سے محروم ہو جائو گے اور دنیوی جاہ و جلال اور شرف تم سے چھن جائے گا۔ مزید تعجب خیز اس کا یہ کہنا ہے کہ تم فوت ہونے کے بعد جب مٹی ہو جائو گے صرف ہڈیوں کا ڈھانچہ باقی رہ جائے گا تو تمہیں دوبارہ زندگی عطا ہو گی اور ثواب و عقاب کے مراحل سے گزرنا ہوگا اس کی یہ باتیں عقل و فراست سے دور ہیں ہمیں ہرگز نہیں اٹھایا جائے گا او رنہ ہی محاسبہ اور جزا و سزا کا عمل ظہور پذیر ہوگا یہ تو افسانوی باتیں ہیں ہم تو یہ سمجھتے ہیں کہ صرف دنیوی زندگی ہے جب ہم موت سے ہم کنار ہوں گے تو پھر ہمیں زندگی نہیں ملے گی ہماری مثال تو اس سبزے کی مانند ہے جو زمین پر اگتا ہے پھر خشک ہو جاتا ہے اور ختم ہو جاتا ہے دوبارہ اس کا زندگی میں نہیں آنا ہوتا ہے۔\nاس استحالہ کے بعد انہوں نے کھلے انداز میں ہود علیہ السلام کے بارے میں اس حقیقت کا اظہار کیا کہ یہ شخص تو ایک انسان ہے یہ اللہ کی جانب جھوٹی باتیں منسوب کر رہا ہے اس کا یہ کہنا کہ اللہ کے سوا تمہارا کوئی معبود نہیں وہی آسمان و زمین کا خالق ہے بالکل جھوٹ ہے اسی طرح اس کا یہ کہنا کہ تم موت سے ہم کنار ہونے کےبعد جب تمہارا جسم مٹی ہو جائے گا اور ہڈیوں کا ڈھانچہ باقی رہ جائے گا تو تمہیں اخروی زندگی میں اٹھایا جائے گا ہم ہرگز اس کی اس بات کو تسلیم نہیں کریں گے ان کے اس احمقانہ جواب کے بعد ہود علیہ السلام ان کے ایمان لانے سے نا امید ہو گئے تو انہوں نے بارگاہ رب العزت میں دعا کی کہ اے میرے پروردگار! مجھے ان پر غلبہ عطا فرما اور ان کی نا فرمانی کے باعث ان سے انتقام لیا جائے تو اللہ تعالیٰ نے واضح کیا کہ تجھے جھٹلانے والے کچھ عرصہ کے بعد عذاب میں گرفتار ہوں گے اپنے انکار پر ندامت محسوس کریں گے لیکن ندامت سے انہیں کچھ فائدہ حاصل نہ ہوگا چنانچہ ان کے کفر کے باعث ان کو خوف ناک آواز نے تباہ و برباد کر دیا ان کی کیفیت خس و خشاک جیسی ہو گئی اس طرح قوم عاد اپنے ظلم کے باعث تباہی سے ہمکنار ہوئی۔\nثُمَّ اَنْشَاْنَا مِنْۢ بَعْدِهِمْ قُرُوْنًا اٰخَرِيْنَؕ۰۰۴۲ مَا تَسْبِقُ مِنْ اُمَّةٍ اَجَلَهَا وَ مَا\nيَسْتَاْخِرُوْنَ۠ؕ۰۰۴۳ ثُمَّ اَرْسَلْنَا رُسُلَنَا تَتْرَا١ؕ كُلَّمَا جَآءَ اُمَّةً رَّسُوْلُهَا كَذَّبُوْهُ فَاَتْبَعْنَا\nبَعْضَهُمْ بَعْضًا وَّ جَعَلْنٰهُمْ اَحَادِيْثَ١ۚ فَبُعْدًاا لِّقَوْمٍ لَّا يُؤْمِنُوْنَ۰۰۴۴\nپھر ہم نے ان کے بعد دوسری امتیں پیدا کیں کوئی بھی امت اپنے مقرر وقت سے آگے نہیں نکل سکتی اور نہ وہ پیچھے رہ سکتی ہے پھر ہم لگاتار اپنے رسول بھیجتے رہے، جب بھی کسی امت کے پاس ان کا رسول آیا تو انھوں نے اس کی تکذیب کی، پھر ہم ایک کے پیچھے دوسری قوم کو (ہلاک) کرتے رہے، اور ہم نے انھیں افسانے بنا دیا، چنانچہ ان لوگوں کے لیے دوری ہے جو ایمان\nنہیں لاتے"],[4582,"§کچھ امتوں کا ذکر\nارشاد باری تعالیٰ ہے: ﴿ثُمَّ اَنْشَاْنَا مِنْۢ بَعْدِهِمْ قُرُوْنًا اٰخَرِيْنَؕ۰۰۴۲﴾ یعنی پھر ہم نے ان کے بعد دوسری امتیں اور دوسرے لوگ پیدا کر دیے۔ ﴿مَا تَسْبِقُ مِنْ اُمَّةٍ اَجَلَهَا وَ مَا يَسْتَاْخِرُوْنَ۠ؕ۰۰۴۳﴾ ’’کوئی بھی امت اپنے مقررہ وقت سے نہ آگے جا سکتی ہے نہ پیچھے رہ سکتی ہے۔‘‘ بلکہ ان کا مؤاخذہ اسی وقت کے حساب سے ہوگا جو اللہ تعالیٰ نے ان کے لیے اپنی کتاب محفوظ میں مقدر فرما دیا ہے اور جسے وہ ان کے امت کے بعد امت، قرن کے بعد قرن، نسل کے بعد نسل اور سلف کے بعد خلف ہونے سے قبل ہی جانتا ہے۔ ﴿ثُمَّ اَرْسَلْنَا رُسُلَنَا تَتْرَا١ؕ﴾ ’’پھر ہم پے در پے اپنے پیغمبر بھیجتے رہے۔‘‘ ابن عباس رضی اللہ عنہما فرماتے ہیں کہ وہ ایک دوسرے کے بعد آتے رہے۔ جیسا کہ فرمایا: ﴿وَ لَقَدْ بَعَثْنَا فِيْ كُلِّ اُمَّةٍ رَّسُوْلًا اَنِ اعْبُدُوا اللّٰهَ وَ اجْتَنِبُوا الطَّاغُوْتَ١ۚ فَمِنْهُمْ مَّنْ هَدَى اللّٰهُ وَ مِنْهُمْ مَّنْ حَقَّتْ عَلَيْهِ الضَّلٰلَةُ١ؕ﴾ (النحل : 36) ’’اور البتہ تحقیق ہم نے ہر جماعت میں ایک پیغمبر بھیجا کہ اللہ ہی کی عبادت کرو اور طاغوت سے بچو، پھر ان میں بعض ایسے ہیں جنہیں اللہ نے ہدایت دی اور بعض ایسے ہیں جن پر گمراہی ثابت ہوئی۔‘‘\nبہت عرصے کی بات ہے، کسی اہل علم کا قول میری نظر سے گزرا ہے، جن کا نام اس وقت مجھے یاد نہیں… کہ موسیٰ علیہ السلام کی بعثت اور تورات کے نزول کے بعد اللہ تعالیٰ نے قوموں پر سے عذاب کو اٹھا لیا، یعنی وہ عذاب جو ان کا جڑ سے خاتمہ کر دیتا تھا اور اس کی جگہ اللہ تعالیٰ نے مکذبین و معاندین حق کے خلاف جہاد مشروع کیا۔ معلوم نہیں انہوں نے یہ رائے کہاں سے اخذ کی ہے لیکن جب میں نے ان آیات کو سورۃ القصص کی آیات کے ساتھ ملا کر غور کیا تو میرے سامنے اس کا سبب واضح ہو گیا کہ ان آیات کریمہ میں اللہ تعالیٰ نے پے در پے ہلاک ہونے والی قوموں کا ذکر فرمایا پھر آگاہ فرمایا کہا اس نے ان قوموں کے بعد سیّدنا موسیٰ علیہ السلام کو رسول بنا کر بھیجا ان پر تورات نازل فرمائی جس میں لوگوں کے لیے راہنمائی تھی اور فرعون کی ہلاکت سے اس نقطہ نظر کی تردید نہیں ہوتی کیونکہ فرعون نزول تورات سے پہلے ہلاک ہو گیا تھا۔ رہی سورۃ القصص کی آیات، تو وہ نہایت واضح ہیں کیونکہ ان آیات میں اللہ تعالیٰ نے فرعون کی ہلاکت کا ذکر کرنے کے بعد فرمایا: ﴿وَ لَقَدْ اٰتَيْنَا مُوْسَى الْكِتٰبَ مِنْۢ بَعْدِ مَاۤ اَهْلَكْنَا الْقُرُوْنَ الْاُوْلٰى بَصَآىِٕرَ لِلنَّاسِ وَ هُدًى وَّ رَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُوْنَ۰۰۴۳﴾ (القصص : 43) ’’پچھلی قوموں کو ہلاک کر دینے کے بعد ہم نے موسیٰ کو کتاب سے نوازا، لوگوں کے لیے بصیرت، ہدایت اور رحمت بنا کر تاکہ شاید وہ نصیحت پکڑیں۔‘‘ اس آیت کریمہ میں صراحت ہے کہ اللہ تعالیٰ نے ان باغی اور سرکش قوموں کی ہلاکت کے بعد موسیٰ علیہ السلام کو تورات عطا فرمائی اور آگاہ فرمایا کہ یہ کتاب لوگوں کے لیے بصیرت، ہدایت اور رحمت کے طور پر نازل کی گئی ہے۔ شاید وہ آیات بھی اسی پر دلالت کرتی ہیں جنہیں اللہ تعالیٰ نے سورۂ یونس میں ذکر فرمایا ہے: ﴿ثُمَّ بَعَثْنَا مِنْۢ بَعْدِهٖ رُسُلًا اِلٰى قَوْمِهِمْ فَجَآءُوْهُمْ بِالْبَيِّنٰتِ فَمَا كَانُوْا لِيُؤْمِنُوْا بِمَا كَذَّبُوْا بِهٖ مِنْ قَبْلُ١ؕ كَذٰلِكَ نَطْبَعُ عَلٰى قُلُوْبِ الْمُعْتَدِيْنَ۰۰۷۴ ثُمَّ بَعَثْنَا مِنْۢ بَعْدِهِمْ مُّوْسٰى وَ هٰرُوْنَ﴾ (یونس : 75,74) ’’پھر نوح کے بعد ہم نے دیگر رسولوں کو ان کی قوموں کی طرف بھیجا وہ ان کے پاس واضح نشانیاں لے کر آئے مگر جس کو انہوں نے پہلے جھٹلا دیا تھا وہ اب بھی اس پر ایمان نہ لائے ہم اسی طرح حد سے گزر جانے والوں کے دلوں پر مہر لگا دیتے ہیں، پھر ان کے بعد ہم نے موسیٰ اور ہارون کو مبعوث کیا…۔‘‘ واللہ اعلم!"],[4583,"§قوم عاد کے بعد کے انبیاء\nاب اگر تاریخی لحاظ سے دیکھا جائے تو جہاں تک انسانی علم کی رسائی ہو سکی ہے اس کے مطابق عاد اولیٰ اور موسیٰ علیہ السلام کی درمیانی مدت تقریباً چار ہزار سال پر محیط ہے۔ اس طویل عرصہ میں لا تعداد انبیاء و رسل مبعوث ہوتے رہے۔ حتیٰ کہ ان انبیا۴ کا ایسا تانتا بندھا ہوا تھا کہ کوئی وقت ایسا نہ تھا جب روئے زمین پر کوئی نبی موجود نہ ہو۔ بلکہ بیک وقت ایک ہی زمانے میں کئی کئی انبیاء مبعوث ہوتے رہے۔ ان سب سے یہی سلوک ہوتا رہا کہ انہیں جھٹلایا گیا۔ کیونکہ چودھری قسم کے لوگ قطعاً اس بات پر آمادہ نہیں ہوتے کہ وہ اپنی سرداریوں سے دستبردار ہو کر نبیوں کے مطیع فرمان بن جائیں۔ وہ دوسرے لوگوں کو بھی انبیاء کے خلاف بھڑکاتے رہے۔ ان کے اس جرم کی پاداش میں ان پر عذاب آتے رہے۔ ایک قوم مٹتی تو دوسری اس کی جگہ لیتی رہی۔ پھر اس کے مقررہ وقت کے مطابق اسے بھی صفحہ ہستی سے نیست و نابود کیا جاتا رہا۔ حتیٰ کہ ان کے آثار بھی باقی نہ رہے، ماسوائے ان داستانوں اور افسانوں کے جو بعد کے آنے والے لوگوں میں سینہ بہ سینہ منتقل ہوتے رہے۔\nاس سے مراد سیّدنا صالح، سیّدنا لوط اور سیّدنا شعیب علیہم السلام کی قومیں ہیں۔ کیونکہ سورۂ اعراف اور سورۂ ہود میں اسی ترتیب سے ان کے واقعات بیان کیے گئے ہیں۔ بعض کے نزدیک بنو اسرائیل مراد ہیں۔ ﴿قُرُوْن﴾ قرن کی جمع ہے اور یہاں بمعنی امت استعمال ہوا ہے۔ یعنی یہ سب امتیں بھی قوم نوح اور عاد کی طرح، جب ان کی ہلاکت کا وقت موعود آ گیا، تو تباہ و برباد ہو گئیں۔ ایک لمحہ آگے، پیچھے نہ ہوئیں۔\nقوم عاد کی ہلاکت کے بعد دیگر قوموں کو ہم نے پیدا کیا جیسے صالح، لوط، شعیب، اور دیگر پیغمبروں کی اقوام ہیں ان میں سے ہر امت کو تباہی و بربادی کے عین وقت پر صفحہ ہستی سے حرف غلط کی طرح مٹا دیا گیا بعد ازاں ہم نے مسلسل پیغمبروں کو مبعوث فرمایا ہر قوم کی جانب پیغمبر آئے لیکن جب بھی کسی پیغمبر نے اپنے پروردگار کی جانب سے شریعت کے احکام کو پیش کیا تو انہوں نے پیغمبر کو جھوٹا قرار دیا جیسا کہ آپ کی قوم نے بھی آپ کی نبوت کو تسلیم نہ کیا اور مخالفت پر اتر آئے لیکن جب انہوں نے اپنے پیغمبروں کی اطاعت نہ کی بلکہ ان کی نبوت کا انکار کیا تو ہم نے انہیں یکے بعد دیگرے تباہ و برباد کیا اور ہم نے ان کی تباہی کے واقعات کو نشان عبرت بنایا عوام و خواص ان کی تباہی وبربادی کا اپنی محفلوں میں تذکرہ کرتے رہتے ہیں حقیقت یہ ہے کہ جو لوگ پیغمبروں کی اطاعت نہیں کرتے ہیں انہیں صفحہ ہستی سے مٹا دیا جاتا ہے۔\nثُمَّ اَرْسَلْنَا مُوْسٰى وَ اَخَاهُ هٰرُوْنَ١ۙ۬ بِاٰيٰتِنَا وَ سُلْطٰنٍ مُّبِيْنٍۙ۰۰۴۵ اِلٰى فِرْعَوْنَ\nوَمَلَاۡىِٕهٖ فَاسْتَكْبَرُوْا۠ وَ كَانُوْا قَوْمًا عَالِيْنَۚ۰۰۴۶ فَقَالُوْۤا اَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا\nوَقَوْمُهُمَا لَنَا عٰبِدُوْنَۚ۰۰۴۷ فَكَذَّبُوْهُمَا۠ فَكَانُوْا مِنَ الْمُهْلَكِيْنَ۰۰۴۸ وَ لَقَدْ اٰتَيْنَا\nمُوْسَى الْكِتٰبَ لَعَلَّهُمْ يَهْتَدُوْنَ۰۰۴۹ وَ جَعَلْنَا ابْنَ مَرْيَمَ وَ اُمَّهٗۤ اٰيَةً وَّ اٰوَيْنٰهُمَاۤ\nاِلٰى رَبْوَةٍ ذَاتِ قَرَارٍ وَّ مَعِيْنٍؒ۰۰۵۰\nپھر ہم نے موسیٰ اور اس کے بھائی ہارون کو اپنی نشانیوں اورکھلی دلیل کے ساتھ بھیجا فرعون اور اس کے درباریوں کی طرف، پھر انھوں نے تکبر کیا اور وہ سر کش لوگ تھے چنانچہ وہ کہنے لگے: کیا ہم اپنی ہی طرح کے دو انسانوں پر ایمان لائیں، جبکہ ان دونوں کی قوم ہماری غلام (ماتحت) ہے پھر انھوں نے ان دونوں کو جھٹلایا، تو وہ ہلاک شد گان میں سے ہو گئے اور بلاشبہ ہم نے موسیٰ کو کتاب دی، تاکہ وہ (لوگ) ہدایت پائیں{ اور ہم نے (عیسیٰ) ابن مریم اور اس کی ماں کو عظیم نشانی بنایا اور\nایک سکون اور جاری چشمے والی بلند جگہ پر ان دونوں کو ٹھکانا دیا}"],[4584,"§سیدنا موسیٰ علیہ السلام اور فرعون کا قصہ\nعالیٰ نے بیان فرمایا ہے کہ اس نے موسیٰ علیہ السلام اور ان کے بھائی ہارون کو معجزات، دلائل ساطعہ اور براہین قاطعہ کے ساتھ فرعون اور اس کے سرداروں کی طرف بھیجا مگر فرعون اور اس کی قوم نے موسیٰ اور ہارون علیہما السلام کی اطاعت و اتباع سے انکار کر دیا اور تکبر کا اظہار کرتے ہوئے کہا کہ ہم اپنے جیسے انسانوں کی بات کو کیسے تسلیم کر لیں جیسا کہ سابقہ قوموں نے بھی حضرات انبیائے کرام علیہم السلام کے بشر ہونے کا انکار کیا تھا، ان تمام کافر قوموں کے اور انبیاء کے بشر ہونے کی وجہ سے ان کا انکار کرنے والے لوگوں کے دل ایک جیسے تھے۔ اللہ تعالیٰ نے فرعون، اس کے سرداروں اور اس کی ساری قوم کو ایک ہی دن ہلاک کر دیا تھا۔ اور پھر اللہ تعالیٰ نے موسیٰ علیہ السلام پر اپنی کتاب تورات کو نازل فرمایا جس میں اللہ تعالیٰ کے احکام اور او امر و نواہی تھے۔ یاد رہے کہ اللہ تعالیٰ نے موسیٰ علیہ السلام پر تورات فرعون اور قبطیوں کو اپنی سخت گرفت میں لے کر ہلاک کرنے کے بعد نازل فرمائی تھی اور نزول تورات کے بعد اللہ تعالیٰ نے پھر اس طرح کسی امت کو ہلاک نہیں کیا بلکہ مومنوں کو حکم دیا کہ وہ کافروں سے جہاد کریں۔ تورات کے نزول کے بارے میں ارشاد باری تعالیٰ ہے: ﴿وَ لَقَدْ اٰتَيْنَا مُوْسَى الْكِتٰبَ مِنْۢ بَعْدِ مَاۤ اَهْلَكْنَا الْقُرُوْنَ الْاُوْلٰى بَصَآىِٕرَ لِلنَّاسِ وَ هُدًى وَّ رَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُوْنَ۰۰۴۳﴾ (القصص: 43) ’’اور بے شک ہم نے پہلی امتوں کو ہلاک کرنے کے بعد موسیٰ کو کتاب دی جو لوگوں کے لیے بصیرت اور ہدایت اور رحمت ہے تاکہ وہ نصیحت پکڑیں۔‘‘"],[4585,"§سیدنا عیسیٰ و مریم علیہما السلام کا ذکر\nاللہ تعالیٰ نے بیان فرمایا ہے کہ اس نے اپنے عبد و رسول عیسیٰ ابن مریم علیہما السلام کو لوگوں کے لیے نشانی اور اس بات کی ایک مضبوط دلیل بنا دیا کہ اللہ تعالیٰ ہر چیز پر ویسے ہی قادر ہے جیسے وہ چاہے۔ اپنی مشیت کے مطابق اس نے آدم علیہ السلام کو باپ اور ماں کے بغیر پیدا فرمایا، حواء کو اس نے نر سے مادہ کے بغیر پیدا فرمایا اور عیسیٰ کو مادہ سے نر کے بغیر پیدا فرمایا اور باقی لوگوں کو نر اور مادہ سے پیدا فرمایا ہے۔ اور فرمایا: ﴿وَّ اٰوَيْنٰهُمَاۤ اِلٰى رَبْوَةٍ ذَاتِ قَرَارٍ وَّ مَعِيْنٍؒ۰۰۵۰﴾ ’’اور ایک پر سکون اور جاری چشمے والے ٹیلے پر ان دونوں کو ٹھکانا دیا۔‘‘ ضحاک رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ﴿رَبْوَۃٍ﴾ زمین سے مرتفع اور اونچی جگہ کو کہتے ہیں، کاشت کاری کے لیے ایسی جگہ بہت بہتر ہوتی ہے۔ (تفسیر القرطبی: 316,315/3 و احکام القرآن لابن العربی : 241/3 والدر المنثور : 17/5 و تفسیر البغوی : 367/3) مجاہد، عکرمہ، سعید بن جبیر اور قتادہ رحمہ اللہ کا بھی یہی قول ہے۔\nابن ابو حاتم رحمہ اللہ نے سعید بن مسیّب رحمہ اللہ سے اس آیت کے بارے میں روایت کیا ہے کہ اس زمین سے مراد دمشق ہے۔ (تفسیر الطبری : 35/18) اور انہوں نے کہا ہے کہ عبداللہ بن سلام، حسن، زید بن اسلم اور خالد بن معدان اور اہل علم رحمہ اللہ سے بھی اسی طرح مروی ہے۔ (تفسیر القرطبی : 126/12 و تفسیر البغوی : 367/3) ابن ابو حاتم رحمہ اللہ نے عکرمہ رحمہ اللہ کے حوالے سے ابن عباس رضی اللہ عنہما سے اس آیت کے بارے میں روایت کیا ہے کہ اس زمین سے مراد دمشق ہے۔ لیث بن ابو سلیم رحمہ اللہ نے اس آیت کے بارے میں مجاہد رحمہ اللہ سے روایت کیا ہے کہ عیسیٰ ابن مریم اور ان کی والدہ نے دمشق اور اس کے گرد و نواح کے علاقے میں پناہ لی تھی۔ جبکہ عبدالرزاق رحمہ اللہ نے سیّدنا ابوہریرہ رضی اللہ عنہ سے روایت کیا ہے کہ اس سے فلسطین کا شہر رملہ مراد ہے۔ اس سلسلے میں سب سے بہتر قول وہ معلوم ہوتا ہے جسے عوفی رحمہ اللہ نے سیّدنا ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ﴿مَعِیْنٍ﴾ کے معنی جاری پانی ہیں اور اسی سے مراد وہی چشمہ ہے جس کے بارے میں اللہ تعالیٰ نے فرمایا ہے: ﴿قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا۰۰۲۴﴾ (مریم : 24) ’’تحقیق تیرے پروردگار نے تیرے نیچے ایک چشمہ جاری کر دیا ہے۔‘‘\nضحاک رحمہ اللہ اور قتادہ رحمہ اللہ کا قول بھی یہی ہے کہ اس آیت میں مذکور سر زمین سے مراد بیت المقدس ہے۔ (تفسیر الطبری : 37/18) اور یہ بات زیادہ صحیح معلوم ہوتی ہے کیونکہ آیت کریمہ: ﴿ذَاتِ قَرَارٍ وَّ مَعِيْنٍؒ۰۰۵۰﴾ میں بیت المقدس ہی مراد لیا گیا ہے اور اصول تفسیر یہ ہے کہ قرآن کا ایک مقام دوسرے مقام کی تفسیر بیان کرتا ہے اور تفسیر کا سب سے بہترین اسلوب و انداز بھی یہی ہے، پھر اس کے بعد تفسیر سے احادیث صحیحہ کی طرف رجوع کیا جاتا ہے اور اس کے بعد آثار صحابۂ کرام رضی اللہ عنہم کو دیکھا جاتا ہے۔\n﴿ثُمَّ اَرْسَلْنَا مُوْسٰی﴾ ’’پھر ہم نے موسیٰ (بن عمران، کلیم اللہ) کو بھیجا۔‘‘ ﴿وَاَخَاہُ ہٰرُوْنَ﴾ ’’اور (ان کے ساتھ) ان کے بھائی ہارون کو۔‘‘ جب سیّدنا موسیٰ علیہ السلام نے دعا کی کہ سیّدنا ہارون علیہ السلام کو نبوت کے معاملے میں ان کے ساتھ شریک کیا جائے تو اللہ تعالیٰ نے آپ کی دعا قبول فرما لی۔ ﴿بِاٰیٰتِنَا﴾ ’’اپنی نشانیوں کے ساتھ۔‘‘ جو ان کی صداقت اور ان کی دعوت کی صحت پر دلالت کرتی تھیں۔ ﴿وَسُلْطٰنٍ مُّبِیْنٍ﴾ ’’اور واضح برہان کے ساتھ۔‘‘ ان دلائل میں ایسی قوت تھی کہ وہ دلوں پر غالب آ جاتے اور اپنی قوت کی بنا پر دلوں میں گھر کر لیتے اور اہل ایمان کے دل ان کو مان لیتے اور معاندین حق کے خلاف حجت قائم ہو جاتی۔\nاور یہ آیت کریمہ اللہ تعالیٰ کے اس ارشاد کے مانند ہے۔ ﴿وَ لَقَدْ اٰتَيْنَا مُوْسٰى تِسْعَ اٰيٰتٍۭ بَيِّنٰتٍ﴾ (بنی اسرائیل : 101) ’’اور بلاشبہ ہم نے موسیٰ کو نو کھلی کھلی نشانیاں عطا کیں۔‘‘ اس لیے معاندین حق کے سردار فرعون نے ان کو پہچان لیا لیکن عناد کا راستہ اختیار کیا۔ ﴿فَسْـَٔلْ بَنِيْۤ اِسْرَآءِيْلَ اِذْ جَآءَهُمْ﴾ ’’آپ بنی اسرائیل سے پوچھ لیجئے! جب موسیٰ یہ نشانیاں لے کر ان کے پاس آئے۔‘‘ ﴿فَقَالَ﴾ تو فرعون نے سیّدنا موسیٰ علیہ السلام سے کہا ﴿اِنِّيْ لَاَظُنُّكَ يٰمُوْسٰى مَسْحُوْرًا۰۰۱۰۱﴾ (بنی اسرائیل : 101) ’’اے موسیٰ! میں تو تجھے سحر زدہ خیال کرتا ہوں۔‘‘ ﴿قَالَ لَقَدْ عَلِمْتَ مَاۤ اَنْزَلَ هٰۤؤُلَآءِ اِلَّا رَبُّ السَّمٰوٰتِ وَ الْاَرْضِ بَصَآىِٕرَ١ۚ وَ اِنِّيْ لَاَظُنُّكَ يٰفِرْعَوْنُ مَثْبُوْرًا۰۰۱۰۲﴾ (بنی اسرائیل : 102) ’’موسیٰ نے کہا: تو جانتا ہے کہ یہ بصیرت افروز نشانیاں اللہ کے سوا کسی نے نازل نہیں کیں۔ اے فرعون! میں سمجھتا ہوں کہ تو ضرور ہلاک ہونے والا ہے۔‘‘ اللہ تعالیٰ نے فرمایا: ﴿وَ جَحَدُوْا بِهَا وَ اسْتَيْقَنَتْهَاۤ اَنْفُسُهُمْ ظُلْمًا وَّ عُلُوًّا١ؕ﴾ (النمل : 14) ’’انہوں نے محض ظلم اور تکبر کی بنا پر ان نشانیوں کو جھٹلایا حالانکہ ان کے دلوں نے ان کو مان لیا تھا۔‘‘\nیہاں اللہ تعالیٰ نے فرمایا: ﴿ثُمَّ اَرْسَلْنَا مُوْسٰى وَ اَخَاهُ هٰرُوْنَ١ۙ۬ بِاٰيٰتِنَا وَ سُلْطٰنٍ مُّبِيْنٍۙ۰۰۴۵ اِلٰى فِرْعَوْنَ وَ مَلَاۡىِٕهٖ﴾ ’’پھر ہم نے بھیجا موسیٰ اور ان کے بھائی ہارون کو اپنی نشانیوں اور واضح برہان کے ساتھ، فرعون اور اس کے سرداروں کی طرف۔‘‘ مثلاً ہامان اور دیگر سرداران قوم۔ ﴿فَاسْتَکْبَرُوْا﴾ پس تکبر کی بنا پر وہ اللہ تعالیٰ پر ایمان نہ لائے اور اس کے انبیاء کے ساتھ تکبر سے پیش آئے۔ ﴿وَ كَانُوْا قَوْمًا عَالِيْنَۚ۰۰۴۶﴾ ’’اور تھے وہ سرکش لوگ۔‘‘ یعنی ان کا وصف غلبہ، قہر اور فساد فی الارض تھا اس لیے ان سے تکبر صادر ہوا اور اسے وہ کوئی بری بات نہیں سمجھتے تھے۔\n﴿فَقَالُوْۤا﴾ انہوں نے تکبر اور غرور سے ضعیف العقل لوگوں کو ڈراتے اور فریب کاری کرتے ہوئے کہا: ﴿اَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا﴾ ’’کیا ہم اپنے جیسے دو انسانوں پر ایمان لے آئیں؟‘‘ جیسا کہ ان سے پہلے لوگ بھی ایسے ہی کہا کرتے تھے چونکہ کفر میں ان کے دل ایک دوسرے سے مشابہت رکھتے تھے اس لیے ان کے اقوال و افعال بھی ایک دوسرے کے مشابہ تھے، چنانچہ اللہ تعالیٰ نے رسالت کے ذریعے سے ان پر جو عنایت کی انہوں نے اسے جھٹلا دیا ﴿وَ قَوْمُهُمَا﴾ ’’اور ان دونوں کی قوم‘‘ یعنی بنی اسرائیل ﴿لَنَا عٰبِدُوْنَۚ۰۰۴۷﴾ ’’ہماری غلام ہے۔‘‘ یعنی وہ پر مشقت کام سر انجام دینے کے لیے ہمارے مطیع ہیں جیسا کہ اللہ تعالیٰ نے فرمایا: ﴿وَ اِذْ نَجَّيْنٰكُمْ مِّنْ اٰلِ فِرْعَوْنَ يَسُوْمُوْنَكُمْ سُوْٓءَ الْعَذَابِ يُذَبِّحُوْنَ اَبْنَآءَكُمْ وَ يَسْتَحْيُوْنَ نِسَآءَكُمْ١ؕ وَ فِيْ ذٰلِكُمْ بَلَآءٌ مِّنْ رَّبِّكُمْ عَظِيْمٌ۰۰۴۹﴾ (البقرۃ : 49) ’’یاد کرو وہ وقت جب ہم نے تمہیں آل فرعون سے نجات دی وہ تمہیں بہت عذاب دیتے تھے۔ تمہارے بیٹوں کو ذبح کر ڈالتے تھے اور تمہاری بیٹیوں کو زندہ رکھتے تھے۔ اس میں تمہارے رب کی طرف سے بہت بڑی آزمائش تھی۔‘‘ پس ہم ان کے متبوع (پیشوا) ہوتے ہوئے ان کے تابع کیسے بن سکتے ہیں؟ اور یہ ہم پر سردار کیسے ہو سکتے ہیں؟\nان کے قول کی نظیر نوح علیہ السلام کی قوم کا یہ قول ہے ﴿اَنُؤْمِنُ لَكَ وَ اتَّبَعَكَ الْاَرْذَلُوْنَؕ۰۰۱۱۱﴾ (الشعرائ : 111) ’’کیا ہم تجھے مان لیں حالانکہ تیری پیروی تو رذیل لوگوں نے کی ہے۔‘‘ ﴿وَ مَا نَرٰىكَ اتَّبَعَكَ اِلَّا الَّذِيْنَ هُمْ اَرَاذِلُنَا بَادِيَ الرَّاْيِ١ۚ﴾ (ہود : 27) ’’ہم دیکھ رہے ہیں کہ صرف انہی لوگوں نے تیری پیروی کی ہے جو ہماری قوم میں رذیل اور چھچھورے تصور کیے جاتے ہیں۔‘‘ اور یہ بات واضح ہے کہ حق کو رد کرنے کے لیے یہ بات درست نہیں ہے اور ظاہر ہے کہ یہ تکذیب اور عناد ہے، اس لیے فرمایا: ﴿فَکَذَّبُوْھُمَا فَکَانُوْا مِنَ الْمُھْلَکِیْنَ﴾ ’’پس انہوں نے ان دونوں کو جھٹلایا اور وہ بھی ہلاک شدہ لوگوں میں ہو گئے۔‘‘ یعنی بنی اسرائیل کے آنکھوں دیکھتے سمندر میں ڈوب کر ہلاک ہو گئے۔\n﴿وَلَقَدْ اٰتَیْنَا مُوْسَی الْکِتٰبَ﴾ ’’اور دی ہم نے موسیٰ کو کتاب۔‘‘ جب اللہ تعالیٰ نے فرعون کو ہلاک کرکے اسرائیلی قوم کو موسیٰ علیہ السلام کی معیت میں نجات بخشی تب موسیٰ علیہ السلام کو قوت اور طاقت حاصل ہوئی کہ وہ اللہ تعالیٰ کے دین کو قائم اور اس کے شعائر کو غالب کریں تو اللہ تعالیٰ نے آپ سے وعدہ فرمایا کہ وہ آپ پر چالیس دن میں تورات نازل کرے گا۔ موسیٰ علیہ السلام اپنے رب کے مقرر کردہ وقت پر پہنچ گئے۔ اللہ تعالیٰ نے فرمایا: ﴿وَ كَتَبْنَا لَهٗ فِي الْاَلْوَاحِ مِنْ كُلِّ شَيْءٍ مَّوْعِظَةً وَّ تَفْصِيْلًا لِّكُلِّ شَيْءٍ١ۚ﴾ (الاعراف : 145) ’’اور ہم نے ہر چیز کے متعلق نصیحت اور ہر چیز کی تفصیل اس کے لیے تختیوں پر لکھ دی، بنابریں یہاں فرمایا: ﴿لَعَلَّہُمْ یَہْتَدُوْنَ﴾ ’’تاکہ وہ ہدایت پائیں۔‘‘ یعنی امرو نہی اور ثواب و عقاب کی تفاصیل کی معرفت حاصل کرکے شاید راہ راست پر گامزن ہو جائیں اور اپنے رب کے اسماء و صفات کی بھی معرفت حاصل کریں۔\n﴿وَ جَعَلْنَا ابْنَ مَرْيَمَ وَ اُمَّهٗۤ اٰيَةً﴾ یعنی ہم نے عیسیٰ بن مریم علیہما السلام پر احسان کیا، ان کو اور ان کی والدہ کو انتہائی تعجب انگیز نشان بنا دیا کیونکہ سیّدہ مریم[ نے سیّدنا عیسیٰ علیہ السلام کو بغیر باپ کے اپنے پیٹ میں رکھا اور پھر آپ کو جنم دیا اور سیّدنا عیسیٰ علیہ السلام نے گہوارے میں کلام کیا اور اللہ تعالیٰ نے آپ کے ہاتھ پر بڑے بڑے معجزات دکھائے۔ ﴿وَّ اٰوَيْنٰهُمَاۤ اِلٰى رَبْوَةٍ﴾ یعنی ہم نے ان دونوں کو ایک بلند مقام پر پناہ دی اور یہ اس وقت کی بات ہے۔ واللہ اعلم! جب سیّدہ مریم[ نے عیسیٰ علیہ السلام کو جنم دیا۔ ﴿ذَاتِ قَرَارٍ﴾ یعنی آرام دہ ٹھکانا ﴿وَّ مَعِيْنٍؒ۰۰۵۰﴾ یعنی جاری چشمے کا پانی اور اس کی دلیل اللہ تعالیٰ کا یہ ارشاد ہے۔ ﴿قَدْ جَعَلَ رَبُّكِ تَحْتَكِ﴾ ’’کر دی ہے تیرے رب نے تیرے نیچے۔‘‘ یعنی اس جگہ سے بہت نیچے جہاں سیّدہ مریم[ نے پناہ لی تھی اور یہ اس لیے کہا گیا کیونکہ آپ بلند جگہ پر تھیں۔ ﴿سَرِيًّا۰۰۲۴﴾ یعنی ندی اور وہ چشمے کا بہتا ہوا پانی ہے۔ ﴿وَ هُزِّيْۤ اِلَيْكِ بِجِذْعِ النَّخْلَةِ تُسٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّاٞ۰۰۲۵ فَكُلِيْ وَ اشْرَبِيْ وَ قَرِّيْ عَيْنًا١ۚ﴾ (مریم : 26,25) ’’تو کھجور کے تنے کو ہلا تجھ پر تازہ کھجوریں گریں گی۔ کھا، پی اور اپنی آنکھوں کو ٹھنڈا کر۔‘‘"],[4586,"§سلطان کا لغوی مفہوم\nسلطان بمعنی غلبہ، قوت، اختیار (منجد، مقائیس اللغۃ) اور بمعنی فرمان شاہی (منجد) یعنی اتھارٹی یا اتھارٹی لیٹر (Athority Letter) وہ اختیار یا اختیار نامہ جو کسی حاکم اعلیٰ سے اس کے نائب کو ملا ہو۔ (اور سلطان بمعنی بادشاہ اس کا کنائی اور مجازی معنی ہے لغوی نہیں۔ نہ ہی قرآن نے اس لفظ کو کسی بھی جگہ ان معنوں میں استعمال کیا ہے) اور اس مقام پر سلطان مبین سے مراد یا ان دونوں نبیوں کی نبوت ہے یا وحی الٰہی اور آیات سے مراد وہ معجزات ہیں جو سیدنا موسیٰ علیہ السلام کو دیے گئے صرف عصا اور ید بیضا ہی نہیں بلکہ دوسرے معجزات بھی کیونکہ یہاں جمع کا صیغہ استعمال ہوا ہے تثنیہ کا نہیں۔ نیز آیات سے مراد احکامِ الٰہی بھی ہو سکتے ہیں۔ جو فرعون کے پاس جاتے وقت انہیں دیے گئے تھے اور جن سے یہ معلوم ہو جاتا تھا کہ ان کی پشت پر کوئی مافوق الفطرت قوت موجود ہے۔"],[4587,"§عبادت کا مفہوم\nیہاں عٰبِدُوْنَ کے لفظ سے عبادت کا مفہوم کھل کر سامنے آ جاتا ہے کہ عبادت محض پوجا پاٹ کا نام نہیں۔ کیونکہ بنی اسرائیل فرعونیوں کی پوجا پاٹ نہیں کرتے تھے۔ بلکہ عبادت کا لفظ اپنے وسیع معنوں میں ہمہ وقت کی غلامی اور فرمانبرداری کے لیے استعمال ہوتا ہے۔"],[4588,"§منکرینِ سنت کا رد\nاس آیت سے دو باتیں معلوم ہوئیں ایک یہ کہ موسیٰ علیہ السلام کو کتاب تورات فرعون اور اس کے سرداروں کی غرقابی کے بعد دی گئی تھی۔ دوسرے یہ کہ جو احکام موسیٰ علیہ السلام کو تورات کے نازل ہونے سے پہلے دیے گئے تھے وہ بھی موسیٰ علیہ السلام اور آپ پر ایمان لانے والوں کے لیے اسی طرح قابل اتباع تھے جس طرح تورات کے احکام۔ اس سے نتیجہ یہ نکلتا ہے کہ نبی پر کتاب اللہ کے علاوہ اللہ کی طرف سے اور بھی بہت کچھ نازل ہوتا ہے اور اس کی اتباع بھی اسی طرح واجب ہوتی ہے جیسے کتاب اللہ کی اور اس میں ان لوگوں کا پورا رد موجود ہے جو کہتے ہیں کہ ہمیں ہدایت کے لیے صرف قرآن ہی کافی ہے۔"],[4589,"§عیسیٰ علیہ السلام کی بن باپ پیدائش کے منکرین کا ردّ\nّ: اللہ تعالیٰ نے یہ نہیں فرمایا کہ ابن مریم[ بھی ایک نشانی تھے اور ان کی والدہ بھی ایک نشانی تھی۔ بلکہ یوں فرمایا ان دونوں کو ملا کر ایک نشانی بنایا اور اس کی صورت صرف یہی رہ جاتی ہے کہ سیدنا عیسیٰ کی ولادت کو بن باپ تسلیم کیا جائے نیز یہ بھی کہ سیدہ مریم کسی مرد کے چھوئے بغیر ہی نفخہ الٰہی سے حاملہ ہوئی تھیں۔"],[4590,"§ربوۃ کا لغوی مفہوم اور اس سے مراد\nربوۃ سے مراد ایسی زمین ہے جو عام سطح زمین سے قدرے بلند ہو اور اس کی مٹی بھر بھری اور ریتلی قسم کی ہو۔ ایسی زمین پانی کو اپنے اندر جذب کرکے خوب پھول جاتی ہے۔ پنجابی میں ایسی زمین کو ’’میری زمین‘‘ کہتے ہیں۔ اس زمین کی خصوصیت یہ ہے کہ یہ عام زمین کی نسبت سرسبز و شاداب بھی زیادہ ہوتی ہے اور بلند بھی ہوتی ہے۔\nاب اس ربوۃ کی تعین میں مفسرین کا اختلاف ہے بعض کہتے ہیں کہ اس سے مراد وہی بلند مقام ہے جہاں سیدنا عیسیٰ علیہ السلام کی پیدائش ہوئی تھی اور اللہ تعالیٰ نے وہاں ایک چشمہ بھی جاری کر دیا تھا اور کھجور کے ٹنڈ درخت سے اللہ کے حکم سے تازہ کھجوریں گرنے لگی تھیں اور بعض کہتے ہیں کہ اس وقت کا ظالم یہودی بادشاہ ہیر وڈس سیدنا عیسیٰ علیہ السلام کا دشمن بن گیا تھا۔ سیدہ مریم ان کی حفاظت کی خاطر اللہ کے حکم سے مصر کی طرف ہجرت کر گئیں اور ایک بلند چشمہ دار جگہ پر قصبہ میں مقیم ہوئیں جسے رملہ کہتے ہیں۔ سیدنا عیسیٰ علیہ السلام وہیں جوان ہوئے پھر جب ہیر وڈس مر گیا تو سیدہ مریم انہیں لے کر اپنے وطن واپس آ گئیں۔ اسرائیلی روایات اسی توجیہ کی تائید کرتی ہیں۔\nاور ربوۃ کے ساتھ ذات قرار سے مراد ایسی جگہ ہے جہاں ضروریات زندگی مہیا ہو سکتی ہوں اور انسان کو وہاں قیام کرنے میں کوئی مشکل پیش نہ آئے اور معین کا لفظ تائید مزید کے لیے ہے۔ جس کا معنی جاری پانی، نتھرا پانی، بہتا ہوا چشمہ، ٹھنڈا اور میٹھا پانی سب کچھ آتا ہے۔\nبیسویں صدی عیسوی کے آغاز میں ہندوستان کے ضلع گورد اسپور میں واقع ایک قصبہ قادیان میں ایک شخص مرزا غلام احمد نے نبوت کا دعویٰ کر دیا۔ وہ خود تو وہیں قادیان میں دفن ہوا اور اس کا مدفن بھی وہیں بنا۔ 1947ء میں پاکستان بنا تو مرزا صاحب کی امت وہاں سے پاکستان کے ضلع جھنگ میں منتقل ہوئی اسی طرح ایک بلند زمین اپنے ہیڈ کوارٹر کے لیے منتخب کی اور اس کا نام ربوہ رکھ لیا۔ مرزا صاحب کے خلیفے اور اولاد وہیں اقامت پذیر ہیں۔"],[4591,"§مرزا قادیانی کا مسیح موعود ہونے کا دعویٰ اور عیسیٰ علیہ السلام کی قبر کی نشاندہی\nمرزا صاحب نے صرف نبوت کا ہی دعویٰ نہیں کیا بلکہ مسیح موعود ہونے کا دعویٰ بھی کیا تھا۔ مرزا صاحب عیسیٰ علیہ السلام کی معجزانہ پیدائش کے تو قائل تھے لیکن رفع عیسیٰ کے قائل نہیں تھے۔ کیونکہ اگر وہ اس کے قائل ہوتے تو آپ کو مسیح موعود بننے میں مشکل پیش آتی تھی۔ ان کی امت نے تو جھنگ میں ایک ربوہ بنا لیا لیکن خود انہوں نے کشمیر کو ربوہ قرار دیا۔ سیدنا عیسیٰ علیہ السلام کی طبعی موت قرار دینے کے بعد فرمایا کہ ان کی قبر کشمیر میں ہے۔ کشمیر کے صدر مقام سری نگر کے محلہ خان یار میں ایک قبر ’’یوسف آز‘‘ کے نام سے مشہور ہے۔ عوام میں یہ بات مشہور ہے کہ یہ کسی نبی کی قبر ہے جو کوئی شہزادہ تھا اور کسی دوسرے ملک سے یہاں آیا تھا۔ مرزا صاحب کے مقصد کے لیے یہ بے سروپا افواہیں ہی کافی تھیں۔ چنانچہ ان کو الہام ہو گیا کہ یہ قبر تو عیسیٰ علیہ السلام ہی کی ہے۔ اب اگر ان کی امت کے بقول ان کے الہام کو درست سمجھ بھی لیا جائے تو سوال پیدا ہوتا ہے کہ اس آیت میں صرف سیدنا عیسیٰ کا ذکر نہیں بلکہ ان کی والدہ کا بھی ذکر ہے لہٰذا ان کو الہام تو دو قبروں کا ہونا چاہیے تھا۔ مگر افسوس ہے کہ وہاں قبر صرف ایک ہی ہے۔ اس سے ان کی نبوت اور الہامات کی بھی قلعی کھل جاتی ہے۔\nثُمَّ اَرْسَلْنَا مُوْسٰى وَاَخَاہُ ہٰرُوْنَ: ان پیغمبروں کے بعد جن کا پہلے تذکرہ ہوا ہے ہم نے موسیٰ علیہ السلام اور اس کے بھائی ہارون علیہ السلام کو فرعون اور قبطیوں کی جانب واضح نشانیوں اور روشن دلائل کے ساتھ بھیجا لیکن انہوں نے ان کی اطاعت سے سرکشی اختیار کی اور ان کی اطاعت سے انکار کیا حقیقت یہ ہے کہ ان کے مزاج میں خود سرائی اور کبر و رعونت کا داعیہ ابھرا ہوا تھا، موسیٰ علیہ السلام اور ہارون علیہ السلام کے بارے میں انہوں نے کھل کر کہا کہ ہم ان کی اطاعت نہیں کریں گے جبکہ ان دونوں کی قوم بنی اسرائیل ہمارے خادم ہیں اور ہماری بنیادی ضرورتوں کی تکمیل ان کی ذمہ داری ہے بھلا اس قماش کے لوگ منصب رسالت کا استحقاق رکھتے ہیں ان کی کیفیت بالکل قریش مکہ کے ساتھ ملتی جلتی ہے جنہوں نے فخر و غرور کے عالم میں رسول اکرم جناب محمد صلی اللہ علیہ وسلم کی حیثیت کو معمولی قرار دیتے ہوئے یہ جملہ دہرایا کہ اگر اللہ پاک نے قرآن پاک کو کسی شخص پر نازل کرنا تھا تو طائف اور مکہ مکرمہ دونوں شہروں میں سے کسی سرمایہ دار عظیم شخصیت پر نازل ہوتا انہیں معلوم نہیں کہ نبوت اور رسالت کے عطا کرنے کا معیار مادی وسائل کی فراوانی نہیں ہے بلکہ نفسیاتی خوبیوں اور اخلاقی برتری کارہین منت ہے، مزید برآں دنیوی علائق سے انہیں نفرت ہو اور اللہ تعالیٰ کی جانب ان کا رجحان سر بر آوردہ ہو۔\nچنانچہ فرعون اور اس کے رفقاء نے موسیٰ علیہ السلام اور ہارون علیہ السلام کو جھوٹا قرار دیا تو اللہ تعالیٰ نے انہیں بحر قلزم (The Redsea) کی لہروں کے سپرد کر دیا جیسا کہ ان سے پہلے لوگوں کو تباہ و برباد کیا جنہوں نے پیغمبروں کی مخالفت کی اور کفر پر ڈٹے رہے ان کی تباہی کے بعد ہم نے موسیٰ علیہ السلام کو تورات عطا کی جو مامورات و منہیات الٰہیہ پر مشتمل تھی شاید باقی ماندہ لوگ حق و صداقت کو قبول کریں اور احکام الٰہیہ کے مطابق زندگی بسر کریں۔\nوَجَعَلْنَا ابْنَ مَرْیَمَ وَاُمَّہٗ اٰیَۃً: اور ہم نے عیسیٰ بن مریم کو لوگوں کے لیے نشان عبرت بنایا اور اس کی تخلیق ہماری عظیم قدرت پر گواہ ہے جبکہ ہم نے اس کو باپ کے بغیر پیدا کیا، مزید ابھی وہ سن رضاعت میں تھے کہ انہوں نے گفتگو کی اور انہیں مزید عظمت عطا کی کہ مادر زاد اندھے (Blind) اور پھلبہری کی بیماری والے مریض ان کی دعا سے شفایاب ہو جاتے اور مردوں کو زندہ کر لیتے تھے جبکہ ان کی والدہ نے عیسیٰ علیہ السلام کو باپ کے بغیر جنم دیا پس ان دونوں کا وجود عادتِ مستمرہ کے خلاف ظہور پذیر ہوا اور ہم نے ان دونوں کو اونچی جگہ پر اتارا جہاں پھلوں کی کثرت کے ساتھ پانی بھی وافر مقدار میں تھا۔\nيٰۤاَيُّهَا الرُّسُلُ كُلُوْا مِنَ الطَّيِّبٰتِ وَ اعْمَلُوْا صَالِحًا١ؕ اِنِّيْ بِمَا تَعْمَلُوْنَ عَلِيْمٌؕ۰۰۵۱\nوَاِنَّ هٰذِهٖۤ اُمَّتُكُمْ اُمَّةً وَّاحِدَةً وَّ اَنَا رَبُّكُمْ فَاتَّقُوْنِ۰۰۵۲ فَتَقَطَّعُوْۤا اَمْرَهُمْ\nبَيْنَهُمْ زُبُرًا١ؕ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُوْنَ۰۰۵۳ فَذَرْهُمْ فِيْ غَمْرَتِهِمْ حَتّٰى\nحِيْنٍ۰۰۵۴ اَيَحْسَبُوْنَ اَنَّمَا نُمِدُّهُمْ بِهٖ مِنْ مَّالٍ وَّ بَنِيْنَۙ۰۰۵۵ نُسَارِعُ لَهُمْ فِي\nالْخَيْرٰتِ١ؕ بَلْ لَّا يَشْعُرُوْنَ۰۰۵۶\n(فرمایا:) اے رسولو! تم پاکیزہ چیزوں میں سے کھائو اور نیک عمل کرو، بے شک تم جو عمل کرتے ہو میں اسے خوب جانتا ہوں\\ اور بلاشبہ یہ تمھارا دین ایک ہی دین ہے اور میں تمھارا رب ہو، لہٰذا تم مجھ سے ڈرو| پھر انھوں نے اپنا معاملہ آپس میں ٹکڑے ٹکڑے کر ڈالا، ہر فرقے کے پاس جو کچھ ہے وہ اسی پر شاداں و فرحاں ہے رحمہ اللہ چنانچہ (اے نبی صلی اللہ علیہ وسلم!) آپ انھیں ان کی غفلت میں ایک (مقرر) وقت تک چھوڑ دیں رحمہ اللہ کیا وہ سمجھتے ہیں کہ بے شک ہم جو بھی ان کے مال اور اولاد میں اضافہ کیے جا رہے ہیں (تو) کیا ہم ان کے لیے بھلائیوں میں جلدی کر رہے ہیں (نہیں نہیں) بلکہ، وہ (اصل حقیقت کا) شعور نہیں رکھتے"],[4592,"§اکل حلال اور عمل صالح کا حکم\nاللہ تعالیٰ نے اپنے تمام پیغمبروں علیہما السلام کو حکم دیا تھا کہ وہ حلال کھائیں اور اعمال صالحہ بجا لائیں، یہ حکم اس بات کی دلیل ہے کہ اکل حلال عمل صالح کے لیے معاون ثابت ہوتا ہے۔ تمام انبیائے کرام نے اس ارشاد باری تعالیٰ کی مکمل تعمیل فرمائی تھی۔ قول و عمل اور رہنمائی و نصیحت کے اعتبار سے انہوں نے ہر خیر و بھلائی کو پیش نظر رکھا تھا: اللہ تعالیٰ انہیں اپنے تمام بندوں کی طرف سے بہترین جزا عطا فرمائے۔ سعید بن جبیر رحمہ اللہ اور ضحاک رحمہ اللہ فرماتے ہیں: ﴿كُلُوْا مِنَ الطَّيِّبٰتِ﴾ ’’تم پاکیزہ چیزوں میں سے کھائو۔‘‘ میں پاکیزہ چیزوں سے مراد رزق حلال ہے۔ صحیح (بخاری) میں ہے: ((مَا بَعَثَ اللہُ نَبِیًّا اِلَّا رَعَی الْغَنَمَ، فَقَالَ اَصْحَابُہٗ: وَاَنْتَ؟ فَقَالَ: نَعَمْ! کُنْتُ اَرْعَاھَا عَلٰی قَرَارِیطَ لِاَھْلِ مَکَّۃَ)) ’’ہر ایک نبی نے بکریاں چرائی ہیں، صحابہ کرام رضی اللہ عنہم نے عرض کی: آپ نے بھی؟ فرمایا: ہاں، میں اہل مکہ کی بکریاں چند قیراط کے عوض چرایا کرتا تھا۔‘‘ (صحیح البخاری، حدیث : 2262 و سنن ابن ماجہ، حدیث: 2149) صحیح (بخاری) میں ہے: ((وَاِنَّ نَبِیَّ اللہِ دَاوٗدَ کَانَ یَاْکُلُ مِنْ عَمَلِ یَدِہٖ)) ’’یقیناً اللہ کے نبی داؤد علیہ السلام اپنے ہاتھ کی کمائی سے کھایا کرتے تھے۔‘‘ (صحیح البخاری، حدیث : 2072)\nصحیح مسلم، جامع ترمذی اور مسند احمد میں ہے اور یہ الفاظ مسند احمد ہی کے ہیں کہ سیّدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((اَیُّھَا النَّاسُ! اِنَّ اللہَ طَیِّبٌ لَّا یَقْبَلُ اِلَّا طَیِّبًا، وَّاِنَّ اللہَ اَمَرَ الْمُوْمِنِیْنَ بِمَا اَمرَ بِہِ الْمُرْسَلِیْنَ، فَقَالَ: ﴿يٰۤاَيُّهَا الُّسُلُ كُلُوْا مِنَ الطَّيِّبٰتِ وَ اعْمَلُوْا صَالِحًا١ؕ اِنِّيْ بِمَا تَعْمَلُوْنَ عَلِيْمٌؕ۰۰۵۱﴾ وَقَالَ: ﴿يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْا كُلُوْا مِنْ طَيِّبٰتِ مَا رَزَقْنٰكُمْ﴾ (البقرۃ: 172) ثُمَّ ذَکَرَ: الرَّجُلُ یَطِیلُ السَّفَرَ اَشْعَثَ اَغْبَرَ ثُمَّ یَمُدُّ یَدَیْہِ اِلَی السَّمَائِ: یَا رَبِّ! یَا رَبِّ! وَمَطْعَمُہٗ حَرَامٌ، وَّمَشْرَبُہٗ حَرَامٌ، وَّمَلْبَسُہٗ حَرَامٌ، وَّغُذِیَ بِالْحَرَامِ، فَاَنّٰی یُسْتَجَابُ لِذٰلِکَ)) ’’اے لوگو! بے شک اللہ تعالیٰ پاک ہے، وہ پاک ہی کو قبول فرماتا ہے اور بے شک اللہ تعالیٰ نے مومنوں کو بھی وہی حکم دیا ہے، جو اس نے پیغمبروں کو حکم دیا تھا اور وہ یہ ہے: ’’اے پیغمبرو! تم پاک چیزوں میں سے کھائو اور نیک عمل کرو، تم جو عمل کرتے ہو میں ان سے خوب واقف ہوں۔‘‘ اور مومنوں سے فرمایا: ’’اے ایمان والو! جو پاکیزہ چیزیں ہم نے تم کو عطا فرمائی ہیں ان میں سے کھائو۔‘‘ پھر آپ نے ایک ایسے شخص کا ذکر فرمایا جو طویل سفر کرتا ہے، اس کے بال پرا گندہ اور غبار آلود ہیں۔ اور اس کا کھانا حرام کا، پینا حرام کا، لباس حرام کا اور وہ حرام ہی کے ساتھ پروان چڑھا ہے۔ وہ اپنے دونوں ہاتھ آسمان کی طرف دراز کرکے کہتا ہے: یا رب! یا رب! تو اس شخص کی دعا کیسے قبول کی جائے گی؟ (مسند احمد) امام ترمذی نے اس حدیث کو حسن غریب قرار دیا ہے۔\n(صحیح مسلم، حدیث : 1015 و جامع الترمذی، حدیث : 2989)"],[4593,"§تمام انبیائے کرام کا دین توحید ہے\nارشاد باری تعالیٰ ہے: ﴿وَ اِنَّ هٰذِهٖۤ اُمَّتُكُمْ اُمَّةً وَّاحِدَةً﴾ ’’اور یہ تمہاری ملت یقیناً ایک ہی ملت و شریعت ہے۔‘‘ یعنی اے گروہ انبیاء! تم سب کا دین بھی ایک اور ملت بھی ایک ہے اور وہ اللہ وحدہ لا شریک کی عبادت کی طرف دعوت دینا ہے، اس لیے فرمایا: ﴿وَّ اَنَا رَبُّكُمْ فَاتَّقُوْنِ۰۰۵۲﴾ ’’اور میں تمہارا پروردگار ہوں، پس تم مجھ ہی سے ڈرو۔‘‘ اس کے بارے میں بحث قبل ازیں سورۂ انبیاء میں گزر چکی ہے۔ (دیکھیے: الانبیائ، آیت : 92 کے ذیل میں) اور اس کا یہ فرمان: ﴿اُمَّۃً وَّاحِدَۃً﴾ حال ہونے کی وجہ سے منصوب ہے۔"],[4594,"§رسولوں کو پاکیزہ اشیاء کھانے کا حکم\nپاکیزہ چیزوں سے مراد وہ چیزیں ہیں جن کا کھانا شریعت نے حلال قرار دیا ہو اور انہیں حلال ذرائع سے ہی حاصل کیا گیا ہو۔ اس کی مثال یوں سمجھیے کہ مرغی بذات خود حلال چیز ہے مگر جب یہ چوری کی ہو تو حرام ہو جائے گی۔ اسی طرح سود یا دوسرے ناجائز ذرائع سے حاصل شدہ مال حرام مال تصور ہو گا۔"],[4595,"§کسبِ حلال کی اہمیت\nکسب حلال اور حرام سے اجتناب اس قدر اہم حکم ہے جس کا اللہ تعالیٰ نے نیک اعمال سے پہلے ذکر فرمایا۔ جس کا مطلب یہ ہوا کہ اگر کسی کی کمائی حرام کی ہو تو اس کے نیک اعمال بھی قبول نہیں ہوتے۔ اس سلسلہ میں ہم سورہ بقرہ کی آیت نمبر 168 کے تحت آٹھ حدیثیں درج کر چکے ہیں جن کو دوبارہ دیکھ لینا مفید ہوگا۔ تاکہ اس اہم شرعی حکم کی اہمیت پوری طرح معلوم ہو جائے۔"],[4596,"§امۃ واحدۃ کا مفہوم\nامت سے مراد ایسا گروہ ہے جو ہم عقیدہ وہم خیال ہو اور یہاں تمہاری امت سے مراد انبیاء و رسل کی جماعت بھی ہو سکتی ہے اور ان کے ساتھ ان پر ایمان لانے والے بھی اور یہ پوری کی پوری جماعت متحد العقیدہ تھی۔ یعنی ان سب کی اصولی تعلیم اور اصول و عقائد ایک ہی جیسے رہے ہیں اور وہ یہ ہیں کہ (1) اللہ تعالیٰ ہی ہر چیز کا خالق و مالک ہے لہٰذا وہی اس بات کا مستحق ہے کہ اس کی عبادت کی جائے اور اس کی ذات و صفات اور عبادات میں کسی دوسرے کو شریک نہ کیا جائے۔ (2) یہ دنیا دار الامتحان ہے۔ مرنے کے بعد ہر انسان کو دوبارہ زندہ کیا جائے گا اور اسے اللہ کے حضور پیش ہونا پڑے گا۔ دنیا میں جو اعمال وہ کرتا رہا اس کے متعلق اس سے باز پرس ہو گی۔ پھر ہر ایک کو اس کے اچھے یا برے اعمال کا پورا پورا بدلہ دیا جائے گا۔ لہٰذا تمہیں صرف مجھ سے ڈرنا چاہیے۔ (3) کسبِ حرام سے مکمل طور پر اجتناب یعنی کسی صورت میں بھی دوسرے کے حقوق یا اموال پر ڈاکہ نہ ڈالا جائے (4) اور نیک اعمال بجا لائے جائیں یہ چار باتیں ایسی ہیں جو اصولی نوعیت کی ہیں اور ان کا حکم ہر نبی کو دیا جاتا رہا ہے اور انہی باتوں کا نام دین ہے۔ رہے جزئی احکام جن کا تعلق بالخصوص شق نمبر 3 سے ہے تو اس میں انبیاء کی شریعتوں میں اختلاف بھی رہا ہے۔"],[4597,"§دین کے اصول چار اور فرقے سینکڑوں\nیعنی اصل دین میں چند موٹی موٹی باتیں شامل تھیں اور ہر نبی یہی اصول دین پیش کرتا رہا۔ مگر لوگوں نے انہیں اصول دین میں اختلاف کرکے سینکڑوں فرقے بنا ڈالے۔\nمثلاً پہلی شق توحید ہی کو لیجئے۔ شیطان نے شرک کی بیسیوں نئی سے نئی قسمیں ایجاد کرکے لوگوں کو اس راہ پر ڈال دیا بعض لوگوں نے کسی شخص، نبی یا فرشتوں کو اللہ کی اولاد قرار دیا۔ حلول اور اوتار کا عقیدہ وضع کیا اور اللہ تعالیٰ کو بعض لوگوں کے اجسام میں اتار دیا۔ کسی نے کہا کہ فلاں ہستی اللہ کے نور میں سے (جدا شدہ) نور ہے۔ کئی ہستیوں کو اللہ کے علاوہ عالم الغیب اور حاضر و ناظر تسلیم کیا گیا اور سب سے بڑھ کر یہ کہ حضرت انسان نے جسے تمام مخلوق سے افضل و اشرف پیدا کیا گیا تھا، اپنے نفع و نقصان کو پتھروں، درختوں، مویشیوں، ستاروں، جن بھوتوں اور آستانوں سے وابستہ کر دیا اور ان کے آگے سر تسلیم خم کرنے لگا۔ انہیں سے مرادیں مانگنے لگا۔"],[4598,"§فرقے کیسے بنتے ہیں اور ہر فرقہ کی خود پسندی\nدوسری شق آخرت پر ایمان ہے۔ بعض لوگوں نے تو روز آخرت اور دوبارہ جی اٹھنے کا انکار ہی کر دیا اور جنہوں نے اسے تسلیم کیا انہوں نے بھی اس کے تقاضوں کو نہ سمجھا۔ بعض نے کہا کہ ہم چونکہ انبیاء کی اولاد یا سادات ہیں۔ لہٰذا ہمیں کیسے عذاب ہو سکتا ہے۔ بعض لوگوں نے سفارش کے عقیدے وضع کر لیے اور اگر فلاں حضرت کی بیعت کر لی جائے تو وہ شفاعت کرکے ہمیں چھڑا لیں گے۔ بعض نے یہی عقیدہ اپنے دیوتائوں سے یا بتوں سے وابستہ کر دیا۔ نصاریٰ نے کفارۂ مسیح کا عقیدہ گھڑ لیا اور بعض پادری حضرات اس دنیا میں ہی لوگوں سے رقوم بٹور کرکے ان کے لیے معافی نامے جاری کرنے لگے اور بعض لوگوں نے یہ عقیدہ وضع کیا کہ اگر فلاں حضرت کے بہشتی دروازہ سے اس کے عرس کے دن نیچے سے گزرا جائے تو یقیناً نجات ہو جائے گی ایسے سستی نجات کے سب عقیدے لغو اور باطل ہیں اور قرآن نے ایسے عقائد رکھنے والوں کو آخرت کے منکر یعنی کافر قرار دیا ہے۔\nتیسری شق حلال اور پاکیزہ اشیاء کھانے سے متعلق تھی تو اس میں بھی لوگوں نے افراط و تفریط کی راہیں پیدا کر لیں۔ رہبان و مشائخ اور بعض صوفیاء نے اپنے اوپر حلال اشیاء کو حرام قرار دے لیا اور بعض دوسروں نے حرام و حلال کی تمیز ہی ختم کر دی اور سود جیسی حرام چیز کو جسے ساری شریعتوں میں حرام قرار دیا جاتا رہا ہے اسے حلال ثابت کرنے کی کوشش کی۔ بہت سے علماء و مشائخ، بتوں کے مہنتوں، مقبروں اور مزاروں کے مجاوروں نے حلت و حرمت کے اختیار خود سنبھال لیے اور ایسے لوگوں کا تذکرہ قرآن میں متعدد بار آیا ہے۔\nچوتھی شق عمل صالح کی تھی۔ تو غالباً اس شق میں شرک سے بھی زیادہ فرقہ بازی ہوئی۔ دین کے بعض اصولی احکام کو مسخ کرکے بدعی عقائد و اعمال شامل کر دیے گئے اور ان باتوں کی اصل بنیاد حبِ جاہ و مال تھی اور بے شمار سیاسی اور بدعی قسم کے فرقے وجود میں آ گئے۔ انہی میں سے ایک تقلید شخصی کا عقیدہ ہے جس کے ذریعہ اماموں کو نبیوں کا درجہ دے دیا گیا یا ان سے بھی بڑھ کر سمجھا گیا۔\nگویا اس سادہ اور مختصر سی اصولی تعلیم سے اختلاف کرکے لوگ جو فی الحقیقت ایک ہی امت تھے سینکڑوں اور ہزاروں فرقوں میں بٹتے چلے گئے اور لطف کی بات یہ ہے کہ ان میں ہر فرقہ اپنے آپ کو حق پر سمجھتا ہے اور اپنے علاوہ دوسرے فرقوں کو دوزخ کا ایندھن سمجھتا ہے۔ حالانکہ یہ اصولی تعلیم آج بھی موجود ہے اور اگر کوئی شخص یا کوئی فرقہ تعصب سے بالاتر ہو کو راہ حق کو تلاش کرنا چاہے تو راہ حق آج بھی ایسی چھپی ہوئی چیز نہیں ہے جس کا سراغ نہ لگایا جا سکتا ہو۔"],[4599,"§کیا آسودہ حالی اللہ کی رضا مندی کی علامت ہے؟\n؟: دنیا دار اور جاہل لوگ عموماً یہ سمجھتے ہیں کہ آسودہ حالی اللہ کی رضا مندی کی علامت ہوتی ہے اور تندرستی یا پریشان حالی اللہ تعالیٰ کی ناراضی کی۔ حالانکہ بسا اوقات معاملہ اس کے برعکس ہوتا ہے۔ چودھری لوگوں کی سرکشی کا بڑا سبب یہی نظریہ ہوتا ہے وہ دیکھتے ہیں کہ پیغمبروں کی تکذیب کرنے اور ایمان داروں پر ظلم و زیادتی روا رکھنے کے باوجود بھی ان کا کچھ نہیں بگڑا تو وہ اس نظریہ پر مزید پختہ ہو جاتے ہیں۔ اب اللہ کی طرف سے ان پر ابتلاء کا دور یوں آتا ہے کہ ان پر مزید انعامات الٰہی کی بارش ہونے لگتی ہے۔ حالانکہ ان انعامات کی حیثیت ایسے ہی ہوتی ہے جیسے بجھنے والا چراغ بجھنے سے پیشتر ایک دفعہ خوب روشن ہو جاتا ہے۔ لیکن وہ اس حقیقت کو نہیں سمجھتے کہ مال و دولت اور نعمتوں کی فراوانی اللہ کی خوشنودی کے طور پر نہیں بلکہ امہال و استدراج کی بنا پر ہے اور جتنی انہیں ڈھیل دی جا رہی ہے اسی قدر ان کی شقادت کا پیمانہ لبریز ہو رہا ہے۔\n﴿طَیِّبَاتِ﴾ سے مراد پاکیزہ اور لذت بخش چیزیں ہیں، بعض نے اس کا ترجمہ حلال چیزیں کیا ہے۔ دونوں ہی اپنی جگہ صحیح ہیں کیونکہ ہر پاکیزہ چیز اللہ نے حلال قرار دی ہے اور ہر حلال چیز پاکیزہ اور لذت بخش ہے۔ خبائث کو اللہ نے اسی لیے حرام کیا ہے کہ وہ اثرات و نتائج کے لحاظ سے پاکیزہ نہیں ہیں۔ گو خبائث خور قوموں کو اپنے ماحول اور عادت کی وجہ سے ان میں ایک گونہ لذت ہی محسوس ہوتی ہو۔ عمل صالح وہ ہے جو شریعت یعنی قرآن و حدیث کے موافق ہو، نہ کہ وہ جسے لوگ اچھا سمجھیں کیونکہ لوگوں کو تو بدعات بھی بہت اچھی لگتی ہیں بلکہ اہل بدعت کے ہاں جتنا اہتمام بدعات کا ہے، اتنا فرائض اسلام اور سنن و مستحبات کا بھی نہیں ہے۔ اکل حلال کے ساتھ عمل صالح کی تاکید سے معلوم ہوتا ہے کہ ان کا آپس میں گہرا تعلق ہے اور یہ ایک دوسرے کے معاون ہیں۔ اکل حلال سے عمل صالح آسان ہوتا ہے اور عمل صالح انسان کو اکل حلال پر آمادہ کرتا اور اسی پر قناعت کرنے کا سبق دیتا ہے۔ اسی لیے اللہ نے تمام پیغمبروں کو ان دونوں باتوں کا حکم دیا۔ چنانچہ تمام پیغمبر محنت کرکے حلال کی روزی کمانے اور کھانے کا اہتمام کرتے رہے، جس طرح سیّدنا داؤد علیہ السلام کے بارے میں آتا ہے ((کَانَ یَا!کُلُ مِنْ کَسْبِ یَدِہِ)) (صحیح بخاری) ’’اپنے ہاتھ کی کمائی سے کھاتے تھے‘‘ اور نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہر نبی نے بکریاں چرائی ہیں، میں بھی اہل مکہ کی بکریاں چند قراریط کے عوض چراتا رہا ہوں۔‘‘ (صحیح بخاری) آج کل بلیک میلروں، سمگلروں، رشوت و سود خوروں اور دیگر حرام خوروں نے محنت مزدوری کرکے حلال روزی کمانے والوں کو حقیر اور پست طبقہ بنا کر رکھ دیا ہے درآں حالیکہ معاملہ اس کے برعکس ہے۔ ایک اسلامی معاشرے میں حرام خوروں کے لیے عزت و شرف کا کوئی مقام نہیں، چاہے وہ قارون کے خزانوں کے مالک ہوں، احترام و تکریم کے مستحق صرف وہ لوگ ہیں جو محنت کرکے حلال کی روزی کھاتے ہیں چاہے روکھی سوکھی ہی ہو۔ اس لیے نبی صلی اللہ علیہ وسلم نے اس کی بڑی تاکید فرمائی ہے اور فرمایا ہے کہ ’’اللہ تعالیٰ حرام کمائی والے کا صدقہ قبول فرماتا ہے نہ اس کی دعا ہی۔‘‘ (صحیح مسلم) ہمیں بھی عزت اور ذلت کے ان معیاروں کو اپنانا چاہیے جو اللہ کے ہاں ہیں۔\nیہ حقیقت ہے کہ اللہ پاک نے ہر پیغمبر کو حکم دیا کہ وہ حلال پاکیزہ لذیذ کھانا تناول کرے اور اعمال صالحہ کرے تاکہ اعمال صالحہ اللہ پاک کے انعامات ظاہریہ اور باطنیہ کے تشکر کا نشان ہوں اگرچہ اس آیت میں انبیاء کرام کو مخاطب کیا گیا ہے جبکہ ان کی امتوں کو بھی ان کی تابع داری کرنے کا حکم دیا گیا ہے کہ وہ بھی ان کے نقش قدم پر رواں دواں رہیں، ابو ہریرۃ رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے لوگو! بلاشبہ اللہ تعالیٰ کی ذات پاک ہے وہ پاک چیز کو ہی قبول کرتا ہے اس کے بعد اس آیت کریمہ کی تلاوت فرمائی پھر آپ نے ایک شخص کے بارے میں وضاحت کی جو طویل سفر کرتا رہتا ہے اس کا جسم غبار آلود رہتا ہے اور اس کے بال بکھرے ہوئے ہیں لیکن اس کا کھانا، پینا اور لباس حرام مال سے لیا گیا ہے ایسا شخص جب اپنے دونوں ہاتھ آسمان کی جانب اٹھاتا ہے اپنے پروردگار کو پکارتا ہے تو اللہ تعالیٰ جواب میں ڈانٹ پلاتے ہیں تیرا کھانا پینا لباس حرام کا ہے کس طرح تیری دعا کو قبولیت حاصل ہو سکتی ہے؟ (صحیح مسلم، صحیح ترمذی،مسند احمد)\nذہن نشین کریں جب انبیاء کرام کو اس کا حکم دیا گیا ہے تو ان کی امتوں کو بھی پیغمبروں کی پیروی کرتے ہوئے پاکیزہ حلال لقمہ منہ میں ڈالنا چاہیے اور اعمال صالحہ پر قائم دائم رہنا چاہیے مزید فرمایا سبھی پیغمبروں کا ایک دین ہے ایک ملت ہے کہ صرف ایک اللہ کی عبادت کی جائے اور میں تمہارا پروردگار ہوں میری ربوبیت اور الوہیت میں میرے ساتھ کسی کو شریک نہ بنائو، حقیقت یہ ہے کہ دین اسلام ایک اکائی ہے وحدت ہے اس میں حزبیت کا شائبہ تک نہیں ہے۔\nفَتَقَطَّعُوْآ اَمْرَہُمْ بَیْنَہُمْ زُبُرًا: لیکن پیغمبروں کی امتوں نے پیغمبروں کی مخالفت کی خواہشات نفسانیہ کی پیروی کی اور دین اسلام کو مختلف فرقوں میں تقسیم کر دیا ہر فرقہ نے خود کو صحیح قرار دیا اور خود کو سچا سمجھا دوسرے کے مسلک کو غلط کہا، انبیاء علیہم السلام کے پیروکاروں سے ہم دریافت کرتے ہیں تمہاری عقل کہاں چلی گئی اللہ تعالیٰ نے تمہاری ہدایت کے لیے پیغمبروں کو مبعوث کیا تمہیں ایک سٹیج (Stage) پر گامزن رہنے کا حکم دیا لیکن تم نے اسلام کے نام پر آپس میں اختلاف کو اجاگر کیا اسلام نے اصول و عقائد کے لحاظ سے تمہیں ایک پلیٹ فارم (Plate Farm) پر گامزن رہنے کا حکم دیا لیکن تم مختلف گروہوں میں منقسم ہو گئے مذاہب کا اختلاف اپنی جگہ پر ہے اس کے سبب عقائد میں اختلاف کو برداشت نہیں کیا جا سکتا کیا دین اسلام میں تبدیلی رونما ہو چکی ہے؟ کیا قرآن کے محتویات میں اختلاف ممکن ہے ہرگز نہیں، لیکن جب اس کے باوجود اتفاق ناپید ہو چکا ہے، حنفیت، شافعیت، مالکیت وغیرہ کے مراکز نظر آ رہے ہیں اختلاف نے معاشرہ میں مسلمانوں کو ایک پلیٹ فارم سے اتار کر مختلف گروہ بندیوں میں تقسیم کر دیا ہے ان میں کوئی بھی گروہ خیر خواہی کی باتوں کو قبول کرنے کے لیے آمادہ نہیں ہے تو اللہ تعالیٰ نے حکم دیا کہ آپ انہیں گمراہی کے گڑھے میں چھوڑ دیں یہاں تک کہ وہ عذاب الٰہی کا اپنی آنکھوں سے مشاہدہ کریں گے۔\nاَیَحْسَبُوْنَ اَنَّمَا نُمِدُّہُمْ بِہٖ مِنْ مَّالٍ وَّبَنِیْنَ: اس آیت کریمہ میں ان کی غلطی کو واضح کیا ہے جبکہ وہ اس خیال میں تھے کہ ہمیں فراوانی سے رزق مل رہا ہے اس سے معلوم ہوتا ہے کہ اللہ پاک ہم پر خوش ہیں ان کے اس غلط خیال کی نفی کرتے ہوئے اللہ پاک نے انہیں کہا کہ تم دھوکے میں مبتلا ہو کہ تمہارے پاس مال اولاد کی کثرت اس وجہ سے ہے کہ اللہ تعالیٰ کے ہاں تمہارا مقام ہے اور وہ تم سے خوش ہے ہرگز نہیں یہ تو اللہ پاک کی جانب سے ڈھیل ہے کہ تم اللہ پاک کی نافرمانیوں میں خود کو نہایت فراخی کے ساتھ مستغرق کیے جائو ان کی کیفیت تو چارپایوں کے مشابہ ہے جو عقل اور شعور سے خالی ہوتے ہیں ان کے ذہن میں یہ خیال گردش ہی نہیں کرتا کہ یہ تو اللہ تعالیٰ کی جانب سے ڈھیل ہے ارشاد ربانی ملاحظہ فرمائیں: ﴿اِنَّمَا نُمْلِيْ لَهُمْ لِيَزْدَادُوْۤا اِثْمًا١ۚ﴾ (آل عمران : 178) ’’ہم ان کو اس لیے ڈھیل دیتے ہیں تاکہ وہ مزید گناہوں میں مستغرق ہوں۔‘‘\nسیّدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے تمہارے درمیان اخلاقیات کو بالکل اسی طرح تقسیم کیا ہے جیسا کہ معیشت کے اسباب کو تقسیم کیا ہے اور یہ حقیقت ہے کہ دنیوی مال و متاع تو اللہ پاک اپنے دوستوں اور دشمنوں کو یکساں طور پر عطا کرتا ہے لیکن دین اسلام کا فہم ان لوگوں کو عطا کرتا ہے جن سے وہ محبت کرتا ہے حقیقت یہ ہے کہ جس شخص کو اللہ پاک نے دین اسلام کا فہم عطا کیا تو گویا کہ اس کو اللہ تعالیٰ نے اپنا دوست بنایا اس ذات کی قسم! جس کے ہاتھ میں محمد کی جان ہے کوئی شخص مسلمان نہیں جب تک کہ اس کا دل اور اس کی زبان اسلام کے اصولوں کے تابع نہیں ہے اور کوئی شخص ایمان دار نہیں ہے جب تک کہ اس کا پڑوسی اس کی تکلیف سے محفوظ نہیں، مقصود یہ ہے کہ نہ مسلمان بھائی کے ساتھ دھوکہ کرے نہ اس پر ظلم کرے۔ (صحیح بخاری، مسند احمد، ابن کثیر : 397/3)\nاِنَّ الَّذِيْنَ هُمْ مِّنْ خَشْيَةِ رَبِّهِمْ مُّشْفِقُوْنَۙ۰۰۵۷ وَ الَّذِيْنَ هُمْ بِاٰيٰتِ رَبِّهِمْ\nيُؤْمِنُوْنَۙ۰۰۵۸ وَ الَّذِيْنَ هُمْ بِرَبِّهِمْ لَا يُشْرِكُوْنَۙ۰۰۵۹ وَ الَّذِيْنَ يُؤْتُوْنَ مَاۤ اٰتَوْا\nوَّقُلُوْبُهُمْ وَجِلَةٌ اَنَّهُمْ اِلٰى رَبِّهِمْ رٰجِعُوْنَۙ۰۰۶۰ اُولٰٓىِٕكَ يُسٰرِعُوْنَ فِي الْخَيْرٰتِ\nوَهُمْ لَهَا سٰبِقُوْنَ۰۰۶۱\nبے شک جو لوگ اپنے رب کے خوف سے ڈرتے رہتے ہیں اور جو لوگ اپنے رب کی آیات پر ایمان لاتے ہیں اور جو لوگ اپنے رب کے ساتھ کسی کو شریک نہیں ٹھہراتے اور جو لوگ (اللہ کی راہ میں) دیتے ہیں جو کچھ بھی دیتے ہیں، تو اس طرح کہ ان کے دل خوف زدہ ہوتے ہیں کہ بے شک وہ اپنے رب کی طرف لوٹنے والے ہیں یہی لوگ بھلائیوں میں جلدی\nکرتے ہیں، اور وہ ان میں باہم سبقت کرنے والے ہیں"],[4600,"§اہل خیر کی صفات\nارشاد باری تعالیٰ ہے: ﴿اِنَّ الَّذِيْنَ هُمْ مِّنْ خَشْيَةِ رَبِّهِمْ مُّشْفِقُوْنَۙ۰۰۵۷﴾ ’’بے شک جو لوگ اپنے پروردگار کے خوف سے ڈرتے ہیں۔‘‘ یعنی وہ اپنی نیکی، ایمان اور عمل صالح کے باوجود اللہ تعالیٰ سے ڈرتے اور خوف کھاتے ہیں کہ وہ انہیں اپنے عذاب کی گرفت میں نہ لے لے۔ امام حسن بصری رحمہ اللہ فرماتے ہیں کہ مومن نیکی کے باوجود ڈرتا ہے اور کافر برائی کے باوجود بے خوف ہوتا ہے۔ (تفسیر البغوی : 368/2 و تفسیر الطبری : 43/18) ﴿وَ الَّذِيْنَ هُمْ بِاٰيٰتِ رَبِّهِمْ يُؤْمِنُوْنَۙ۰۰۵۸﴾ ’’اور جو لوگ اپنے پروردگار کی آیتوں پر ایمان رکھتے ہیں۔‘‘ یعنی اس کی کونی اور شرعی آیتوں پر ایمان رکھتے ہیں جیسا کہ اللہ تعالیٰ نے مریم[ کے بارے میں فرمایا ہے: ﴿وَ صَدَّقَتْ بِكَلِمٰتِ رَبِّهَا وَ كُتُبِهٖ …﴾ الآیۃ (التحریم : 12) ’’اور اس نے اپنے پروردگار کے کلام اور اس کی کتابوں کی تصدیق کی…۔‘‘ یعنی ان کا ایمان تھا کہ جو کچھ ہوا، وہ اللہ تعالیٰ کی قضا و قدر کے مطابق ہے اور اللہ تعالیٰ کی شریعت کے احکام ایسے امور ہیں جنہیں اس کی ذات پاک پسند فرماتی ہے اور نواہی وہ امور ہیں جو اللہ تعالیٰ کو حد درجہ ناپسند ہیں اور اللہ تعالیٰ نے جو حالات و واقعات بیان فرمائے ہیں وہ بالکل سچ ہیں جیسا کہ فرمایا: ﴿وَ الَّذِيْنَ هُمْ بِرَبِّهِمْ لَا يُشْرِكُوْنَۙ۰۰۵۹﴾ ’’اور جو لوگ اپنے پروردگار کے ساتھ کسی کو شریک نہیں ٹھہراتے۔‘‘ یعنی وہ غیر اللہ کی پوجا نہیں کرتے بلکہ وہ اسی کی توحید کے قائل اور اس بات کو جانتے ہیں کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں، وہ ایک ہے اور بے نیاز ہے، اس کی بیوی ہے اور نہ بیٹا، اس کا کوئی نظیر ہے اور نہ ہم سر۔"],[4601,"§نیکی کرنے کے باوجود اللہ کا ڈر\n﴿وَ الَّذِيْنَ يُؤْتُوْنَ مَاۤ اٰتَوْا وَّ قُلُوْبُهُمْ وَجِلَةٌ اَنَّهُمْ اِلٰى رَبِّهِمْ رٰجِعُوْنَۙ۰۰۶۰﴾ ’’اور جو لوگ (اللہ کی راہ میں) دیتے ہیں جو کچھ بھی دیتے ہیں تو اس طرح کہ ان کے دل اس بات سے ڈرتے رہتے ہیں کہ انہیں اپنے پروردگار کی طرف لوٹ کر جانا ہے۔‘‘ یعنی وہ دیتے ہیں مگر ساتھ ہی ڈرتے بھی ہیں کہیں ایسا نہ ہو کہ ان کا دیا ہوا قبول ہی نہ ہو کیونکہ انہیں خدشہ رہتا ہے کہ شاید انہوں نے دینے کی شرائط کو پورا ہی نہ کیا ہو اور یہ سب کچھ اللہ تعالیٰ سے ڈر اور احتیاط کی وجہ سے ہے جیسا کہ امام احمد نے سیّدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے کہ انہوں نے عرض کی: اے اللہ کے رسول! ﴿وَ الَّذِيْنَ يُؤْتُوْنَ مَاۤ اٰتَوْا وَّ قُلُوْبُهُمْ وَجِلَةٌ﴾ سے کیا وہ شخص مراد ہے جو چوری کرتا، زنا کرتا، شراب پیتا اور اللہ عزوجل سے ڈرتا ہے؟ آپ نے فرمایا: ((لَا، یَا بِنْتَ اَبِی بَکْرِ! یَّا بِنْتَ الصِّدِّیقِ! وَلٰکِنَّہُ الَّذِی یُصَلِّی وَیَصُومُ وَیَتَصَدَّقُ وَہُوَ یَخَافُ اللہَ عَزَّوَجَلَّ)) ’’نہیں، اے بنت ابوبکر! اے بنت صدیق! بلکہ اس سے مراد وہ شخص ہے جو نماز پڑھتا، روزہ رکھتا، صدقہ کرتا اور اللہ تعالیٰ سے ڈرتا ہے۔‘‘ (مسند احمد)\nاسی طرح اس حدیث کو امام ترمذی رحمہ اللہ اور ابن ابو حاتم رحمہ اللہ نے روایت کیا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ((لَا، یَا بِنْتَ الصِّدِّیقِ! وَلٰکِنَّہُمُ الَّذِیْنَ یَصُومُوْنَ وَیُصَلُّوْنَ، وَیَتَصَدَّقُونَ وَہُمْ یَخَافُونَ اَنْ لَّا یُقْبَلَ مِنْھُمْ: ﴿اُولٰٓىِٕكَ يُسٰرِعُوْنَ فِي الْخَيْرٰتِ وَ هُمْ لَهَا سٰبِقُوْنَ۰۰۶۱﴾ ’’نہیں، اے بنت صدیق! بلکہ اس سے مراد وہ لوگ ہیں جو نماز پڑھتے، روزہ رکھتے، صدقہ کرتے اور اللہ تعالیٰ سے ڈرتے ہیں کہ کہیں ایسا نہ ہو کہ ان کے اعمال قبول ہی نہ ہوں۔‘‘ یہی لوگ ہیں کہ جلدی کرتے ہیں بھلائیوں میں اور وہ ان کے لیے سبقت کرنے والے ہیں۔‘‘ (جامع الترمذی، حدیث: 3175 و سنن ابن ماجہ، حدیث : 4198) اور سیّدنا ابن عباس رضی اللہ عنہما، محمد بن کعب قرظی رحمہ اللہ اور امام حسن بصری رحمہ اللہ نے بھی اسی طرح فرمایا ہے۔(تفسیر الطبری : 45,44/18)\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے اس آیت کے متعلق نبی اکرم صلی اللہ علیہ وسلم سے پوچھا کہ جو لوگ اللہ کی راہ میں دیتے ہیں، انہیں کس بات کا ڈر لگا رہتا ہے؟ کیا وہ شراب پیتے ہیں یا چوری کرتے ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: صدیق کی بیتی! یہ بات نہیں بلکہ وہ لوگ روزہ رکھتے، نماز پڑھتے اور صدقہ دیتے ہیں۔ اس کے باوجود وہ ڈرتے ہیں کہ شاید ان کا عمل قبول نہ ہو۔ یہی لوگ ہیں جو نیکیوں کی طرف لپکتے اور آگے نکل جانے والے ہیں۔‘‘ (صحیح ترمذی)\nیعنی اللہ کی راہ میں خرچ کرتے ہیں لیکن اللہ سے ڈرتے بھی رہتے ہیں کہ کسی کوتاہی کی وجہ سے ہمارا عمل یا صدقہ نا مقبول قرار نہ پا جائے حدیث میں آتا ہے۔ سیّدہ عائشہ رضی اللہ عنہا نے پوچھا: ’’ڈرنے والے کون ہیں؟ وہ جو شراب پیتے، بدکاری کرتے ہیں اور چوریاں کرتے ہیں؟ نبی صلی اللہ علیہ وسلم نے فرمایا: نہیں، بلکہ یہ وہ لوگ ہیں جو نماز پڑھتے، روزہ رکھتے اور صدقہ و خیرات کرتے ہیں لیکن ڈرتے رہتے ہیں کہ کہیں یہ نا مقبول نہ ٹھہریں۔‘‘ (صحیح ترمذی، مسند احمد) گویا نیک لوگ نیکی کرکے گھمنڈ میں مبتلا نہیں ہوتے، بلکہ خوف الٰہی سے لرزاں رہتے ہیں۔\nقبل ازیں اللہ پاک نے ان لوگوں کو مذموم قرار دیا ہے جنہوں نے دین اسلام میں تفرقہ بازی کو قائم کیا اور اپنی علم و آگہی پر خوش رہے جبکہ انہیں خبردار کیا جا رہا ہے کہ وہ وہم و گمان میں مبتلا ہیں اس کے بعد ان لوگوں کا تذکرہ ہو رہا ہے جن میں اعمال صالحہ کی جانب رغبت کا داعیہ موجود ہے ان کے اوصاف بیان ہو رہے ہیں کہ وہ اپنے پروردگار کے عذاب کے خوف سے اللہ پاک کی اطاعت پر ہمیشہ رواں دواں رہتے ہیں تاکہ اس کی خوشنودی حاصل ہو، مزید اللہ پاک کی ناراضگی سے خوف زدہ ہوتے ہوئے گناہ کے کاموں سے دور رہتے ہیں اور اللہ پاک کی قدرت پر آفاقی اور انفسی دلائل پر یقین کرتے ہوئے وہ اللہ تعالیٰ کی ذات کے ساتھ کسی کو شریک نہیں کرتے ہیں انہیں یقین ہے کہ اللہ تعالیٰ وحدہٗ لا شریک ذات ہے اس کے ساتھ کوئی بھی عبادت کے لائق نہیں وہ اکیلا ہے بے نیاز ہے وہ بیوی، اولاد سے بے نیاز ہے۔\nاللہ پاک تو نہ صرف یہ کہ توحید فی الربوبیۃ کے وصف کے ساتھ موصوف ہے بلکہ توحید فی الالوہیۃ میں بھی اس کا کوئی شریک نہیں ہے جبکہ مشرکین کی کثیر تعداد توحید فی الربوبیۃ کو تسلیم کرتی ہے لیکن توحید فی الالوہیۃ کا انکار کرتے ہیں اسی لیے وہ بت پرستی وغیرہ کرتے ہیں، مزید ایمان دار لوگ جب صدقہ خیرات کرتے ہیں تو ان کے دلوں میں خوف برابر جاگزیں رہتا ہے کہ شاید ان کا یہ عمل اللہ تعالیٰ کے ہاں قبولیت سے ہم کنار نہ ہو سکے چنانچہ عائشہ صدیقہ رضی اللہ عنہا نے جب رسول اللہ صلی اللہ علیہ وسلم سے ﴿وَالَّذِیْنَ یُؤْتُوْنَ مَآ اٰتَوْا﴾ کے بارے میں دریافت کیا، کیا اس سے مقصود وہ لوگ ہیں جو زنا کے مرتکب ہوتے ہیں شراب پیتے ہیں چوری کے مرتکب ہوتے ہیں اور ان گناہوں کا ارتکاب کرتے وقت اللہ سے خوف زدہ رہتے ہیں؟ آپ صلی اللہ علیہ وسلم نے انہیں مخاطب کرتے ہوئے جواب دیا نہیں! اے ابوبکر کی بیٹی! جبکہ اس سے مقصود تو وہ شخص ہے جو نماز ادا کرتا ہے روزہ رکھتا ہے صدقہ خیرات کرتا ہے لیکن ان اعمال صالحہ کی ادائیگی پر وہ خوف زدہ رہتا ہے شاید بارگاہ الٰہی میں ان کی قبولی نہ ہو پائے۔ (صحیح ابن ماجہ، صحیح ترمذی، مسند احمد)\nاُوْلٰٓئِکَ یُسٰرِعُوْنَ فِی الْخَیْرٰتِ: جن لوگوں میں ذکر کردہ اعمال صالحہ موجود ہوں گے یہ لوگ اعمال صالحہ کی ادائیگی میں رغبت کریں گے ادائیگی میں جلدی کریں گے تاکہ ان کی ادائیگی سے محروم نہ ہو جائیں۔\nوَہُمْ لَھَا سٰبِقُوْنَ: یہ لوگ اطاعت کے کاموں میں ثواب کے حصول کے لیے سبقت لے جائیں گے مقصود یہ ہے کہ صدقات خیرات کا عمل بھی تب دونوں جہانوں کے لیے باعث سعادت ہوگا جب اس کے ساتھ اللہ تعالیٰ کا ڈر بھی شامل حال ہو۔\nوَ لَا نُكَلِّفُ نَفْسًا اِلَّا وُسْعَهَا وَ لَدَيْنَا كِتٰبٌ يَّنْطِقُ بِالْحَقِّ وَ هُمْ لَا يُظْلَمُوْنَ۰۰۶۲\nبَلْ قُلُوْبُهُمْ فِيْ غَمْرَةٍ مِّنْ هٰذَا وَ لَهُمْ اَعْمَالٌ مِّنْ دُوْنِ ذٰلِكَ هُمْ لَهَا\nعٰمِلُوْنَ۰۰۶۳ حَتّٰۤى اِذَاۤ اَخَذْنَا مُتْرَفِيْهِمْ بِالْعَذَابِ اِذَا هُمْ يَجْـَٔرُوْنَؕ۰۰۶۴ لَا\nتَجْـَٔرُوا الْيَوْمَ١۫ اِنَّكُمْ مِّنَّا لَا تُنْصَرُوْنَ۰۰۶۵ قَدْ كَانَتْ اٰيٰتِيْ تُتْلٰى عَلَيْكُمْ فَكُنْتُمْ\nعَلٰۤى اَعْقَابِكُمْ تَنْكِصُوْنَۙ۰۰۶۶ مُسْتَكْبِرِيْنَ۠١ۖۗ بِهٖ سٰمِرًا تَهْجُرُوْنَ۰۰۶۷\nاور ہم کسی نفس کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے، اور ہمارے پاس ایک ایسی کتاب (نامۂ اعمال) ہے جو (ہر شخص کا حال) ٹھیک ٹھیک بولے گی، اور ان پر ظلم نہیں کیا جائے گا; بلکہ ان (کفار) کے دل میں اس (قرآن) سے جہالت و غفلت میں ہیں، اور اس کے علاوہ بھی ان کے کئی (برے) اعمال ہیں، جنھیں وہ کرنے والے ہیں' حتی کہ جب ہم ان کے خوشحالی (عیاش) لوگوں کو عذاب میں پکڑیں گے تو اس وقت وہ چیخ پکار کریں گے (کہا جائے گا:) آج مت چیخو، یقیناً تم ہماری\nطرف سے مدد نہیں کیے جائو گے رحمہم اللہ تحقیق میری آیات تم پر تلاوت کی جاتی تھیں تو تم اپنی ایڑیوں کے بل پھر جاتے تھے\nتکبر کرتے ہوئے، (اور) اس کے بارے میں افسانہ خوانی کرتے ہوئے تم بیہودہ گوئی کرتے تھے"],[4602,"§اللہ تعالیٰ کا عدل اور مشرکین کی قلا بازیاں\nاللہ تعالیٰ نے بیان فرمایا ہے کہ اس نے دنیا میں اپنے بندوں کے لیے جو شریعت مقرر فرما رکھی ہے، وہ مبنی بر عدل ہے اور وہ کسی شخص پر اس کی طاقت سے زیادہ ذمہ داری کا بوجھ نہیں ڈالتا کہ جسے برداشت کرنے اور جس کے مطابق عمل کرنے کا اسے مقدور ہی نہ ہو، پھر وہ روز قیامت ان سب کے اعمال کا حساب لے گا۔ ان کے تمام اعمال کو بلا کم و کاست اس نے کتاب مسطور میں لکھ رکھا ہے، اسی لیے فرمایا: ﴿وَ لَدَيْنَا كِتٰبٌ يَّنْطِقُ بِالْحَقِّ﴾ ’’اور ہمارے پاس ایک ایسی کتاب (نامہ اعمال) ہے جو (ہر شخص کا حال) ٹھیک ٹھیک بولے گی۔‘‘ یعنی کتاب اعمال، ﴿وَ هُمْ لَا يُظْلَمُوْنَ۰۰۶۲﴾ ’’اور ان (لوگوں) پر ظلم نہیں کیا جائے گا۔‘‘ یعنی ان کی کسی نیکی کو کم نہیں کیا جائے گا، پھر اللہ تعالیٰ نے قریش کے کفار و مشرکین کی تردید کرتے ہوئے فرمایا: ﴿بَلْ قُلُوْبُهُمْ فِيْ غَمْرَةٍ﴾ ’’مگر ان کے دل غفلت میں (پڑے ہوئے) ہیں۔‘‘ اور ضلالت میں مبتلا ہیں ﴿مِّنْ هٰذَا﴾ ’’اس (قرآن) سے۔‘‘ یعنی اس قرآن کی طرف سے جسے اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم پر نازل فرمایا ہے۔ ﴿وَ لَهُمْ اَعْمَالٌ مِّنْ دُوْنِ ذٰلِكَ هُمْ لَهَا عٰمِلُوْنَ۰۰۶۳﴾ ’’اور اس (غفلت) کے علاوہ بھی ان کے کئی (برے) اعمال ہیں جنہیں وہ کرنے والے ہیں۔‘‘ حکم بن ابان رحمہ اللہ نے عکرمہ رحمہ اللہ سے اور انہوں نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ شرک کے سوا بھی ان کے کئی برے اعمال ہیں جنہیں یہ ضرور کرتے ہیں۔ (الدر المنثور : 23/5) مجاہد، حسن اور کچھ ائمہ تفسیر رحمہ اللہ سے بھی اسی طرح مروی ہے۔ (تفسیر الطبری : 48,47/18 و تفسیر القرطبی : 135,134/12) اور کچھ دیگر اہل علم نے کہا ہے کہ اس کے معنی یہ ہیں کہ کچھ دیگر برے اعمال بھی ان کے مقدر میں لکھ دیے گئے ہیں جنہیں اپنی موت سے پہلے یہ ضرور انجام دیں گے تاکہ عذاب کے مستحق قرار پا سکیں، مُقاتِل بن حیان، سُدِّی اور عبدالرحمٰن بن زید بن اسلم رحمہ اللہ سے بھی اسی طرح مروی ہے اور بظاہر اس کے معنی قوی اور حسن معلوم ہوتے ہیں۔\nہم نے قبل ازیں یہ حدیث ابن مسعود رضی اللہ عنہ بیان کی ہے: (دیکھیے: المومنون، آیات : 16,12) ((فَوَالَّذِیْ لَا اِلٰہَ غَیْرُہٗ! [وَاِنَّ الرَّجُلَ] لَیَعْمَلُ بِعَمَلِ اَھْلِ الْجَنَّۃِ، حَتّٰی مَا یَکُوْنُ بَیْنَہٗ وَبَیْنَھَا اِلَّا ذِرَاعٌ، فَیَسْبِقُ عَلَیْہِ الْکِتَابُ، فَیَعْمَلُ بِعَمَلِ اَھْلِ النَّارِ فَیَدْخُلُھَا)) ’’اس ذات اقدس کی قسم جس کے سوا کوئی معبود نہیں! ایک شخص اہل جنت کے سے عمل کرتا رہتا ہے حتیٰ کہ اس کے اور جنت کے درمیان صرف ایک ہاتھ کا فاصلہ رہ جاتا ہے مگر کتاب اس سے سبقت لے جاتی ہے اور وہ اہل دوزخ کا سا کوئی عمل کرکے جہنم میں داخل ہو جاتا ہے۔ (صحیح البخاری، حدیث: 6594 و صحیح مسلم، حدیث : 2643 واللفظ لہ)\nاللہ تبارک و تعالیٰ آگاہ فرماتا ہے کہ یہ جھٹلانے والے، اس بارے میں جہالت میں مبتلا ہیں یعنی جہالت، ظلم، غفلت اور روگردانی میں غلطاں ہیں یہ جہالت اور غفلت انہیں قرآن تک پہنچنے نہیں دیتی۔ پس یہ قرآن سے راہنمائی حاصل کرنے سے قاصر ہیں اور قرآن سے ان کے دلوں تک کچھ نہیں پہنچتا۔ فرمایا: ﴿وَ اِذَا قَرَاْتَ الْقُرْاٰنَ جَعَلْنَا بَيْنَكَ وَ بَيْنَ الَّذِيْنَ لَا يُؤْمِنُوْنَ بِالْاٰخِرَةِ حِجَابًا مَّسْتُوْرًاۙ۰۰۴۵وَ جَعَلْنَا عَلٰى قُلُوْبِهِمْ اَكِنَّةً اَنْ يَّفْقَهُوْهُ وَ فِيْۤ اٰذَانِهِمْ وَقْرًا١ؕ﴾ (بنی اسرائیل: 46,45) ’’جب آپ قرآن پڑھتے ہیں تو آپ کے درمیان اور ان لوگوں کے درمیان جو آخرت پر ایمان نہیں لاتے ہم ایک پردہ حائل کر دیتے ہیں اور دلوں پر غلاف چڑھا دیتے ہیں کہ وہ کچھ نہ سمجھیں اور ان کے کانوں میں گردانی ڈال دیتے ہیں۔‘‘ اور جب ان کے دل غفلت اور جہالت میں مستغرق ہیں تو وہ اپنے حسب حال کفریہ اور شریعت کے خلاف اعمال بجا لائیں گے جو ان کے لیے عذاب کے موجب ہیں۔\n﴿وَ لَهُمْ اَعْمَالٌ مِّنْ دُوْنِ ذٰلِكَ﴾ مگر ان کے علاوہ بھی ان کے برے اعمال ہیں ﴿هُمْ لَهَا عٰمِلُوْنَ۰۰۶۳﴾ ’’جنہیں وہ کرنے والے ہیں۔‘‘ یعنی وہ عذاب کے عدم وقوع پر تعجب نہ کریں کیونکہ اللہ تعالیٰ انہیں مہلت فراہم کر رہا ہے تاکہ وہ ان اعمال بد کا ارتکاب بھی کر لیں جو باقی رہ گئے ہیں اور جو ان کے لیے درج کیے گئے ہیں۔ جب وہ ان اعمال بد کا پوری طرح ارتکاب کر لیں گے تو وہ بدترین حالت کے ساتھ اللہ تعالیٰ کے غضب اور عذاب میں منتقل ہوں گے۔\n﴿مُسْتَكْبِرِيْنَ۠١ۖۗ بِهٖ سٰمِرًا تَهْجُرُوْنَ﴾ ’’تکبر کرتے ہوئے ساتھ اس کے افسانہ گوئی کرتے ہوئے تم بے ہودہ بکتے تھے۔‘‘ اصحاب تفسیر اس کا یہ معنی بیان کرتے ہیں کہ ﴿مُسْتَكْبِرِيْنَ۠١ۖۗ بِهٖ﴾ میں ضمیر بیت اللہ یا حرم کی طرف لوٹتی ہے، جو مخاطبین کے ہاں معہود (ذہن میں موجود) ہے یعنی تم حرم یا بیت اللہ کے سبب سے لوگوں کے ساتھ تکبر سے پیش آتے تھے اور کہتے تھے کہ ہم اہل حرم ہیں بنا بریں ہم دوسروں سے اعلیٰ و افضل ہیں۔ ﴿سٰمِرًا﴾ یعنی جماعت کی صورت میں رات کے وقت بیت اللہ کے گرد بیٹھ کر باتیں کرتے ﴿تَهْجُرُوْنَ۰۰۶۷﴾ یعنی تم اس قرآن عظیم کے بارے میں قبیح گفتگو کرتے تھے۔ پس قرآن کریم کے بارے میں اہل تکذیب کا طریقہ روگردانی پر مبنی تھا اور اسی طریقے کی وہ ایک دوسرے کو وصیت کیا کرتے تھے۔ ﴿وَ قَالَ الَّذِيْنَ كَفَرُوْا لَا تَسْمَعُوْا لِهٰذَا الْقُرْاٰنِ وَ الْغَوْا فِيْهِ لَعَلَّكُمْ تَغْلِبُوْنَ۰۰۲۶﴾ (حمٓ السجدۃ : 26) ’’وہ لوگ جنہوں نے کفر کیا کہتے ہیں کہ اس قرآن کو مت سنو، جب سنایا جائے تو شور مچا دیا کرو شاید کہ تم غالب رہو۔‘‘ اللہ تبارک و تعالیٰ نے ان کے بارے میں فرمایا: ﴿اََفَمِنْ هٰذَا الْحَدِيْثِ تَعْجَبُوْنَۙ۰۰۵۹ وَ تَضْحَكُوْنَ وَ لَا تَبْكُوْنَۙ۰۰۶۰ وَ اَنْتُمْ سٰمِدُوْنَ۰۰۶۱﴾ (النجم:61,59) ’’کیا تم اس کلام کے بارے میں تعجب کرتے ہو، ہنستے ہو اور روتے نہیں ہو اور تم غفلت میں پڑے ہوئے ہو۔‘‘ اور فرمایا: ﴿اَمْ يَقُوْلُوْنَ تَقَوَّلَهٗ١ۚ﴾ (الطور : 33) ’’کیا کفار یہ کہتے ہیں کہ آپ نے یہ قرآن خود گھڑ لیا ہے؟‘‘\nوہ ان رذائل کے جامع تھے اور اس میں کوئی شک نہیں کہ ان پر عذاب واجب ہو گیا اور جب یہ عذاب واقع ہو گیا تو ان کا کوئی حامی بنا جو ان کی مدد کر سکے نہ فریاد رس بنا ہوگا جو ان کو اس عذاب سے بچا سکے اس وقت ان کے اعمال بد کی بنا پر ان کو زجر و توبیخ کی گئی۔"],[4603,"§تکلیف کا مفہوم، شرعی احکام کی حکمت اور ہر شخص کی استعداد کا لحاظ\nیعنی ہم نے احکام شریعت ایسے نازل نہیں کیے جو انسان کی بساط سے باہر ہوں۔ شرعی احکام میں مصلحت کے جس پہلو کو ملحوظ رکھا گیا ہے وہ یہ ہے کہ شرعی احکام بالعموم مسلمانوں کی اکثریت کے لیے اور نارمل حالات میں قابل عمل ہوتے ہیں۔ جب حالات بدل جائیں تو احکام میں بھی تھوڑی بہت تبدیلی کر دی جاتی ہے پھر چونکہ یہ احکام ایک عام انسان کی استعداد یاقوتِ کار کو ملحوظ رکھ کر دیے جاتے ہیں۔ لہٰذا عام استعداد سے کم استعداد رکھنے والوں مثلاً بیماروں یا معذوروں کے لیے رخصت یا رعایت دی جاتی ہے۔ حتیٰ کہ نابالغ، مجنون وغیرہ سے شرعی احکام ویسے ہی ساقط کر دیے گئے ہیں۔ پھر معاشرہ میں کچھ ایسے افراد بھی ہوتے ہیں جو ایک عام انسان کی استعداد سے زیادہ استعداد رکھتے ہیں۔ ایسے لوگوں کے لیے وسیع میدان عمل کو سامنے لا کر اس حکم کی زیادہ سے زیادہ بجا آوری کی ترغیب دی جاتی ہے۔ مثلاً ہر عاقل و بالغ مسلمان کو پانچ وقت نماز با جماعت ادا کرنے کا حکم ہے اور نماز سے پہلے وضو یا طہارت بھی ضروری ہے تو حالات کے مطابق مراعات تو یہ ہیں کہ جسے وقت پر وضو کے لیے پانی دستیاب نہ ہو وہ تیمم کر سکتا ہے۔ بیمار کو اگر وضو کرنے سے بیماری بڑھنے یا کسی اور تکلیف کا خطرہ ہو تو وہ بھی تیمم کر سکتا ہے۔ سفر یا خوف کی حالت میں نماز قصر بھی کر سکتا ہے اور دو نمازیں اکٹھی بھی پڑھ سکتا ہے، نیز سفر کی حالت میں سواری پر بھی نماز ادا کر سکتا ہے۔ نیز اگر قبلہ یا صحیح وقت کی تعیین میں دقت ہو تو اندازہ سے کام لے سکتا ہے۔ بارش یا کسی اور معقول عذر کی وجہ سے مسجد نہیں جا سکتا تو گھر پر نماز ادا کر سکتا ہے اور کم استعداد والوں کی مثال یوں سمجھیے کہ بیمار بیٹھ کر نماز پڑھ سکتا ہے اگر زیادہ بیمار ہے تو لیٹے لیٹے ہی پڑھ سکتا ہے۔ اتنی بھی ہمت نہ رہی ہو تو اشارہ سے بھی ادا کر سکتا ہے۔ ایسا بیمار یا انتہائی بوڑھا جو مسجد تک جانے کی ہمت نہیں رکھتا۔ مستقل طور پر اپنے گھر میں نماز ادا کر سکتا ہے۔ یہی اس جملہ کا مطلب ہے کہ ’’ہم کسی شخص کو اس کے مقدور سے زیادہ تکلیف نہیں دیتے‘‘ اتنی مراعات کے باوجود پھر بھی کوئی شخص عمداً نماز ادا نہیں کرتا تو وہ کافر ہو جائے گا اور اگر نماز کی بجا آوری میں کوتاہی کرتا ہے تو گناہ کبیرہ کا مرتکب ہوگا۔\nاور جو لوگ زیادہ استعداد رکھتے ہیں ان کے لیے فرضی نماز کے علاوہ نوافل تجویز کیے گئے ہیں۔ مثلاً ظہر کی نماز کی فرض رکعات صرف چار ہیں۔ ان چار رکعات پر رسول اللہ صلی اللہ علیہ وسلم نے تطوعاً جو اضافہ کیا وہ ہمارے لیے سنت ہیں اور وہ چار رکعات فرض نماز سے پہلے ہیں اور دو بعد میں۔ پھر ان فرض اور سنت رکعات پر تطوعاً آخر میں مزید رکعات کا اضافہ ہوا جسے نفل کہتے ہیں اور ان پر مزید نوافل کا اضافہ بھی کیا جا سکتا ہے۔ پھر کچھ نمازیں ایسی ہیں جو فرض کفایہ ہیں جیسے نماز جمعہ اور نماز جنازہ وغیرہ اور کچھ سنت ہیں جیسے تہجد کی نماز جو آپ صلی اللہ علیہ وسلم پر تو فرض تھی مگر امت کے لیے سنت موکدہ ہے یا نماز تراویح اور کچھ نمازیں ہی نفلی ہیں مثلاً نماز چاشت، اوابین اور شکرانہ کے نوافل اور کچھ نفل نمازیں حالات سے متعلق ہیں۔ جیسے نماز استسقاء، نماز کسوف اور خسوف وغیرہ یہ ہے وہ وسیع میدان جو ترقی درجات کا سبب بنتا ہے۔ پھر ایک نماز ہی کی یہ صورت نہیں۔ صدقات و خیرات بلکہ ہر رکن اسلام اور عمل صالح کی یہی صورت ہے کہ اس میں تطوعات کا وسیع میدان موجود ہے یہی وہ میدان ہے جس کے متعلق اللہ تعالیٰ نے فرمایا: ﴿یُسَارِعُوْنَ فِی الْخَیْرٰتِ وَہُمْ لَھَا سَابِقُوْنَ﴾ اور اس کا دوسرا مطلب یہ بھی ہو سکتا ہے کہ بھلے کاموں میں ایک دوسرے سے آگے نکل جانے کی کوشش کرنا کوئی ایسی بات نہیں جو انسان کی بساط سے باہر ہو۔ کم از کم ہر انسان کو ایسا کرنے کی کوشش ضرور کرنا چاہیے۔"],[4604,"§اعمال کے اندراج کا طریق کار\nیعنی ہر انسان کے اعمال، افعال، اقوال حتیٰ کہ دل کے خیالات اور دل میں پیدا ہونے والے وساوس اور ارادے بھی ساتھ کے ساتھ ریکارڈ ہو رہے ہیں۔ قرآن کی تصریح کے مطابق یہ قلم بند کرنے والے دو معزز فرشتے ہوتے ہیں ایک انسان کے دائیں طرف، دوسرا بائیں طرف، پھر ان کی ڈیوٹیاں بھی فجر اور عصر کے وقت بدلتی رہتی ہیں موجودہ دور کی سائنسی ایجادات نے اس حقیقت کو بہت حد تک قریب الفہم بنا دیا ہے کہ یہ باتیں از خود کس طرح ریکارڈ میں آ جاتی ہیں۔ گویا ہر شخص کی زندگی کی مکمل ہسٹری شیٹ اللہ کے ہاں موجود رہتی ہیں اور اس کی خصوصیت یہ ہے کہ اس میں نہ تو کوئی چھوٹی سے چھوٹی بات قلم بند ہونے سے رہ جاتی ہے اور نہ ہی اس میں کوئی غلط اندراج ہو سکتا ہے۔"],[4605,"§سمر کا لغوی مفہوم\nسمر کے معنی وقت سونے سے پیشتر ایک دوسرے سے قصے کہانیاں بیان کرنا۔ تاکہ ان قصے کہانیوں میں محو ہو کر نیند آ جائے۔ یہ قصے یا افسانے یا کہانیاں محض دفع الوقتی یا خوش وقتی کے لیے سنے سنائے جاتے ہیں۔ ان کا اور کچھ مقصد نہیں ہوتا۔ دیہاتوں میں آج بھی یہ دستور ہے کہ بڑے لوگ چھوٹوں کو کوئی بھوت پریت یا ایسی ہی دوسری کہانیاں سناتے ہیں اور مکہ میں بھی یہی دستور تھا اور ہجر کے معنی بیماری، نیم بے ہوشی یا نیم خفتگی کی حالت میں مہمل سی باتیں کرنا یا بڑ بڑانا۔ گویا مترفین یا ان عیاش لوگوں کا جرم یہ تھا کہ اللہ کی آیات کو سننا بھی گوارا نہ کرتے تھے اور از راہ تکبر منہ موڑتے ہوئے واپس چلے جاتے تھے۔ مزید برآں ایک دوسرے سے اگر آیاتِ الٰہی کا ذکر کرتے بھی تو انتہائی بے نیازی اور لا پروائی سے جیسے کوئی مہمل سی باتیں یا قصے کہانیاں سنا رہا ہو۔ ان کے ان جرائم کی سزا یہی ہے کہ اب ان کے چھٹکارا کی سب راہیں بند کر دی جائیں اور ان کی آہ و فغاں پر کچھ توجہ نہ دی جائے۔\nوَلَا نُکَلِّفُ نَفْسًا اِلَّا وُسْعَھَا: یہ ہماری سنت ہے کہ ہم کسی شخص کو اس کی طاقت سے زیادہ تکلیف میں مبتلا نہیں کرتے ہیں جیسا کہ جو شخص نماز میں قیام نہیں کر سکتا وہ بیٹھ کر نماز ادا کرے اور جو شخص بیٹھ کر بھی اس فریضہ کو سر انجام نہیں دے سکتا تو وہ اشارے کے ساتھ ادا کرے اور ہمارے پاس لوگوں کے اعمال نامے ہیں محاسبہ کے وقت وہ ان کی تلاوت کریں گے اور جزاء سزا کے عمل میں کسی پر ظلم نہ ہوگا نہ ثواب میں کمی ہو گی نہ عذاب میں اضافہ ہوگا عدل و انصاف کے ساتھ نظام جاری ہوگا۔\nبلکہ کفار کے دل پردے، غفلت اور قرآن کی ہدایت سے دور اندھیرے میں ہیں کفر اور شرک کے علاوہ بھی ان میں کثرت کے ساتھ برے اعمال ہیں مستقبل میں بھی وہ اسی انداز پر بد اعمالیوں کے مرتکب رہیں گے اس وجہ سے ان پر عذاب کا اترنا متحقق ہوگا یہاں تک کہ جب ہم ان میں سے صاحب ثروت اور معاشرہ میں مال و دولت کے باعث جو عیش و آرام کی زندگی بسر کر رہے ہیں ان پر نہایت تیزی کے ساتھ جلد ہی بھوک، قتل اور دشمن کے ہاتھوں میں گرفتار کرا دیتے ہیں تو اس وقت وہ چیخنے لگ جاتے ہیں اور اونچی آواز کرتے ہوئے کسی مددگار کو پکارتے ہیں جیسا کہ کفار آپ کے دور میں سات سال تک قحط سالی کی زد میں رہے تو اللہ تعالیٰ نے انہیں ڈانٹ پلاتے ہوئے کہا تم اب عذاب سے چھٹکارا حاصل کرنے کی اپیل نہ کرو اب ضروری ہے کہ تم ہمارے عذاب سے تحفظ حاصل نہ کر سکو گے اب چیخنے چلانے سے تمہیں کچھ فائدہ حاصل نہ ہوگا۔\nیہ حقیقت ہے کہ تم پر قرآن پاک کی آیات کی تلاوت ہوتی رہی اور تم سنتے رہے لیکن تم نے آیات سے روگردانی کی اور تمہاری کیفیت تو اس شخص کی سی تھی جو انکار کرتے ہوئے اپنی ایڑیوں پر واپس پھر جاتا ہے اس میں استعارہ تمثیلیہ ہے مشرکین نے جب قرآن پاک کے سننے سے روگردانی کی تو گویا کہ وہ اپنی ایڑیوں پر رجعت قہقریٰ کے مرتکب ہوئے تاکہ قرآن پاک کی آواز ان کے کانوں میں پہنچنے نہ پائے انہوں نے قرآن پاک کی تصدیق سے کبر و نخوت کی کیفیت میں روگردانی کی۔\nعلامہ ابن کثیر رحمہ اللہ نے مزید وضاحت کرتے ہوئے اس حقیقت کا اظہار کیا ہے کہ وہ لوگ رات کے لمحات میں جب آپس میں کہانیاں بیان کرتے تو قرآن پاک کے ملحوظات کو فحش کلام قرار دیتے تھے اس کو شعر کے قبیل سے بتاتے اور جادو کا کرشمہ اور کہانت کا الزام لگاتے اور سابقہ اقوام کی کہانیوں کا مجموعہ بھی کہا کرتے تھے جبکہ ابن جوزی رحمہ اللہ نے مجرور ضمیر کا مرجع بیت الحرام قرار دیا ہے حالانکہ بیت الحرام کا تذکرہ اس سے پہلے نہیں ہے لیکن بیت الحرام کی شہرت ہی کافی ہے اس عدم ذکر سے ہرگز کچھ قباحت نہیں ہے، مقصود یہ ہے کہ تم بیت الحرام کے قرب و جوار میں بیٹھ کر فخر کر رہے ہو اور تکبر کرنے سے باز نہیں آرہے ہو تم فخر کرتے ہوئے کتہے ہو ہم تو حرم والے ہیں اللہ کے گھر کے متولی اور خادم ہیں اور ہم ہرگز کسی سے ڈرتے نہیں ہیں تم اپنی مجالس میں رات کے وقت فحش گفتگو کرتے ہو قرآن پاک کے خلاف تمہاری زبانیں مذموم الفاظ نکالنے سے رکتی نہیں ہیں بلکہ تم آخر الزمان پیغمبر محمد صلی اللہ علیہ وسلم کو دیوانہ، کاہن، جادوگر، افسانہ نویس اور شاعر قرار دیتے ہو، حقیقت یہ ہے کہ یہ لوگ قرآن پاک کے معانی میں غور و فکر نہیں کرتے ہیں تاکہ انہیں معلوم ہو کہ یہ قرآن تو واقعی اللہ تعالیٰ کا کلام ہے جب اس کی حیران کن ترتیب بار بار ہر اس شخص کو دعوت دیتی ہے جو قرآن پاک کے نظم و ترتیب پر غور کرے گا تو وہ مجبور ہو کر اعلان کرے گا کہ یہ تو اللہ کا کلام ہے اور ایسا عجیب کلام ہے کہ اس جیسا کلام اس سے پہلے نہیں آیا، علامہ ابو السعود کا قول ہے کہ اللہ تعالیٰ کی جانب سے پیغمبروں پر مقدس کتابوں کا نزول ہوتا رہا یہ اللہ تعالیٰ کا بہت قدیمی انداز ہے اس سے انکار نہیں ہو سکتا اور آخر الزمان پیغمبر پر قرآن پاک کا نازل ہونا بھی پہلی کتب کی طرح ہے اس کا انکار بھی کیسے کیا جا سکتا ہے؟\nاَفَلَمْ يَدَّبَّرُوا الْقَوْلَ اَمْ جَآءَهُمْ مَّا لَمْ يَاْتِ اٰبَآءَهُمُ الْاَوَّلِيْنَٞ۰۰۶۸ اَمْ لَمْ\nيَعْرِفُوْا رَسُوْلَهُمْ فَهُمْ لَهٗ مُنْكِرُوْنَٞ۰۰۶۹ اَمْ يَقُوْلُوْنَ بِهٖ جِنَّةٌ١ؕ بَلْ جَآءَهُمْ\nبِالْحَقِّ وَ اَكْثَرُهُمْ لِلْحَقِّ كٰرِهُوْنَ۰۰۷۰ وَ لَوِ اتَّبَعَ الْحَقُّ اَهْوَآءَهُمْ لَفَسَدَتِ\nالسَّمٰوٰتُ وَ الْاَرْضُ وَ مَنْ فِيْهِنَّ١ؕ بَلْ اَتَيْنٰهُمْ بِذِكْرِهِمْ فَهُمْ عَنْ ذِكْرِهِمْ\nمُّعْرِضُوْنَؕ۰۰۷۱ اَمْ تَسْـَٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ١ۖۗ وَّ هُوَ خَيْرُ الرّٰزِقِيْنَ۰۰۷۲\nوَاِنَّكَ لَتَدْعُوْهُمْ اِلٰى صِرَاطٍ مُّسْتَقِيْمٍ۰۰۷۳ وَ اِنَّ الَّذِيْنَ لَا يُؤْمِنُوْنَ بِالْاٰخِرَةِ\nعَنِ الصِّرَاطِ لَنٰكِبُوْنَ۰۰۷۴ وَ لَوْ رَحِمْنٰهُمْ وَ كَشَفْنَا مَا بِهِمْ مِّنْ ضُرٍّ لَّلَجُّوْا فِيْ\nطُغْيَانِهِمْ يَعْمَهُوْنَ۰۰۷۵\nکیا پھر انھوں نے قرآن میں تدبر نہیں کیا، یا پھر ان کے پاس وہ چیز آ گئی جو ان کے پہلے باپ دادا کے پاس نہیں آئی تھی؟ یا انھوں نے اپنے رسول کو نہیں پہچانا، لہٰذا وہ اس کے منکر ہیں یا وہ کہتے ہیں کہ اسے جنون ہے؟ (نہیں نہیں) بلکہ وہ ان کے پاس حق لایا ہے، اور ان کے اکثر لوگ حق کو نا پسند کرتے ہیں اور اگر حق ان کی خواہشات کی پیروی کرے تو آسمان اور زمین اور جو ان میں ہیں، سب تباہ و برباد ہو جائیں بلکہ ہم ان کے پاس ان کے لیے نصیحت لائے ہیں اور وہ اپنی ہی نصیحت سے اعراض کر رہے ہیں کیا آپ ان سے اجرت کا سوال کرتے ہیں، چنانچہ آپ کے رب کی اجرت زیادہ بہتر ہے اور وہ بہترین رزق دینے والا ہے اور بلاشبہ آپ انھیں صراط مستقیم (اسلام) کی طرف بلاتے ہیں: اور بلاشبہ جو لوگ جو آخرت پر ایمان نہیں لاتے وہ یقیناً صراط مستقیم سے ہٹ رہے ہیں\" اور اگر ان پر رحم کریں اور انھیں لاحق تکلیفیں دور کر دیں تو پھر بھی وہ برابر\nاپنی سر کشی پر بھٹکتے ہوئے اڑئے رہیں"],[4606,"§مشرکین کی تردید اور مذمت\nاللہ تعالیٰ نے قرآن عظیم کے نہ سمجھنے، اس پر تدبر نہ کرنے اور اس سے اعراض کرنے کی وجہ سے مشرکین کی تردید فرمائی ہے کیونکہ اس کتاب کو اللہ تعالیٰ نے بطور خاص انہی لوگوں کی ہدایت کے لیے نازل فرمایا تھا، پھر اس سے بڑھ کر اکمل اور اشرف کتاب کسی اور رسول پر نازل نہیں کی گئی، خصوصاً ان کے وہ آباء و اجداد جو زمانہ جاہلیت میں مرگئے تھے، انہیں اس طرح کی کوئی کتاب نہیں پہنچی اور نہ ان کے پاس اللہ عذاب سے ڈرانے والا ہی کوئی آیا تھا، لہٰذا ان لوگوں کو چاہیے تھا کہ وہ اللہ تعالیٰ کی اس نعمت کو قبول کرتے جس سے اس نے انہیں نوازا تھا، اس کا شکر ادا کرتے، اسے سمجھنے کی کوشش کرتے اور اپنی زندگی کے دن اور راتیں، صبحیں اور شامیں اس کتاب کے تقاضوں کے مطابق عمل کرتے ہوئے گزارتے جیسا کہ ان میں سے ان نجباء نے کیا جو مشرف بہ اسلام ہو گئے تھے اور جنہوں نے رسول اللہ صلی اللہ علیہ وسلم کی اتباع و اطاعت کو اختیار کر لیا تھا۔\n﴿اَفَلَمْ يَدَّبَّرُوا الْقَوْلَ﴾ ’’کیا پھر انہوں نے کلام (قرآن) میں غور نہیں کیا؟‘‘ امام قتادہ رحمہ اللہ فرماتے ہیں کہ یہ لوگ قرآن میں غور کرتے تو واللہ! اس میں ایسی چیزیں پاتے جو انہیں اللہ تعالیٰ کی نا فرمانی سے روکتیں لیکن یہ تو متشابہات کے پیچھے لگ گئے جس کی وجہ سے تباہ و برباد ہو گئے۔ (الدر المنثور : 25/5) پھر اللہ تعالیٰ نے کفار قریش کی تردید کرتے ہوئے فرمایا ہے: ﴿اَمْ لَمْ يَعْرِفُوْا رَسُوْلَهُمْ فَهُمْ لَهٗ مُنْكِرُوْنَٞ۰۰۶۹﴾ ’’یا انہوں نے اپنے پیغمبر کو نہیں پہچانا؟ سو وہ اس کے منکر ہیں؟‘‘ کیا یہ لوگ محمد صلی اللہ علیہ وسلم اور آپ کی صداقت و امانت اور اس پاک بازی و عفت مآبی کو نہیں جانتے؟ جس میں ان کے سامنے آپ نے نشات و ارتقا کی منزلیں طے فرمائی ہیں کیا یہ لوگ ان باتوں کا انکار کر سکتے ہیں؟ جعفر بن ابو طالب رضی اللہ عنہ نے شاہ حبشہ نجاشی سے کہا تھا: اے بادشاہ! بے شک اللہ تعالیٰ نے ہماری طرف ایک ایسے رسول کو مبعوث فرمایا ہے جن کے نسب اور جن کی صداقت و امانت کو ہم خوب جانتے ہیں۔ (مسند احمد وصحیح ابن خزیمۃ: 13/4 والسیرۃ النبویۃ لابن ہشام، ارسال قریش الی الحبشۃ فی طلب المہاجرین الیہا…: 336,335/1) اسی طرح مغیرہ بن شعبہ رحمہ اللہ نے نائب کسریٰ سے بھی اس وقت یہی بات کہی تھی، جب اس نے آپ لوگوں کو طلب کیا تھا۔ اسی طرح ابو سفیان صخر بن حرب رحمہ اللہ نے شاہِ روم ہرقل سے بھی کہا تھا جب اس نے ابوسفیان اور اس کے ساتھیوں سے نبی صلی اللہ علیہ وسلم کی صفات، نسب، صداقت اور امانت کے بارے میں پوچھا تھا اور اس وقت ابوسفیان اور اس کے ساتھی دائرہ اسلام میں داخل نہیں ہوئے تھے لیکن اس کے باوجود انہیں آپ کی صداقت و امانت کا اعتراف کرنا پڑا اور اس کے بغیر ان کے لیے کوئی چارہ کار ہی نہ تھا۔"],[4607,"§حق خواہشوں کے پیچھے نہیں چلتا\nارشاد باری تعالیٰ ہے: ﴿وَ لَوِ اتَّبَعَ الْحَقُّ اَهْوَآءَهُمْ لَفَسَدَتِ السَّمٰوٰتُ وَ الْاَرْضُ وَ مَنْ فِيْهِنَّ١ؕ﴾ ’’اور اگر حق ان کی خواہشوں کی پیروی کرے تو آسمان اور زمینا ور جو ان میں ہیں سب درہم برہم ہو جائیں۔‘‘ مجاہد، ابو صالح اور سُدّی رحمہ اللہ نے کہا ہے کہ حق سے مراد اللہ عزوجل کی ذات گرامی ہے۔ (تفسیر الطبری : 56/18 وتفسیر القرطبی : 140/2) مراد یہ ہے کہ اگر اللہ تعالیٰ ان کے نفسوں کی خواہشوں کے پیچھے چلے اور ان کی خواہشوں کے مطابق احکام شریعت نازل فرمائے تو آسمان و زمینا ور جو ان میں ہیں وہ سب ان کی خراب خواہشوں کی وجہ سے درہم برہم ہو جائیں جیسا کہ اللہ تعالیٰ نے بیان فرمایا ہے کہ انہوں نے بھی کہا تھا: ﴿لَوْ لَا نُزِّلَ هٰذَا الْقُرْاٰنُ عَلٰى رَجُلٍ مِّنَ الْقَرْيَتَيْنِ عَظِيْمٍ۰۰۳۱﴾ (الزخرف: 31) ’’یہ قرآن ان دونوں بستیوں میں سے کسی بڑے آدمی پر نازل کیوں نہیں کیا گیا؟‘‘ پھر اللہ تعالیٰ نے جواب میں فرمایا: ﴿اَهُمْ يَقْسِمُوْنَ رَحْمَتَ رَبِّكَ١ؕ﴾ (الزخرف: 32) ’’کیا وہ (لوگ) آپ کے پروردگار کی رحمت کو بانٹتے ہیں؟‘‘ اللہ تعالیٰ نے ان کے بارے میں فرمایا ہے: ﴿قُلْ لَّوْ اَنْتُمْ تَمْلِكُوْنَ خَزَآىِٕنَ رَحْمَةِ رَبِّيْۤ اِذًا لَّاَمْسَكْتُمْ خَشْيَةَ الْاِنْفَاقِ١ؕ وَ كَانَ الْاِنْسَانُ قَتُوْرًاؒ۰۰۱۰۰﴾ (بنی اسرائیل: 100) ’’کہہ دیجئے: اگر تم میرے پروردگار کی رحمت کے خزانوں کے مالک ہوتے تو اس وقت تم انہیں خرچ ہو جانے کے خوف سے بند کر رکھتے اور انسان نہایت بخیل ہے۔‘‘ اور فرمایا: ﴿اَمْ لَهُمْ نَصِيْبٌ مِّنَ الْمُلْكِ فَاِذًا لَّا يُؤْتُوْنَ النَّاسَ نَقِيْرًاۙ۰۰۵۳﴾ (النسآئ: 53) ’’کیا (وہ سمجھتے ہیں کہ) ان کے پاس بادشاہی کا کچھ حصہ ہے، پھر تو وہ اس میں سے لوگوں کو (کھجور کی گٹھلی کے) دھاگے برابر بھی نہ دیں گے۔‘‘ ان سب آیات سے بندوں کا عجز اور ان کی آراء و خواہشات کا مختلف ہونا واضح ہوتا ہے جبکہ اللہ رب ذوالجلال کی ذات پاک اپنی تمام صفات میں، اپنے تمام اقوال و افعال میں اور مخلوق کے لیے اپنی شریعت و تقدیر و تدبیر میں کامل ہے، وہ ہر عیب و نقص سے پاک ہے، اس کے سوا کوئی معبود ہے اور نہ کوئی پروردگار، پھر فرمایا: ﴿بَلْ اَتَيْنٰهُمْ بِذِكْرِهِمْ﴾ ’’بلکہ ہم ان کے پاس ان کی نصیحت (کی کتاب) لائے ہیں۔‘‘ یعنی قرآن مجید: ﴿فَهُمْ عَنْ ذِكْرِهِمْ مُّعْرِضُوْنَ﴾ ’’وہ اپنی ہی (کتاب) نصیحت سے اعراض کر رہے ہیں۔‘‘"],[4608,"§نبی اجرت کا طلب گار نہیں ہوتا\n﴿اَمْ تَسْـَٔلُهُمْ خَرْجًا﴾ ’’کیا آپ ان سے اجرت کا سوال کرتے ہیں؟‘‘ حسن رحمہ اللہ فرماتے ہیں کہ ﴿خَرْجًا﴾ کے معنی اجرت کے ہیں۔ (تفسیر الطبری : 57/18) اور قتادہ رحمہ اللہ فرماتے ہیں کہ اس کے معنی مال کے ہیں۔ (الدر المنثور: 25/5) ﴿فَخَرَاجُ رَبِّكَ خَيْرٌ١ۖۗ﴾ ’’تو آپ کے پروردگار کا صلہ بہت اچھا ہے۔‘‘ یعنی ہدایت کی طرف دعوت دینے پر آپ ان سے اجرت، مال یا کچھ بھی نہیں مانگتے بلکہ اس سلسلے میں اللہ تعالیٰ کے بے پایاں اجر و ثواب کے امیدوار ہیں جیسا کہ فرمایا: ﴿قُلْ مَا سَاَلْتُكُمْ مِّنْ اَجْرٍ فَهُوَ لَكُمْ١ؕ اِنْ اَجْرِيَ اِلَّا عَلَى اللّٰهِ١ۚ﴾ (سبا : 47) ’’کہہ دیجئے: میں نے تم سے جو کچھ صلہ مانگا ہو تو وہ تمہاےر ہی لیے ہے، میرا صلہ تو اللہ ہی کے ذمے ہے۔‘‘ اور فرمایا: ﴿قُلْ مَاۤ اَسْـَٔلُكُمْ عَلَيْهِ مِنْ اَجْرٍ وَّ مَاۤ اَنَا مِنَ الْمُتَكَلِّفِيْنَ۰۰۸۶﴾ (صٓ : 86) ’’آپ کہہ دیں: میں تم سے اس کا صلہ نہیں مانگتا اور میں تکلف کرنے والوں میں سے نہیں ہوں۔‘‘ اور فرمایا: ﴿قُلْ لَّاۤ اَسْـَٔلُكُمْ عَلَيْهِ اَجْرًا اِلَّا الْمَوَدَّةَ فِي الْقُرْبٰى ١ؕ﴾ (الشوریٰ : 23) ’’کہہ دیں کہ میں اس کا تم سے صلہ نہیں مانگتا مگر محبت کا قرابت داری کی وجہ سے۔‘‘ اور فرمایا: ﴿وَ جَآءَ مِنْ اَقْصَا الْمَدِيْنَةِ رَجُلٌ يَّسْعٰى قَالَ يٰقَوْمِ اتَّبِعُوا الْمُرْسَلِيْنَۙ۰۰۲۰ اتَّبِعُوْا مَنْ لَّا يَسْـَٔلُكُمْ اَجْرًا﴾ (یٰسٓ: 21,20) ’’اور شہر کے پرلے کنارے سے ایک آدمی دوڑتا ہوا آیا، کہنے لگا: اے میری قوم! پیغمبروں کے پیچھے چلو۔ تم ان کی پیروی کر وجو تم سے صلہ نہیں مانگتے۔‘‘ اور فرمایا: ﴿وَ اِنَّكَ لَتَدْعُوْهُمْ اِلٰى صِرَاطٍ مُّسْتَقِيْمٍ۰۰۷۳ وَ اِنَّ الَّذِيْنَ لَا يُؤْمِنُوْنَ بِالْاٰخِرَةِ عَنِ الصِّرَاطِ لَنٰكِبُوْنَ۰۰۷۴﴾ ’’اور بے شک آپ تو ان کو سیدھے رستے کی طرف بلاتے ہیں، اور جو لوگ آخرت پر ایمان نہیں لاتے وہ (سیدھے) رستے سے الگ ہو رہے ہیں۔‘‘\nامام احمد نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ: ((اَنَّ رَسُوْلَ اللہِ اَتَاہُ فِیْمَا یَرَی النَّائِمُ مَلَکَانِ، فَقَعَدَ اَحَدُھُمَا عِنْدَ رِجْلَیْہِ، وَالْآخَرُ عِنْدَ رَاْسِہٖ، فَقَالَ الَّذِیْ عِنْدَ رِجْلَیْہِ لِلَّذِی عِنْدَ رَاْسِہٖ: اِضْرِبْ مَثَلَ ہٰذَا وَمَثَلَ اُمَّتِہٖ، فَقَالَ: اِنَّ مَثَلَہٗ وَمَثَلَ اُمَّتِہٖ کَمَثَلِ قَوْمٍ سَفْرٍ، اِنْتَھَوْا اِلٰی رَاْسِ مَفَازَۃٍ، فَلَمْ یَکُنْ مَّعَہُمْ مِّنَ الزَّادِ مَا یَقْطَعُوْنَ بِہِ القمَفَازَۃَ، وَلَا مَا یَرْجِعُوْنَ بِہٖ، فَبَیْنَمَا ہُمْ کَذٰلِکَ، اِذْ اَتَاہُمْ رَجُلٌ فِی حُلَّۃٍ حِبَرَۃٍ، فَقَالَ: اَرَاَئْتُمْ اِنْ وَرَدْتُّ بِکُمْ رِیَاضًا مُّعْشِبَۃً، وَّحِیَاضًا رُّوَائً، اَتَتَّبِعُوْنِی؟ فَقَالُوْا: نَعَمْ، قَالَ: فَانْطَلَقَ بِھِمْ، فَاَوْرَدَہُمْ رِیَاضًا مُّعْشِبَۃً، وَّحِیَاضًا رُّوَائً، فَاَکَلُوْا وَشَرِبُوا وَسَمِنُوْا، فَقَالَ لَہُمْ: اَلَمْ اَلْقَکُمْ عَلٰی تِلْکَ الْحَالِ، فَجَعَلْتُمْ لِی اِنْ وَرَدْتُّ بِکُمْ رِیَاضًا مُّعْشِبَۃً، وَّحِیَاضًا رُّوَائً، اَتَتَّبِعُوْنِی؟ فَقَالُوْا: بَلٰی! قَالَ: فَاِنَّ بَیْنَ اَیْدِیْکُمْ رِیَاضًا اَعْشَبَ مِنْ ہٰذِہٖ، وَحِیَاضًا ہِیَ اَرْوٰی مِنْ ہٰذِہٖ، فَاتَّبِعُوْنِی قَالَ: فَقَالَتق طَائِفَۃٌ: صَدَقَ وَاللہِ! لَنَتَّبِعَنَّہٗ، وَقَالَتْ طَائِفَۃٌ: قَدق رَضِیْنَا بِہٰذَا نُقِیْمُ عَلَیْہِ)) ’’رسول اللہ صلی اللہ علیہ وسلم کے پاس خواب میں دو فرشتے آئے، ان میں سے ایک آپ کے دونوں پائوں کے پاس بیٹھ گیا اور دوسرا آپ کے سر مبارک کے پاس۔ جو پائوں کے پاس تھا اس نے سر کے پاس والے فرشتے سے کہا کہ آپ صلی اللہ علیہ وسلم کی اور آپ کی امت کی مثال بیان کرو۔ اس نے کہا کہ آپ کی اور آپ کی امت کی مثال ایسے ہے جیسے کچھ لوگ سفر میں ہوں اور وہ ایک جنگل کے کنارے پہنچ گئے ہوں، ان کے پاس نہ اس قدر زاد راہ ہو جس سے اس جنگل کو طے کر لیں اور نہ اتنا زاد راہ کہ وہ اس سے واپس جا سکیں۔ وہ اسی شش و پنج میں تھے کہ ان کے پاس دھاری دار حُلہ زیب تن کیے ایک شخص آیا اور اس نے کہا: یہ بتائو کہ اگر میں تمہیں سر سبز و شاداب باغات اور پانی سے لبریز حوضوں کے پاس لے چلوں تو کیا تم میرے پیچھے آئو گے۔ انہوں نے کہا: ہاں، تو وہ انہیں لے کر سر سبز و شاداب باغات اور پانی سے لبریز حوضوں کے پاس لے گیا، انہوں نے کھایا، پیا اور خوب فربہ ہو گئے تو اس نے ان سے کہا: کیا میں نے تم کو اس حال میں نہیں پایا تھا اور تم نے اس شرط پر میری پیروی کی تھی کہ میں تم کو سر سبز و شاداب باغات اور پانی سے بھرے حوضوں کی طرف لے جائوں گا۔ لوگوں نے کہا: ہاں، تو انہوں نے فرمایا کہ تمہارے آگے ان سے بھی کہیں زیادہ سر سبز و شاداب اور پر بہار باغات اور ان سے زیادہ سیراب کر دینے والے حوض ہیں، لہٰذا میری بات مانو۔ کچھ لوگوں نے تو یہ کہا: واللہ! یہ بالکل سچ فرما رہے ہیں، ہم ضرور آپ کی پیروی کریں گے اور کچھ لوگوں نے کہا کہ ہم بس اسی پر خوش ہیں اور یہیں مقیم رہیں گے۔‘‘(مسند احمد و کشف الأستار، حدیث : 2407 و مجمع الزوائد: 466/8 والمستدرک للحاکم، حدیث : 8200 اس کی سند ضعیف ہے)"],[4609,"§کفار کے حالات کا ذکر\nارشاد باری تعالیٰ ہے: ﴿وَ اِنَّ الَّذِيْنَ لَا يُؤْمِنُوْنَ بِالْاٰخِرَةِ عَنِ الصِّرَاطِ لَنٰكِبُوْنَ۰۰۷۴﴾ ’’اور بلاشبہ جو لوگ آخرت پر ایمان نہیں لاتے وہ سیدھے رستے سے الگ ہو رہے ہیں۔‘‘ یعنی یہ لوگ گم گشتہ راہ اور راہ راست سے بھٹکے ہوئے ہیں۔ عرب نَکَبَ فُلَانٌ عَنِ الطَّرِیقِ اس وقت کہتے ہیں جب کوئی رستے سے بھٹک جائے۔ ﴿وَ لَوْ رَحِمْنٰهُمْ وَ كَشَفْنَا مَا بِهِمْ مِّنْ ضُرٍّ لَّلَجُّوْا فِيْ طُغْيَانِهِمْ يَعْمَهُوْنَ۰۰۷۵﴾ ’’اور اگر ہم ان پر رحم کریں اور جو تکلیفیں ان کو پہنچ رہی ہیں دور کر دیں تو پھر بھی وہ اپنی سرکشی پر اڑے ہوئے بھٹکتے پھریں۔‘‘ اللہ تعالیٰ نے ان کے کفر کی سختی کو بیان کرتے ہوئے فرمایا ہے کہ اگر وہ ان کی تکلیف کو دور فرما دے اور انہیں قرآن کا فہم عطا فرما دے تو پھر بھی یہ نہیں مانیں گے بلکہ اپنے، کفر، سرکشی اور فساد پر ہی قائم رہیں گے جیسا کہ فرمایا: ﴿وَ لَوْ عَلِمَ اللّٰهُ فِيْهِمْ خَيْرًا لَّاَسْمَعَهُمْ١ؕ وَ لَوْ اَسْمَعَهُمْ لَتَوَلَّوْا وَّ هُمْ مُّعْرِضُوْنَ۰۰۲۳﴾ (الانفال : 23) ’’اور اگر اللہ ان میں بھلائی پاتا تو انہیں ضرور سننے کی توفیق بخشتا اور اگر انہیں سماعت دیتا تو پھر بھی وہ اعراض کرتے ہوئے پھر جاتے۔‘‘ اور فرمایا: ﴿وَ لَوْ تَرٰۤى اِذْ وُقِفُوْا عَلَى النَّارِ فَقَالُوْا يٰلَيْتَنَا نُرَدُّ وَ لَا نُكَذِّبَ بِاٰيٰتِ رَبِّنَا وَ نَكُوْنَ مِنَ الْمُؤْمِنِيْنَ۰۰۲۷ بَلْ بَدَا لَهُمْ مَّا كَانُوْا يُخْفُوْنَ مِنْ قَبْلُ١ؕ وَ لَوْ رُدُّوْا لَعَادُوْا لِمَا نُهُوْا عَنْهُ وَ اِنَّهُمْ لَكٰذِبُوْنَ۰۰۲۸ وَقَالُوْۤا اِنْ هِيَ اِلَّا حَيَاتُنَا الدُّنْيَا وَ مَا نَحْنُ بِمَبْعُوْثِيْنَ۠۰۰۲۹﴾ (الانعام : 29,27) ’’اور کاش! آپ (ان کو اس وقت) دیکھیں جب یہ آتش (جہنم کے کنارے) پر کھڑے کیے جائیں گے تو کہیں گے کہ اے کاش! ہم پھر (دنیا میں) لوٹا دیے جائیں اور ہم اپنے پروردگار کی آیتوں کی تکذیب نہ کریں گے اور مومنوں میں سے ہو جائیں گے۔ بلکہ ان کے لیے اس نے وہ ظاہر کر دیا جسے اس سے پہلے وہ چھپاتے تھے اور اگر یہ (دنیا میں) لوٹائے بھی جائیں تو جن (کاموں) سے ان کو منع کیا گیا تھا وہی پھر کرنے لگیں، کچھ شک نہیں کہ یہ جھوٹے ہیں اور کہتے ہیں کہ ہماری جو دنیا کی زندگی ہے بس یہی (زندگی) ہے اور ہم (مرنے کے بعد پھر) نہیں اٹھائے جائیں گے۔‘‘ اس کا تعلق اس باب سے ہے کہ اللہ تعالیٰ کو اس کا بھی علم ہے جو نہیں ہوگا اور اگر ہوگا تو کیسے ہوگا، ضحاک رحمہ اللہ نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ ہر وہ چیز جس کے لیے ﴿لَوْ﴾ استعمال کیا گیا ہے وہ کبھی بھی وقوع پذیر نہیں ہو گی۔\n﴿اَفَلَمْ يَدَّبَّرُوا الْقَوْلَ﴾ ’’کیا انہوں نے قرآن میں غور و فکر اور تدبر نہیں کیا؟‘‘ اگر انہوں نے قرآن میں تدبر کیا ہوتا تو وہ ان کے ایمان کا موجب اور ان کو کفر سے منع کرنے کا باعث بنتا، مگر ان پر جو مصیبت نازل ہوئی ہے اس کا سبب ان کا قرآن سے اعراض ہے اور یہ آیت اس امر کی دلیل ہے کہ قرآن میں تدبر و تفکر ہر بھلائی کی طرف دعوت دیتا ہے اور ہر برائی سے بچاتا ہے اور جس چیز نے ان کو قرآن میں غور و فکر کرنے سے روک رکھا ہے وہ یہ ہے کہ ان کے دلوں پر تالے پڑے ہوئے ہیں۔ ﴿اَمْ جَآءَهُمْ مَّا لَمْ يَاْتِ اٰبَآءَهُمُ الْاَوَّلِيْنَٞ۰۰۶۸﴾ یعنی یا اس بات نے ان کو ایمان لانے سے روک رکھا ہے کہ ان کے پاس رسول آیا اور ایک ایسی کتاب ان کے پاس آئی جو ان کے آباء و اجداد کے پاس نہیں آئی تھی لہٰذا یہ اپنے گمراہ آباء واجداد کی راہ پر چلنے پر راضی ہو گئے۔ جو چیز اس راہ کے خلاف تھی انہوں نے اس کی مخالفت کی لہٰذا انہوں نے اور ان جیسے دوسرے کفار نے یہی کہا تھا جس کے بارے میں اللہ تعالیٰ نے خبر دی ہے۔ ﴿وَ كَذٰلِكَ مَاۤ اَرْسَلْنَا مِنْ قَبْلِكَ فِيْ قَرْيَةٍ مِّنْ نَّذِيْرٍ اِلَّا قَالَ مُتْرَفُوْهَاۤ١ۙ اِنَّا وَجَدْنَاۤ اٰبَآءَنَا عَلٰۤى اُمَّةٍ وَّ اِنَّا عَلٰۤى اٰثٰرِهِمْ مُّقْتَدُوْنَ۰۰۲۳﴾ (الزخرف: 23) ’’اسی طرح آپ سے پہلے جس بستی میں بھی ہم نے کوئی ڈرانے والا بھیجا تو اس کے خوشحال لوگوں نے کہا ہم نے اپنے آباء و اجداد کو ایک طریقے پر پایا ہے ہم تو انہی کی پیروی کر رہے ہیں۔‘‘ اور ان کے جواب میں ہر رسول نے فرمایا: ﴿اَوَ لَوْ جِئْتُكُمْ بِاَهْدٰى مِمَّا وَجَدْتُّمْ عَلَيْهِ اٰبَآءَكُمْ١ؕ﴾ (الزخرف: 24) ’’کیا تم اسی طریقے پر چلتے چلے جائو گے خواہ میں تمہیں اس راستے سے بہتر راستہ بتائوں جس پر تم نے آباء و اجداد کو پایا ہے۔‘‘ اگر تمہارا مقصد حق جوئی ہے تو کیا تم اس کی پیروی کرو گے؟ اور انہوں نے اپنی نیتوں کے مطابق جواب دیا: ﴿اِنَّا بِمَاۤ اُرْسِلْتُمْ بِهٖ كٰفِرُوْنَ۰۰۲۴﴾ (الزخرف: 24) ’’بلاشبہ تمہیں جس چیز کے ساتھ بھیجا گیا ہے ہم اس کا انکار کرتے ہیں۔‘‘\nاگر یہ کہا جائے کہ حق ان کی خواہشات نفس کے موافق کیوں نہیں تاکہ وہ ایمان لے آتے اور جلدی سے حق کی اطاعت کرتے تو اللہ تعالیٰ نے اس کا یوں جواب عطا فرمایا: ﴿وَ لَوِ اتَّبَعَ الْحَقُّ اَهْوَآءَهُمْ لَفَسَدَتِ السَّمٰوٰتُ وَ الْاَرْضُ﴾ ’’اگر حق (دین) ہی ان کی خواہشات کی پیروی کرنے لگ جائے، تو آسمانوں اور زمین کا سارا نظام ہی درہم برہم ہو جائے۔‘‘ اور اس کی وجہ یہ ہے کہ ان کی خواہشات نفس، ظلم، کفر اور فساد پر مبنی اخلاق و اعمال سے متعلق ہوتی ہیں۔ پس اگر حق ان کی خواہشات کی پیروی کرنے لگے تو آسمان و زمین ظلم اور عدم عدل پر مبنی تدبیر و تصرف کی وجہ سے فساد کا شکار ہو جائیں، اس لیے کہ آسمان اور زمین تو صرف حق و عدل کی بنا پر درست ہیں۔\n﴿بَلْ اَتَيْنٰهُمْ بِذِكْرِهِمْ﴾ یعنی ہم ان کے پاس یہ قرآن لے کر آئے جو ان کو ہر قسم کی بھلائی کی نصیحت کرتا ہے۔ یہ ان کا فخر و شرف ہے۔ اگر وہ اس کو قائم کریں گے تو لوگوں کی سیادت کریں گے۔ ﴿فَهُمْ عَنْ ذِكْرِهِمْ مُّعْرِضُوْنَؕ۰۰۷۱﴾ ’’وہ اپنے ذکر (نصیحت) سے روگردانی کر رہے ہیں۔‘‘ اپنی بد بختی اور عدم توفیق کی وجہ سے ﴿نَسُوا اللّٰهَ فَنَسِيَهُمْ١ؕ﴾ (التوبۃ: 67) ’’انہوں نے اللہ کو بھلا دیا تو اللہ نے بھی ان کو فراموش کر دیا۔‘‘ ﴿نَسُوا اللّٰهَ فَاَنْسٰىهُمْ اَنْفُسَهُمْ١ؕ﴾ (الحشر: 19) ’’انہوں نے اللہ کو بھلا دیا اور اللہ نے ان کو اپنے تئیں بھلوا دیا۔‘‘ پس قرآن عظیم اور اس کو لانے والی ہستی سب سے بڑی نعمت ہے جو اللہ تعالیٰ نے ان کو عطا کی ہے مگر انہوں نے اس عظیم نعمت کو ٹھکرا دیا اور اس سے روگردانی کی۔ کیا اس ایمان سے محرومی کے بعد، اس سے بڑی کوئی حرماں نصیبی ہے؟ اور کیا اس کے پیچھے انتہائی درجے کا خسارہ نہیں؟\n﴿اَمْ تَسْـَٔلُهُمْ خَرْجًا﴾ اے محمد صلی اللہ علیہ وسلم ! کیا ان کو آپ کی اتباع سے اس چیز نے روکا ہے کہ آپ ان سے اس کام پر کوئی اجرت طلب کرتے ہیں؟ ﴿فَهُمْ مِّنْ مَّغْرَمٍ مُّثْقَلُوْنَؕ۰۰۴۰﴾ (الطور: 40) ’’کہ ان پر تاوان کا بوجھ پڑ رہا ہے۔‘‘ اور اس طرح آپ کی اطاعت سے ان کو تکلیف پہنچتی ہے کیونکہ آپ صلی اللہ علیہ وسلم ان سے اجرت اور خراج طلب کرتے ہیں؟ معاملہ یوں نہیں بلکہ ﴿فَخَرَاجُ رَبِّكَ خَيْرٌ١ۖۗ وَّ هُوَ خَيْرُ الرّٰزِقِيْنَ۰۰۷۲﴾ ’’آپ کے رب کی اجرت بہت بہتر ہے اور وہ بہترین روزی رساں ہے۔‘‘ یہ اسی کا قول ہے جس طرح انبیاء کرام علیہم السلام نے اپنی اپنی قوم سے فرمایا: ﴿يٰقَوْمِ لَاۤ اَسْـَٔلُكُمْ عَلَيْهِ اَجْرًا١ؕ﴾ (ہود: 51) ’’اے میری قوم میں اس پر تم سے کوئی اجر نہیں مانگتا۔‘‘ ﴿اِنْ اَجْرِيَ اِلَّا عَلَى اللّٰهِ﴾ (ہود: 29) ’’میرا صلہ تو اللہ کے پاس ہے۔‘‘ یعنی انبیائے کرام علیہم السلام کی طرف سے لوگوں کو دعوت دینے میں یہ لالچ نہیں ہوتا کہ انہیں لوگوں کی طرف سے مال و دولت حاصل ہوگا۔ وہ تو صرف خیر خواہی اور ان کے اپنے فائدے کی خاطر ان کو دعوت دیتے ہیں بلکہ انبیاء و مرسلین مخلوق کے لیے، خود ان سے بھی زیادہ خیر خواہ ہیں۔ پس اللہ تعالیٰ ان کو ان کی امتوں کی طرف سے جزائے خیر عطا کرے اور تمام احوال میں ہمیں بھی ان کی اقتداء سے بہرہ مند کرے۔"],[4610,"§حق لوگوں کی خواہشات کا تابع نہیں\nاگر اللہ تعالیٰ یا اللہ تعالیٰ کے احکام عام لوگوں کی خواہشات کے مطابق نازل ہوں اور اللہ تعالیٰ لوگوں کی خواہشات کے مطابق احکام نازل کرے تو اللہ تعالیٰ مالک و مختار رہ کہاں گیا؟ اس صورت میں تو اللہ تعالیٰ (معاذ اللہ) بندوں کے ہاتھوں میں کٹھ پتلی بن گیا۔ پھر خواہشات بھی ہر شخص کی الگ الگ ہیں اور ایک دوسرے کی خواہشات سے ٹکراتی ہیں اس بات کو ایک سادہ سی کہانی سے بخوبی سمجھا جا سکتا ہے۔ کہتے ہیں ایک آدمی کی دو بیٹیاں تھیں۔ اس نے اپنی ایک بیٹی کا نکاح ایک زمین دار لڑکے سے کر دیا اور دوسری کا ایک کمہار سے۔ ایک دفعہ وہ اپنی بیٹیوں سے ملنے گیا۔ پہلے بڑی بیٹی کے ہاں گیا تو وہ کہنے لگے۔ ابا جان! کافی عرصہ سے بارش نہیں ہو رہی فصل کو پانی کی شدید ضرورت ہے۔ آپ اللہ سے دعا کریں کہ وہ رحمت کی بارش برسا دے۔ ورنہ اگر فصل نہ ہوئی تو ہم تو بھوکوں مر جائیں گے۔ اس نے بیٹی سے دعا کا وعدہ کیا۔ پھر دوسری بیٹی کے ہاں گیا۔ تو وہ کہنے لگی: ابا جان! ابھی ابھی ہم نے برتنوں والا آوا چڑھایا ہے۔ آپ اللہ سے دعا کریں کہ ابھی کچھ مدت بارش نہ ہو۔ اگر بارش ہو گئی تو ہمارا بہت نقصان ہو جائے گا‘‘ وہ اس کی بات سن کر کہنے لگا: ’’یا اللہ! جیسے تیری مرضی ہے ویسے ہی کر۔ اپنے کاموں کو تو ہی بہتر جانتا ہے۔‘‘\nاب اگر مشرکوں کی خواہش کا اتباع کیا جائے تو ان کی تو یہ خواہش ہے کہ ان کے معبودوں کو تصرف امور میں شریک سمجھا ہی نہ جائے بلکہ بنا بھی دیا جائے۔ اب بتائیے کہ اس صورت میں یہ نظام کائنات ایک ساعت بھی قائم رہ سکتا ہے؟ ایک گھر میں دو منتظم یا ایک مملکت میں دو بادشاہ بھی سما نہیں سکتے تو کیا اس کائنات میں مشرکوں کے سینکڑوں خدائوں کی خدائی سے کائنات کا نظام ایک منٹ بھی چل سکتا ہے۔ حق صرف اس لیے حق ہے کہ لوگ اس کی اتباع کریں نہ یہ کہ حق لوگوں کی خواہشات کی اتباع کرنے لگے اور اگر بفرض محال ایسی صورت ہو تو کوئی بات بھی حق نہ رہے گی۔"],[4611,"§قرآن کی تاثیر: عتبہ بن ربیعہ پر قرآن کی آیات کا اثر\nاس کا ایک مطلب تو یہ ہے کہ ہم نے ان کی طرف قرآن اس لیے نازل کیا تھا کہ وہ ہدایت حاصل کرتے۔ جیسا کہ کفارِ مکہ کہا کرتے تھے کہ اگر ذکر ہماری طرف نازل کیا جائے تو ہم یقیناً دوسری سب قوموں سے زیادہ ہدایت یافتہ ہو جائیں گے۔ (157:6) پھر جب ذکر ان کے پاس آ گیا تو بجائے اس کے کہ اسے قبول کر لیتے اس سے اِعراض کرنے لگے۔\nدوسرا مطلب یہ ہے کہ یہاں ذکر سے مراد عزو شرف ہے اور یہ معنی بھی اکثر مفسرین نے اختیار کیا ہے یعنی ہم نے یہ ذکر تمہاری ہی زبان میں نازل کیا تاکہ تم اسے خوب سمجھ سکو پھر رسول نے تمہیں واضح طور پر بتا دیا کہ اگر تم اس کی تعلیم پر عمل کرو گے تو تم عرب و عجم کے حکمران بن جائو گے اور اس کی تائید اس واقعہ سے بھی ہوتی ہے کہ ایک دفعہ عتبہ بن ربیعہ، جو ایک معزز قریشی سردار، نہایت بہادر اور فطرتاً نیک دل انسان تھا۔ حرم میں بیٹھ کر اپنے دوسرے ساتھیوں سے کہنے لگا کہ میں محمد صلی اللہ علیہ وسلم سے کچھ باتیں کہنا چاہتا ہوں۔ امید ہے وہ ان میں سے ایک نہ ایک ضرور قبول کر لے گا اور اگر اس نے قبول کر لی تو ہم اس مصیبت سے نجات حاصل کر سکیں گے۔\nمشرکوں نے کہا: ابو الولید! ضرور یہ کام کرو۔ چنانچہ آپ صلی اللہ علیہ وسلم کے پاس آکر اس نے چند باتیں پیش کیں۔ جن کی تفصیل کا یہ موقعہ نہیں۔ ان سب باتوں کے جواب میں آپ نے سورہ حم السجدہ کی چند آیات پڑھیں جنہیں عتبہ چپ چاپ سنتا رہا۔ جب آپ صلی اللہ علیہ وسلم اس آیت پر پہنچے: ﴿فَاِنْ اَعْرَضُوْا فَقُلْ اَنْذَرْتُكُمْ صٰعِقَةً مِّثْلَ صٰعِقَةِ عَادٍ وَّ ثَمُوْدَؕ۰۰۱۳﴾ (حٰمٓ السجدۃ:13) ’’یعنی اگر یہ لوگ اعراض کریں تو آپ کہہ دیجئے کہ میں تمہیں عاد و ثمود کی کڑک جیسی ایک کڑک کے خطرہ سے آگاہ کر رہا ہوں۔‘‘ تو عتبہ کے آنسو بہنے لگے اور آپ کے منہ پر ہاتھ رکھ دیا۔ قرآن کی یہ آیات اس کے دل کو خوب متاثر کر رہی تھیں اور اسے یہ خطرہ محسوس ہونے لگا کہ کہیں ایسا عذاب اسی وقت نہ آن پڑے۔ وہ چپ چاپ وہاں سے اٹھ کھڑا ہوا۔ مگر اب وہ پہلا عتبہ نہ رہا تھا۔ جا کر قریشیوں سے کہنے لگا: محمد صلی اللہ علیہ وسلم جو کلام پیش کرتا ہے وہ شاعری نہیں کچھ اور ہی چیز ہے تم اسے اس کے حال پر چھوڑ دو۔ اگر وہ عرب پر غالب آ گیا تو اس میں تمہاری ہی عزت ہے اور اگر وہ خود ہی ختم ہو گیا تو یہی کچھ تم چاہتے ہو‘‘ وہ کہنے لگے: ’’ابو الولید! معلوم ہوتا ہے تم پر بھی اس کا جادو چل گیا۔ (تفسیر ابن کثیر، ج : 6، د: 159 تا 161)\nمگر جب یہ عزو شرف بخشنے والا ذکر آ گیا تو انہوں نے اس سے اعراض اور نفرت کا اظہار شروع کر دیا۔"],[4612,"§سیدھی راہ سے مراد\nیعنی وہ ایسی موٹی باتیں ہیں جو ہر پیغمبر پر وحی کی جاتی رہی ہیں۔ ان میں کوئی ایچ پیچ نہیں۔ کوئی پیچیدگی اور ابہام نہیں۔ ان کے دلائل نہایت سادہ اور عام فہم ہیں۔ جو ایک دیہاتی اور بدو کو بھی متاثر کر دیتے ہیں۔ ان کے سمجھنے کے لیے کسی لمبی چوڑی تعلیم کی بھی ضرورت نہیں۔ مثلاٍ ایک بدو سے کسی نے پوچھا کہ کیا اللہ تعالیٰ کی ہستی موجود ہے؟‘‘ کہنے لگا: ’’ہاں ہے! پوچھنے والے نے دوبارہ سوال کیا ’’بھلا کیسے؟‘‘ بدو کہنے لگا: اگر ہم راہ میں کوئی اونٹ کی مینگنی پڑی دیکھیں تو ہم اندازہ لگا لیتے ہیں کہ یہاں سے یقیناً کوئی اونٹ گزرا ہے۔ اسی طرح جب ہم یہ کائنات کا اتنا وسیع کارخانہ دیکھتے ہیں تو لازماً اس نتیجہ پر پہنتے ہیں کہ اس کا کوئی بنانے والا ضرور ہونا چاہیے۔‘‘\nاسی طرح ہم دیکھتے ہیں کہ ایک گھر میں دو حاکم ہوں تو اس کا نظام کبھی درست نہیں رہتا پھر یہ کیسے ممکن ہے کہ اس کائنات میں اللہ کے سوا کچھ اور بھی مالک و مختار ہوں؟ اگر ایسی صورت ہو تو کائنات کا نظام تو ایک دن بھی نہ چل سکے۔\nاسی طرح ہم یہ بھی دیکھتے ہیں کہ اللہ تعالیٰ ہر وقت اور ہر زمانہ میں مردہ سے زندہ اور زندہ سے مردہ پیدا کرتا رہتا ہے۔ انسان جو غذائیں کھاتا ہے سب بے جان ہیں۔ کئی مراحل کے بعد انہیں غذائوں سے نطفہ بنتا ہے۔ پھر اسی نطفہ سے ایک جیتا جاگتا انسان پیدا ہو جاتا ہے۔ جس میں اس کے ماں باپ کے خصائل و عادات اور نقش وغیرہ تک کی جھلک موجود ہوتی ہے۔ اسی سے بآسانی اندازہ لگایا جا سکتا ہے۔ جو کام اس دنیا میں ہر آن ہمارے سامنے ہو رہے ہیں وہ آخر انسان کی موت کے بعد کیوں نا ممکن ہیں۔ غرض دین کی اصولی تعلیمات پر غور فرمائیے تو سب باتیں سیدھی، سادہ اور عام فہم نظر اائیں گی اور یہی اصولی باتیں ہی اللہ کی سیدھی راہ ہے۔\nسمر کے اصل معنی ہیں چاندنی، عام طور پر چاند راتوں میں کعبے کے ارد گرد بیٹھ کر کفار مکہ باتیں کرتے تھے۔ اس لیے یہ لفظ راتوں کی گفتگو کے لیے استعمال ہونے لگ گیا۔ یہاں اس کے معنی خاص طور پر ان باتوں کے ہیں جو قرآن کریم اور نبی اکرم صلی اللہ علیہ وسلم کے بارے میں وہ کرتے تھے اور اس کی بنا پر وہ حق کی بات سننے اور اسے قبول کرنے سے انکار کر دیتے یعنی چھوڑ دیتے اور بعض نے ہجر کے معنی ہذیان گوئی اور بعض نے فحش گوئی کے کیے ہیں۔ یعنی راتوں کی گفتگو میں تم قرآن کی شان میں ہذیان بکتے ہو یا بے ہودہ اور فحش باتیں کرتے ہو جن میں کوئی بھلائی نہیں۔ (فتح القدیر)\nاَمْ لَمْ یَعْرِفُوْا رَسُوْلَہُمْ فَہُمْ لَہٗ مُنْکِرُوْنَ: مزید کفار مکہ کو تہدید آمیز انداز میں مخاطب کرتے ہوئے کہا جا رہا ہے کہ یہ لوگ آخر الزمان پیغمبر جناب محمد صلی اللہ علیہ وسلم کے بارے میں اچھی طرح جانتے ہیں کہ وہ ان میں امانت داری، سچائی اور اخلاق حسنہ کے اوصاف کے ساتھ موصوف اور مشہور ہیں، نسب کے لحاظ سے بھی اس کا مقام اونچا ہے تعجب ہے! کہ کفار مکہ نے ان سبھی اوصاف کے باوجود انہیں دیوانہ قرار دیا، جبکہ معاشرہ میں آپ امانت اور سچائی کے وصف کے ساتھ جانے پہچانے جاتے ہیں، مزید عقل و بصیرت کے لحاظ سے آپ صلی اللہ علیہ وسلم کا مقام بہت اونچا ہے اور ذہن کے لحاظ سے بھی روشن ضمیر ہیں اور زیرک باور کیے جاتے ہیں اسی لیے اس کے بعد وضاحت ہے۔\nاَمْ یَقُوْلُوْنَ بِہٖ جِنَّۃٌ: تعجب ہے کہ وہ محمد صلی اللہ علیہ وسلم کو دیوانہ قرار دے رہے ہیں اس جملہ پر نہ صرف یہ کہ انہیں اس جملہ کے باعث ڈانٹ پلائی جا رہی ہے بلکہ ان کی دشمنی پر حیرت و استعجاب کا اظہار کیا گیا ہے اللہ تعالیٰ ان کی اس بات کی تردید کرتے ہوئے وضاحت فرما رہے ہیں ان کے سبھی الزامات اس لائق ہیں کہ ان کی جانب توجہ ہی نہ کی جائے جبکہ حقیقت یہ ہے کہ محمد صلی اللہ علیہ وسلم ان کے پاس واضح سچائی کو لائے ہیں جس میں ہرگز باطل کا شائبہ تک بھی نہیں ہے جبکہ قرآن پاک توحید اور اسلام کے احکام پر مشتمل ہے اس کے باوجود اکثریت ان لوگوں کی ہے جو حق و صداقت کا انکار کر رہے ہیں ان کے انکار کا باعث ان کے دلوں میں ٹیڑھا پن ہے، ابو طالب کے دو اشعار ملاحظہ فرمائیں:\nفَوَاللہِ لَولَا اَنْ اَجِیءَ بِسُبَّۃٍ\nتَجُرُّ عَلٰی اَشْیَاخِنَا فِی الْقَبَائِلِ\nاِذًا لَاتَّبَعْنَاہُ عَلٰی کُلِّ حَالَۃٍ\nمِنَ الدَّھْرِ جِدًّا غَیْرَ قَوْلِ التَّکَاذُلِ\n’’اللہ کی قسم! اگر مجھے گالی گلوچ کا خطرہ نہ ہوتا کہ ہمارے بڑے اس کی زد میں آتے تو ہم اس پیغمبر کی ضرور تابع داری کرتے یہ بات پختہ ہے مزاحیہ انداز نہیں ہے معلوم ہوا وہ بلاشبہ اپنے آبائو اجداد کے دین کو چھوڑنے کو اپنے لیے عار تصور کرتے تھے وگرنہ اسلام کی حقانیت کے منکر نہ تھے۔‘‘\nاگر توحید جس کو وہ ناپسند گردانتے ہیں ان کی خواہشات کے موافق ہو جائے تو عالم کا علوی سفلی سبھی نظام ختم ہو جائے گا اور سبھی مخلوقات بھی اپنے فاسدانہ اختلاف کے باعث موت سے ہم کنار ہو جائے، مقصود یہ ہے کہ انسان عاجز ہے جبکہ اللہ تعالیٰ کی ذات جو اپنے سبھی اوصاف اور افعال اور تدبیر کے لحاظ سے کامل اور مکمل ہے بلکہ ہم نے انہیں قرآن پاک سے نوازا ہے لیکن لوگ اس سے روگردانی کر رہے ہیں جبکہ ان کے لیے ضروری تھا کہ وہ قرآن پاک کے احکام کی اطاعت کرتے لیکن وہ اس سے روگردانی کر رہے ہیں حالانکہ اس کی اطاعت ان کے لیے شرف سے وابستہ تھی۔\nاَمْ تَسْئَلُہُمْ خَرْجًا: اے محمد! صلی اللہ علیہ وسلم کیا آپ ان سے رسالت کی تبلیغ پر اجرت کا مطالبہ کر رہے ہیں تو اس وجہ سے وہ ایمان قبول نہیں کر رہے ہیں اس جملہ کے مفہوم میں بوجہ ان کے ایمان نہ لانے کے انہیں معیوب قرار دیا ہے جبکہ محمد صلی اللہ علیہ وسلم رسالت کے احکام کے پہنچانے پر ان سے اجرت کا مطالبہ نہیں کر رہے ہیں تو پھر کیوں اسے جھوٹا قرار دے رہے ہیں؟ اور اس کے ساتھ دشمنی کر رہے ہیں جبکہ اصلی حقیقت یہ ہے کہ رسالت کی تبلیغ پر اللہ پاک کی جانب سے جو عطیہ آپ صلی اللہ علیہ وسلم کو حاصل ہوگا وہ آپ صلی اللہ علیہ وسلم کے لیے بہتر ہے اور یہ حقیقت ہے کہ سبھی عطیات دینے والوں سے اللہ تعالیٰ زیادہ عظمت اور شرف کے ساتھ موصوف ہے اس لیے کہ اللہ پاک کا عطیہ سے نوازنا ہرگز کسی ضرورت کے پیش نظر نہیں ہے جبکہ اللہ پاک کی ذات کے علاوہ کوئی بھی شخص جب کسی کو عطیہ سے نوازتا ہے تو اس کے ذہن میں لازماً کوئی نہ کوئی آرزو خوابیدہ ہوتی ہے اور یہ حقیقت بھی مسلمہ ہے کہ آپ ان کو اسلام کی جانب دعوت دے رہے ہیں اور اسلام ہی کا راستہ صراط مستقیم ہے جو جنت (Paradise) میں داخل کرے گا اور اس حقیقت سے بھی انکار ممکن نہیں کہ جو لوگ مرنے کے بعد اٹھائے جانے اور جزاء سزا کے عمل کو تسلیم نہیں کرتے ہیں وہ صراط مستقیم کی راہ پر رواں دواں نہیں ہیں۔\nوَلَوْ رَحِمْنٰہُمْ وَکَشَفْنَا مَا بِھِمْ مِّنْ ضُرٍّ: اگر ہم ان مشرکین پر بفرض محال رحیمانہ انداز اختیار کر لیتے ہیں جنہوں نے آپ کو جھوٹا قرار دیا اور آپ کے ساتھ دشمنی پر اصرار کیا اور انہیں قحط سالی سے تحفظ عطا کریں گے اور دیگر مصائب کو بھی ختم کردیں گے تو گمراہی پر برقرار رہیں گے حدود الٰہیہ سے تجاوز کریں گے اس کیفیت میں بظاہر وہ مخبوط الحواس دکھائی دیں گے۔\nوَ لَقَدْ اَخَذْنٰهُمْ بِالْعَذَابِ فَمَا اسْتَكَانُوْا لِرَبِّهِمْ وَ مَا يَتَضَرَّعُوْنَ۰۰۷۶ حَتّٰۤى اِذَا\nفَتَحْنَا عَلَيْهِمْ بَابًا ذَا عَذَابٍ شَدِيْدٍ اِذَا هُمْ فِيْهِ مُبْلِسُوْنَؒ۰۰۷۷ وَ هُوَ الَّذِيْۤ اَنْشَاَ\nلَكُمُ السَّمْعَ وَ الْاَبْصَارَ وَ الْاَفْـِٕدَةَ١ؕ قَلِيْلًا مَّا تَشْكُرُوْنَ۰۰۷۸ وَ هُوَ الَّذِيْ ذَرَاَكُمْ فِي\nالْاَرْضِ وَ اِلَيْهِ تُحْشَرُوْنَ۰۰۷۹ وَ هُوَ الَّذِيْ يُحْيٖ وَ يُمِيْتُ وَ لَهُ اخْتِلَافُ الَّيْلِ\nوَالنَّهَارِ١ؕ اَفَلَا تَعْقِلُوْنَ۰۰۸۰ بَلْ قَالُوْا مِثْلَ مَا قَالَ الْاَوَّلُوْنَ۰۰۸۱ قَالُوْۤا ءَاِذَا\nمِتْنَا وَ كُنَّا تُرَابًا وَّ عِظَامًا ءَاِنَّا لَمَبْعُوْثُوْنَ۠۰۰۸۲ لَقَدْ وُعِدْنَا نَحْنُ وَ اٰبَآؤُنَا هٰذَا\nمِنْ قَبْلُ اِنْ هٰذَاۤ اِلَّاۤ اَسَاطِيْرُ الْاَوَّلِيْنَ۰۰۸۳\nاور بلاشبہ ہم نے انھیں عذاب میں پکڑا تھا، پھر نہ انھوں نے اپنے رب کے سامنے عاجزی کی اور نہ وہ گڑ گڑائے حتی کہ جب ہم نے ان پر سخت عذاب کا دروازہ کھول دیا تو وہ اس میں نا امید ہو گئے اور وہی (اللہ) ہے جس نے تمھارے لیے کان اور آنکھیں اور دل پیدا کیے، تم قلیل ہی شکر کرتے ہو اور وہی ہے جس نے تمھیں زمین پھیلایا، اور اسی کی طرف تمھیں اکٹھا کیا جائے گا اور وہی ہے جو زندہ کرتا اور مارتا ہے اور رات اور دن کا اختلاف اسی کا (پیدا کیا ہوا) ہے، کیا پھر بھی تم نہیں سمجھتے؟ بلکہ انھوں نے وہی کچھ کہا جو (ان سے) پہلوں نے کہا تھا انھوں نے کہا: کیا جب ہم مر گئے اور مٹی اور ہڈیاں ہو گئے، تو کیا ہمیں (دوبارہ) زندہ کر کے اٹھایا جائے گا؟, بلاشبہ اسی بات کا ہم سے اور ہم سے پہلے ہمارے آبائو اجداد سے وعدہ\nہوتا آیا ہے، یہ تو محض پہلے لوگوں کے افسانے ہیں."]])